window.RECALL_ORGANIC = {"chapters":[{"title":"第一章 绪论","questions":[{"type":"D","stem":"名词解释：有机化合物","answer":"含碳元素的化合物，绝大多数还含氢，并可含氧、氮、硫、卤素等；以共价键为主，普遍存在同分异构现象。一氧化碳、二氧化碳、碳酸盐、氰化物等性质近无机物，通常归无机化学讨论。","rationale":"出自概念手册「绪论」核心概念；背完后可对照该单元的可背诵版核对。","id":"rgo01_q001","chapter":"第一章 绪论","chapterIdx":0,"num":1},{"type":"D","stem":"名词解释：有机化学","answer":"研究有机化合物的组成、结构、性质及相互转化规律的科学；任务包括分离提纯、结构测定、性质研究、反应机理探讨与有机合成，是药物化学和生命科学的基础。","rationale":"出自概念手册「绪论」核心概念；背完后可对照该单元的可背诵版核对。","id":"rgo01_q002","chapter":"第一章 绪论","chapterIdx":0,"num":2},{"type":"D","stem":"名词解释：烃类化合物","answer":"仅由碳和氢两种元素组成的有机化合物，如甲烷、乙烯、苯。烃是有机物的母体，其他有机物可看作烃分子中的氢被各种官能团取代后的衍生物。","rationale":"出自概念手册「绪论」核心概念；背完后可对照该单元的可背诵版核对。","id":"rgo01_q003","chapter":"第一章 绪论","chapterIdx":0,"num":3},{"type":"D","stem":"名词解释：官能团","answer":"决定有机化合物主要化学性质的原子或原子团，如羟基、羰基、羧基、氨基、卤素、碳碳双键等；同系物官能团相同，故化学性质相似而物理性质递变。","rationale":"出自概念手册「绪论」核心概念；背完后可对照该单元的可背诵版核对。","id":"rgo01_q004","chapter":"第一章 绪论","chapterIdx":0,"num":4},{"type":"F","stem":"填空题：决定有机化合物主要化学性质的原子或原子团，如羟基、羰基、羧基、氨基、卤素、碳碳双键等；同系物______相同，故化学性质相似而物理性质递变。","answer":"官能团","rationale":"出自概念手册「绪论」核心概念：官能团。","id":"rgo01_q005","chapter":"第一章 绪论","chapterIdx":0,"num":5},{"type":"D","stem":"名词解释：同分异构现象","answer":"分子式相同而结构不同、性质也不同的现象，是有机化合物数目众多的重要原因；分为构造异构与立体异构两大类。","rationale":"出自概念手册「绪论」核心概念；背完后可对照该单元的可背诵版核对。","id":"rgo01_q006","chapter":"第一章 绪论","chapterIdx":0,"num":6},{"type":"D","stem":"名词解释：构造异构","answer":"分子式相同、原子或基团的连接顺序和方式不同的异构，包括碳链异构、位置异构和官能团异构，如乙醇与二甲醚。","rationale":"出自概念手册「绪论」核心概念；背完后可对照该单元的可背诵版核对。","id":"rgo01_q007","chapter":"第一章 绪论","chapterIdx":0,"num":7},{"type":"D","stem":"名词解释：分子式","answer":"用元素符号表示分子中所含原子种类和数目的式子，如C2H6O；确定分子式需先由元素分析得实验式，再测定相对分子质量。","rationale":"出自概念手册「绪论」核心概念；背完后可对照该单元的可背诵版核对。","id":"rgo01_q008","chapter":"第一章 绪论","chapterIdx":0,"num":8},{"type":"F","stem":"填空题：用元素符号表示分子中所含原子种类和数目的式子，如C2H6O；确定______需先由元素分析得实验式，再测定相对分子质量。","answer":"分子式","rationale":"出自概念手册「绪论」核心概念：分子式。","id":"rgo01_q009","chapter":"第一章 绪论","chapterIdx":0,"num":9},{"type":"D","stem":"名词解释：实验式","answer":"又称最简式，表示分子中各元素原子个数最简整数比的式子，如乙酸的实验式为CH2O；实验式乘以整数倍才是分子式。","rationale":"出自概念手册「绪论」核心概念；背完后可对照该单元的可背诵版核对。","id":"rgo01_q010","chapter":"第一章 绪论","chapterIdx":0,"num":10},{"type":"F","stem":"填空题：又称最简式，表示分子中各元素原子个数最简整数比的式子，如乙酸的______为CH2O；实验式乘以整数倍才是分子式。","answer":"实验式","rationale":"出自概念手册「绪论」核心概念：实验式。","id":"rgo01_q011","chapter":"第一章 绪论","chapterIdx":0,"num":11},{"type":"D","stem":"名词解释：元素分析","answer":"测定有机化合物元素组成的方法。定性分析常用钠熔法使氮、硫、卤素转变为可溶性无机离子后检出；定量分析用燃烧法测定碳和氢，近代多用元素分析仪。","rationale":"出自概念手册「绪论」核心概念；背完后可对照该单元的可背诵版核对。","id":"rgo01_q012","chapter":"第一章 绪论","chapterIdx":0,"num":12},{"type":"F","stem":"填空题：测定有机化合物元素组成的方法。定性分析常用钠熔法使氮、硫、卤素转变为可溶性无机离子后检出；定量分析用燃烧法测定碳和氢，近代多用______仪。","answer":"元素分析","rationale":"出自概念手册「绪论」核心概念：元素分析。","id":"rgo01_q013","chapter":"第一章 绪论","chapterIdx":0,"num":13},{"type":"D","stem":"名词解释：构造式","answer":"表示分子中原子或基团连接顺序及成键情况的式子，又称结构式；只反映连接关系，不表示空间构型与构象。","rationale":"出自概念手册「绪论」核心概念；背完后可对照该单元的可背诵版核对。","id":"rgo01_q014","chapter":"第一章 绪论","chapterIdx":0,"num":14},{"type":"D","stem":"名词解释：键线式","answer":"用折线表示碳骨架的式子，折点和端点代表碳原子，碳上的氢按四价补齐而省略，杂原子及其所连的氢必须写出。","rationale":"出自概念手册「绪论」核心概念；背完后可对照该单元的可背诵版核对。","id":"rgo01_q015","chapter":"第一章 绪论","chapterIdx":0,"num":15},{"type":"D","stem":"名词解释：示性式","answer":"把同类原子或基团合并书写、以突出官能团的式子，如乙醇写作C2H5OH、乙酸写作CH3COOH，便于看出化合物的类别。","rationale":"出自概念手册「绪论」核心概念；背完后可对照该单元的可背诵版核对。","id":"rgo01_q016","chapter":"第一章 绪论","chapterIdx":0,"num":16},{"type":"D","stem":"名词解释：分离提纯","answer":"从混合物中获得纯组分的过程，是有机物研究的第一步；常用蒸馏、分馏、重结晶、萃取、升华和色谱等方法，依沸点、溶解度或分配系数的差异选择。","rationale":"出自概念手册「绪论」核心概念；背完后可对照该单元的可背诵版核对。","id":"rgo01_q017","chapter":"第一章 绪论","chapterIdx":0,"num":17},{"type":"D","stem":"名词解释：重结晶","answer":"利用固体有机物在溶剂中的溶解度随温度升高而显著增大的性质提纯的方法：热饱和溶液冷却析出晶体，杂质留在母液中，适用于杂质含量不高的固体。","rationale":"出自概念手册「绪论」核心概念；背完后可对照该单元的可背诵版核对。","id":"rgo01_q018","chapter":"第一章 绪论","chapterIdx":0,"num":18},{"type":"D","stem":"名词解释：蒸馏","answer":"利用液体混合物中各组分沸点不同而分离的方法；沸点差较大时用简单蒸馏，沸点相近时用分馏，减压蒸馏适用于高沸点或热敏性物质。","rationale":"出自概念手册「绪论」核心概念；背完后可对照该单元的可背诵版核对。","id":"rgo01_q019","chapter":"第一章 绪论","chapterIdx":0,"num":19},{"type":"F","stem":"填空题：利用液体混合物中各组分沸点不同而分离的方法；沸点差较大时用简单______，沸点相近时用分馏，减压蒸馏适用于高沸点或热敏性物质。","answer":"蒸馏","rationale":"出自概念手册「绪论」核心概念：蒸馏。","id":"rgo01_q020","chapter":"第一章 绪论","chapterIdx":0,"num":20},{"type":"D","stem":"名词解释：萃取","answer":"利用溶质在两种互不相溶的溶剂中分配系数不同，把溶质从原溶剂转移到另一溶剂中的分离方法；常用分液漏斗以水与有机溶剂配对进行。","rationale":"出自概念手册「绪论」核心概念；背完后可对照该单元的可背诵版核对。","id":"rgo01_q021","chapter":"第一章 绪论","chapterIdx":0,"num":21},{"type":"D","stem":"名词解释：色谱法","answer":"利用各组分在固定相与流动相之间吸附、分配或离子交换能力的差异，随流动相移动速度不同而分离的方法，适合微量及性质相近组分的分离。","rationale":"出自概念手册「绪论」核心概念；背完后可对照该单元的可背诵版核对。","id":"rgo01_q022","chapter":"第一章 绪论","chapterIdx":0,"num":22},{"type":"D","stem":"名词解释：质谱法","answer":"用高能电子流轰击分子使其电离并断裂，按质荷比分离和记录离子峰的方法；可测定相对分子质量、确定分子式并推测结构片段。","rationale":"出自概念手册「绪论」核心概念；背完后可对照该单元的可背诵版核对。","id":"rgo01_q023","chapter":"第一章 绪论","chapterIdx":0,"num":23},{"type":"D","stem":"名词解释：红外光谱","answer":"分子吸收红外光引起振动能级跃迁而形成的吸收光谱，不同官能团在特定波数出现特征吸收峰，是鉴定官能团最常用的方法。","rationale":"出自概念手册「绪论」核心概念；背完后可对照该单元的可背诵版核对。","id":"rgo01_q024","chapter":"第一章 绪论","chapterIdx":0,"num":24},{"type":"D","stem":"名词解释：核磁共振","answer":"在外磁场中具有自旋的原子核吸收射频辐射发生能级跃迁的现象；氢谱给出氢的化学环境、数目及与相邻氢的关系，是推断碳氢骨架的主要手段。","rationale":"出自概念手册「绪论」核心概念；背完后可对照该单元的可背诵版核对。","id":"rgo01_q025","chapter":"第一章 绪论","chapterIdx":0,"num":25},{"type":"S","stem":"简答题：分离提纯有机化合物常用的方法有哪些？各依据什么原理？","answer":"①蒸馏与分馏：依据液体混合物中各组分沸点不同，沸点相近时用分馏，高沸点或热敏性物质用减压蒸馏。②重结晶：依据固体有机物在溶剂中的溶解度随温度升高而显著增大，热饱和溶液冷却析出晶体，杂质留在母液中。③萃取：依据溶质在两种互不相溶的溶剂中分配系数不同，把溶质由原溶剂转移到另一溶剂。④升华：依据固体与杂质的蒸气压差异，适用于易升华的固体。⑤色谱法：依据各组分在固定相与流动相之间吸附、分配或离子交换能力的差异而分离，适合微量及性质相近的组分。","rationale":"得分要点是按物态和性质选方法：固体用重结晶或升华，液体用蒸馏、分馏或萃取，微量或性质相近用色谱。易错点是混淆蒸馏与分馏的适用条件，以及把色谱法原理写成“溶解度不同”。","id":"rgo01_q026","chapter":"第一章 绪论","chapterIdx":0,"num":26},{"type":"F","stem":"填空题：有机化合物分子式相同而结构不同的现象称为______；其中原子或基团的连接顺序和方式不同所引起的异构属于______异构。","answer":"①同分异构现象 ②构造（构造异构又分为碳链异构、位置异构和官能团异构，与立体异构并列）","rationale":"同分异构分为构造异构与立体异构两大类。构造异构只涉及原子的连接顺序，立体异构涉及原子在空间的排列，二者不要混为一谈。","id":"rgo01_q027","chapter":"第一章 绪论","chapterIdx":0,"num":27},{"type":"F","stem":"填空题：有机化合物以共价键为主，熔点、沸点一般较______，难溶于______，而易溶于苯、乙醚等有机溶剂。","answer":"①低 ②水（有机物极性弱，分子间以范德华力为主，故熔沸点低、不溶于极性大的水）","rationale":"这是有机化合物物理性质的共性：可燃、熔沸点低、难溶于水、易溶于有机溶剂、多为非电解质。答题时要点出“分子间作用力小、极性弱”这一原因。","id":"rgo01_q028","chapter":"第一章 绪论","chapterIdx":0,"num":28},{"type":"T","stem":"判断题：有机化合物就是含碳的化合物，因此一氧化碳、二氧化碳和碳酸盐都属于有机化合物。","options":{"A":"正确","B":"错误"},"answer":["B"],"rationale":"一氧化碳、二氧化碳、碳酸盐、氰化物等性质接近无机物，通常归无机化学讨论。有机化合物是以共价键结合的碳氢化合物及其衍生物。","id":"rgo01_q029","chapter":"第一章 绪论","chapterIdx":0,"num":29},{"type":"T","stem":"判断题：键线式中折点和端点都代表碳原子，碳原子上的氢原子通常省略不写。","options":{"A":"正确","B":"错误"},"answer":["A"],"rationale":"键线式用折线表示碳骨架，折点和端点代表碳原子，碳上的氢按四价补齐而省略；但杂原子及其所连的氢必须写出。","id":"rgo01_q030","chapter":"第一章 绪论","chapterIdx":0,"num":30}]},{"title":"第二章 有机化合物的化学键","questions":[{"type":"D","stem":"名词解释：价键理论","answer":"又称电子配对法，认为共价键由两个自旋相反的未成对电子配对形成，成键时原子轨道尽可能最大重叠，故共价键具有饱和性和方向性。","rationale":"出自概念手册「有机化合物的化学键」核心概念；背完后可对照该单元的可背诵版核对。","id":"rgo02_q001","chapter":"第二章 有机化合物的化学键","chapterIdx":1,"num":1},{"type":"D","stem":"名词解释：分子轨道理论","answer":"原子形成分子时原子轨道线性组合成分子轨道，电子属于整个分子；组合遵循能量相近、对称性匹配和最大重叠三原则。","rationale":"出自概念手册「有机化合物的化学键」核心概念；背完后可对照该单元的可背诵版核对。","id":"rgo02_q002","chapter":"第二章 有机化合物的化学键","chapterIdx":1,"num":2},{"type":"D","stem":"名词解释：杂化轨道理论","answer":"成键时同一原子中能量相近的原子轨道重新组合成一组数目相同、形状与方向不同的新轨道，成键能力增强，并决定分子的空间构型。","rationale":"出自概念手册「有机化合物的化学键」核心概念；背完后可对照该单元的可背诵版核对。","id":"rgo02_q003","chapter":"第二章 有机化合物的化学键","chapterIdx":1,"num":3},{"type":"D","stem":"名词解释：sp3杂化","answer":"一个s轨道与三个p轨道杂化，生成四个等价的sp3杂化轨道，指向正四面体的四个顶点，键角109.5°，如甲烷和四氯化碳中的碳。","rationale":"出自概念手册「有机化合物的化学键」核心概念；背完后可对照该单元的可背诵版核对。","id":"rgo02_q004","chapter":"第二章 有机化合物的化学键","chapterIdx":1,"num":4},{"type":"F","stem":"填空题：一个s轨道与三个p轨道杂化，生成四个等价的______轨道，指向正四面体的四个顶点，键角109.5°，如甲烷和四氯化碳中的碳。","answer":"sp3杂化","rationale":"出自概念手册「有机化合物的化学键」核心概念：sp3杂化。","id":"rgo02_q005","chapter":"第二章 有机化合物的化学键","chapterIdx":1,"num":5},{"type":"D","stem":"名词解释：sp2杂化","answer":"一个s轨道与两个p轨道杂化，生成三个sp2杂化轨道，在同一平面内互成120°，未杂化的p轨道垂直于该平面，如乙烯、苯和甲醛。","rationale":"出自概念手册「有机化合物的化学键」核心概念；背完后可对照该单元的可背诵版核对。","id":"rgo02_q006","chapter":"第二章 有机化合物的化学键","chapterIdx":1,"num":6},{"type":"F","stem":"填空题：一个s轨道与两个p轨道杂化，生成三个______轨道，在同一平面内互成120°，未杂化的p轨道垂直于该平面，如乙烯、苯和甲醛。","answer":"sp2杂化","rationale":"出自概念手册「有机化合物的化学键」核心概念：sp2杂化。","id":"rgo02_q007","chapter":"第二章 有机化合物的化学键","chapterIdx":1,"num":7},{"type":"D","stem":"名词解释：sp杂化","answer":"一个s轨道与一个p轨道杂化，生成两个sp杂化轨道，呈直线形，键角180°，余下两个p轨道可形成两个π键，如乙炔和二氧化碳。","rationale":"出自概念手册「有机化合物的化学键」核心概念；背完后可对照该单元的可背诵版核对。","id":"rgo02_q008","chapter":"第二章 有机化合物的化学键","chapterIdx":1,"num":8},{"type":"F","stem":"填空题：一个s轨道与一个p轨道杂化，生成两个______轨道，呈直线形，键角180°，余下两个p轨道可形成两个π键，如乙炔和二氧化碳。","answer":"sp杂化","rationale":"出自概念手册「有机化合物的化学键」核心概念：sp杂化。","id":"rgo02_q009","chapter":"第二章 有机化合物的化学键","chapterIdx":1,"num":9},{"type":"D","stem":"名词解释：σ键","answer":"原子轨道沿键轴方向头碰头重叠形成的共价键，电子云绕键轴呈圆柱形对称，可自由旋转，重叠程度大而键能较高，构成分子的骨架。","rationale":"出自概念手册「有机化合物的化学键」核心概念；背完后可对照该单元的可背诵版核对。","id":"rgo02_q010","chapter":"第二章 有机化合物的化学键","chapterIdx":1,"num":10},{"type":"D","stem":"名词解释：π键","answer":"未杂化p轨道肩并肩平行重叠形成的共价键，电子云分布在键轴上下两侧，不能自由旋转，重叠程度小、键能低，是加成反应的活性部位。","rationale":"出自概念手册「有机化合物的化学键」核心概念；背完后可对照该单元的可背诵版核对。","id":"rgo02_q011","chapter":"第二章 有机化合物的化学键","chapterIdx":1,"num":11},{"type":"D","stem":"名词解释：键参数","answer":"描述共价键性质的物理量，包括键长、键角和键能；键长越短、键能越大，键越牢固；键角决定分子的空间构型。","rationale":"出自概念手册「有机化合物的化学键」核心概念；背完后可对照该单元的可背诵版核对。","id":"rgo02_q012","chapter":"第二章 有机化合物的化学键","chapterIdx":1,"num":12},{"type":"D","stem":"名词解释：键的极性","answer":"成键原子电负性不同使共用电子对偏向电负性大的原子，形成极性共价键；电负性差越大极性越强，其大小用偶极矩衡量，偶极矩是矢量。","rationale":"出自概念手册「有机化合物的化学键」核心概念；背完后可对照该单元的可背诵版核对。","id":"rgo02_q013","chapter":"第二章 有机化合物的化学键","chapterIdx":1,"num":13},{"type":"D","stem":"名词解释：极化","answer":"在外电场或邻近极性基团影响下，键的电子云与原子核发生相对位移，使键的极性增大的现象；易极化的键反应活性高，如碘代烷。","rationale":"出自概念手册「有机化合物的化学键」核心概念；背完后可对照该单元的可背诵版核对。","id":"rgo02_q014","chapter":"第二章 有机化合物的化学键","chapterIdx":1,"num":14},{"type":"F","stem":"填空题：在外电场或邻近极性基团影响下，键的电子云与原子核发生相对位移，使键的极性增大的现象；易______的键反应活性高，如碘代烷。","answer":"极化","rationale":"出自概念手册「有机化合物的化学键」核心概念：极化。","id":"rgo02_q015","chapter":"第二章 有机化合物的化学键","chapterIdx":1,"num":15},{"type":"D","stem":"名词解释：均裂","answer":"共价键断裂时两个原子各带走一个成键电子，生成两个自由基的过程；多在光照、高温或过氧化物存在下发生，引发自由基型反应。","rationale":"出自概念手册「有机化合物的化学键」核心概念；背完后可对照该单元的可背诵版核对。","id":"rgo02_q016","chapter":"第二章 有机化合物的化学键","chapterIdx":1,"num":16},{"type":"D","stem":"名词解释：异裂","answer":"共价键断裂时成键电子对完全归其中一个原子所有，生成正、负离子的过程；多在极性溶剂或酸碱催化下发生，引发离子型反应。","rationale":"出自概念手册「有机化合物的化学键」核心概念；背完后可对照该单元的可背诵版核对。","id":"rgo02_q017","chapter":"第二章 有机化合物的化学键","chapterIdx":1,"num":17},{"type":"D","stem":"名词解释：自由基","answer":"带有未成对电子的原子或原子团，碳自由基接近平面构型，具顺磁性和很高的反应活性；稳定性顺序为叔大于仲大于伯大于甲基。","rationale":"出自概念手册「有机化合物的化学键」核心概念；背完后可对照该单元的可背诵版核对。","id":"rgo02_q018","chapter":"第二章 有机化合物的化学键","chapterIdx":1,"num":18},{"type":"F","stem":"填空题：带有未成对电子的原子或原子团，碳______接近平面构型，具顺磁性和很高的反应活性；稳定性顺序为叔大于仲大于伯大于甲基。","answer":"自由基","rationale":"出自概念手册「有机化合物的化学键」核心概念：自由基。","id":"rgo02_q019","chapter":"第二章 有机化合物的化学键","chapterIdx":1,"num":19},{"type":"D","stem":"名词解释：碳正离子","answer":"碳上带正电荷、只连三个基团并呈sp2杂化的活性中间体，构型为平面，空p轨道使其具强亲电性；稳定性由诱导效应与共轭效应决定。","rationale":"出自概念手册「有机化合物的化学键」核心概念；背完后可对照该单元的可背诵版核对。","id":"rgo02_q020","chapter":"第二章 有机化合物的化学键","chapterIdx":1,"num":20},{"type":"D","stem":"名词解释：共振论","answer":"鲍林提出的用若干极限结构式描述离域体系的方法：真实分子是这些共振式的杂化体，能量低于任一极限式；书写时只移动电子，不移动原子。","rationale":"出自概念手册「有机化合物的化学键」核心概念；背完后可对照该单元的可背诵版核对。","id":"rgo02_q021","chapter":"第二章 有机化合物的化学键","chapterIdx":1,"num":21},{"type":"D","stem":"名词解释：诱导效应","answer":"因原子或基团电负性不同而使σ键电子云偏移、并沿碳链传递的静电效应，分吸电子诱导效应和给电子诱导效应，随距离增加迅速减弱，属短程效应。","rationale":"出自概念手册「有机化合物的化学键」核心概念；背完后可对照该单元的可背诵版核对。","id":"rgo02_q022","chapter":"第二章 有机化合物的化学键","chapterIdx":1,"num":22},{"type":"F","stem":"填空题：因原子或基团电负性不同而使σ键电子云偏移、并沿碳链传递的静电效应，分吸电子______和给电子诱导效应，随距离增加迅速减弱，属短程效应。","answer":"诱导效应","rationale":"出自概念手册「有机化合物的化学键」核心概念：诱导效应。","id":"rgo02_q023","chapter":"第二章 有机化合物的化学键","chapterIdx":1,"num":23},{"type":"D","stem":"名词解释：共轭效应","answer":"在共轭体系中π电子离域并沿共轭链传递的效应，使体系能量降低、键长趋于平均化；分π-π共轭、p-π共轭和超共轭，属远程效应。","rationale":"出自概念手册「有机化合物的化学键」核心概念；背完后可对照该单元的可背诵版核对。","id":"rgo02_q024","chapter":"第二章 有机化合物的化学键","chapterIdx":1,"num":24},{"type":"D","stem":"名词解释：场效应","answer":"取代基通过空间静电场而不是化学键对反应中心产生的影响，其大小与取代基的空间位置和距离有关，可解释诱导效应无法解释的酸性差异。","rationale":"出自概念手册「有机化合物的化学键」核心概念；背完后可对照该单元的可背诵版核对。","id":"rgo02_q025","chapter":"第二章 有机化合物的化学键","chapterIdx":1,"num":25},{"type":"D","stem":"名词解释：分子间作用力","answer":"又称范德华力，包括取向力、诱导力和色散力，能量远小于共价键；它与氢键共同决定有机物的沸点、熔点、溶解度和挥发性。","rationale":"出自概念手册「有机化合物的化学键」核心概念；背完后可对照该单元的可背诵版核对。","id":"rgo02_q026","chapter":"第二章 有机化合物的化学键","chapterIdx":1,"num":26},{"type":"D","stem":"名词解释：氢键","answer":"与电负性大的原子共价结合的氢，同另一电负性大原子上的孤对电子之间的作用力；分分子间氢键与分子内氢键，使沸点升高、溶解度改变。","rationale":"出自概念手册「有机化合物的化学键」核心概念；背完后可对照该单元的可背诵版核对。","id":"rgo02_q027","chapter":"第二章 有机化合物的化学键","chapterIdx":1,"num":27},{"type":"F","stem":"填空题：与电负性大的原子共价结合的氢，同另一电负性大原子上的孤对电子之间的作用力；分分子间______与分子内氢键，使沸点升高、溶解度改变。","answer":"氢键","rationale":"出自概念手册「有机化合物的化学键」核心概念：氢键。","id":"rgo02_q028","chapter":"第二章 有机化合物的化学键","chapterIdx":1,"num":28},{"type":"D","stem":"名词解释：电荷转移络合物","answer":"由富电子给体与缺电子受体之间部分转移电子而形成的分子间化合物，如苦味酸与萘的络合物；结合力弱，多呈深色。","rationale":"出自概念手册「有机化合物的化学键」核心概念；背完后可对照该单元的可背诵版核对。","id":"rgo02_q029","chapter":"第二章 有机化合物的化学键","chapterIdx":1,"num":29},{"type":"D","stem":"名词解释：包合物","answer":"一种分子被另一种分子的空腔包络而形成的分子间化合物，如环糊精包合药物；主客体间无共价键，靠氢键与范德华力维持。","rationale":"出自概念手册「有机化合物的化学键」核心概念；背完后可对照该单元的可背诵版核对。","id":"rgo02_q030","chapter":"第二章 有机化合物的化学键","chapterIdx":1,"num":30},{"type":"S","stem":"简答题：比较 σ 键与 π 键在形成方式、重叠程度、能否旋转和反应活性上的差异。","answer":"①形成方式：σ 键由原子轨道沿键轴方向“头碰头”重叠形成，电子云绕键轴呈圆柱形对称；π 键由未杂化的 p 轨道“肩并肩”平行重叠形成，电子云分布在键轴上下两侧。②重叠程度与强度：σ 键重叠程度大、键能高，较牢固；π 键重叠程度小、键能低，较易断裂。③旋转：σ 键可绕键轴自由旋转；π 键不能自由旋转，故双键存在顺反异构。④反应活性：π 键电子云暴露在键轴上下，易受亲电试剂进攻，是加成反应的活性部位；σ 键相对稳定。⑤组成：双键由一个 σ 键和一个 π 键组成，三键由一个 σ 键和两个 π 键组成。","rationale":"采分点是“重叠方式不同”和“π 键不能自由旋转”。易错点：误认为 π 键键能总大于 σ 键，或把双键说成由两个 σ 键构成。","id":"rgo02_q031","chapter":"第二章 有机化合物的化学键","chapterIdx":1,"num":31},{"type":"F","stem":"填空题：碳原子采取 sp3 杂化时四个杂化轨道指向正四面体的四个顶点，键角为______；采取 sp 杂化时两个杂化轨道呈直线形，键角为______。","answer":"①109.5°（即 109°28′） ②180°（sp2 杂化为 120°，分子呈平面三角形）","rationale":"杂化轨道数等于参与杂化的原子轨道数，杂化类型决定键角与分子构型。三键碳为 sp 杂化，双键碳为 sp2 杂化，饱和碳为 sp3 杂化。","id":"rgo02_q032","chapter":"第二章 有机化合物的化学键","chapterIdx":1,"num":32},{"type":"F","stem":"填空题：共价键断裂时成键电子对完全被一个原子占有、生成正负离子的方式称为______；在光照或过氧化物存在下两个原子各带一个电子、生成自由基的方式称为______。","answer":"①异裂 ②均裂（异裂引发离子型反应，均裂引发自由基型反应）","rationale":"断键方式决定反应类型，判断机理的关键是看中间体是离子还是自由基。极性溶剂、酸碱催化有利于异裂，光照、高温、过氧化物有利于均裂。","id":"rgo02_q033","chapter":"第二章 有机化合物的化学键","chapterIdx":1,"num":33},{"type":"T","stem":"判断题：烷基是给电子基团，其给电子诱导效应随碳链延长而不断增强。","options":{"A":"正确","B":"错误"},"answer":["B"],"rationale":"诱导效应是短程效应，沿碳链传递时迅速减弱，一般超过三个碳原子后即可忽略。这与共轭效应的远程传递不同。","id":"rgo02_q034","chapter":"第二章 有机化合物的化学键","chapterIdx":1,"num":34},{"type":"T","stem":"判断题：二氧化碳和四氯化碳分子中的共价键有极性，但整个分子的偶极矩为零。","options":{"A":"正确","B":"错误"},"answer":["A"],"rationale":"分子极性取决于各键矩的矢量和。二氧化碳为直线形、四氯化碳为正四面体，结构对称使键矩相互抵消，故分子偶极矩为零。","id":"rgo02_q035","chapter":"第二章 有机化合物的化学键","chapterIdx":1,"num":35}]},{"title":"第三章 烷烃","questions":[{"type":"D","stem":"名词解释：烷烃","answer":"只含碳碳单键和碳氢键的开链饱和烃，通式CnH2n+2，碳原子均为sp3杂化，化学性质稳定，主要发生自由基取代反应。","rationale":"出自概念手册「烷烃」核心概念；背完后可对照该单元的可背诵版核对。","id":"rgo03_q001","chapter":"第三章 烷烃","chapterIdx":2,"num":1},{"type":"D","stem":"名词解释：同系列","answer":"结构相似、组成上相差一个或若干个CH2原子团的一系列化合物，如甲烷、乙烷、丙烷；同系列中的各化合物互为同系物。","rationale":"出自概念手册「烷烃」核心概念；背完后可对照该单元的可背诵版核对。","id":"rgo03_q002","chapter":"第三章 烷烃","chapterIdx":2,"num":2},{"type":"F","stem":"填空题：结构相似、组成上相差一个或若干个CH2原子团的一系列化合物，如甲烷、乙烷、丙烷；______中的各化合物互为同系物。","answer":"同系列","rationale":"出自概念手册「烷烃」核心概念：同系列。","id":"rgo03_q003","chapter":"第三章 烷烃","chapterIdx":2,"num":3},{"type":"D","stem":"名词解释：碳链异构","answer":"烷烃中因碳骨架分支方式不同而产生的构造异构，如正丁烷与异丁烷；碳原子数越多，可能的碳链异构体数目增加得越快。","rationale":"出自概念手册「烷烃」核心概念；背完后可对照该单元的可背诵版核对。","id":"rgo03_q004","chapter":"第三章 烷烃","chapterIdx":2,"num":4},{"type":"F","stem":"填空题：烷烃中因碳骨架分支方式不同而产生的构造异构，如正丁烷与异丁烷；碳原子数越多，可能的______体数目增加得越快。","answer":"碳链异构","rationale":"出自概念手册「烷烃」核心概念：碳链异构。","id":"rgo03_q005","chapter":"第三章 烷烃","chapterIdx":2,"num":5},{"type":"D","stem":"名词解释：烷基","answer":"烷烃分子去掉一个氢原子后剩下的基团，通式CnH2n+1，如甲基、乙基、异丙基，是命名中取代基的基本形式。","rationale":"出自概念手册「烷烃」核心概念；背完后可对照该单元的可背诵版核对。","id":"rgo03_q006","chapter":"第三章 烷烃","chapterIdx":2,"num":6},{"type":"D","stem":"名词解释：伯仲叔季碳","answer":"按所连碳原子数目划分：连一个碳的为伯碳，连两个为仲碳，连三个为叔碳，连四个为季碳；相应的氢称伯、仲、叔氢。","rationale":"出自概念手册「烷烃」核心概念；背完后可对照该单元的可背诵版核对。","id":"rgo03_q007","chapter":"第三章 烷烃","chapterIdx":2,"num":7},{"type":"D","stem":"名词解释：系统命名法","answer":"按国际纯粹与应用化学联合会规则命名：选最长碳链为主链，从靠近取代基一端编号使位次最小，取代基按次序规则由小到大书写。","rationale":"出自概念手册「烷烃」核心概念；背完后可对照该单元的可背诵版核对。","id":"rgo03_q008","chapter":"第三章 烷烃","chapterIdx":2,"num":8},{"type":"D","stem":"名词解释：构象","answer":"同一分子因单键旋转而使原子在空间形成的不同排列方式；构象之间的转变不需断键、无法分离，只能用构象式表示。","rationale":"出自概念手册「烷烃」核心概念；背完后可对照该单元的可背诵版核对。","id":"rgo03_q009","chapter":"第三章 烷烃","chapterIdx":2,"num":9},{"type":"F","stem":"填空题：同一分子因单键旋转而使原子在空间形成的不同排列方式；______之间的转变不需断键、无法分离，只能用构象式表示。","answer":"构象","rationale":"出自概念手册「烷烃」核心概念：构象。","id":"rgo03_q010","chapter":"第三章 烷烃","chapterIdx":2,"num":10},{"type":"D","stem":"名词解释：纽曼投影式","answer":"沿碳碳单键轴线观察分子，用圆圈表示后碳、三线交点表示前碳所画出的投影式，可直观比较两碳上基团的相对位置。","rationale":"出自概念手册「烷烃」核心概念；背完后可对照该单元的可背诵版核对。","id":"rgo03_q011","chapter":"第三章 烷烃","chapterIdx":2,"num":11},{"type":"D","stem":"名词解释：交叉式构象","answer":"相邻碳上的氢原子彼此交错排列、二面角为60°的构象；空间位阻小、能量低，是乙烷最稳定的构象。","rationale":"出自概念手册「烷烃」核心概念；背完后可对照该单元的可背诵版核对。","id":"rgo03_q012","chapter":"第三章 烷烃","chapterIdx":2,"num":12},{"type":"D","stem":"名词解释：重叠式构象","answer":"相邻碳上的氢原子彼此正对、二面角为0°的构象；氢原子间排斥最大、能量最高，是乙烷最不稳定的构象。","rationale":"出自概念手册「烷烃」核心概念；背完后可对照该单元的可背诵版核对。","id":"rgo03_q013","chapter":"第三章 烷烃","chapterIdx":2,"num":13},{"type":"D","stem":"名词解释：对位交叉式","answer":"丁烷中两个甲基处于对位、二面角为180°的交叉式构象；甲基相距最远、位阻最小，是丁烷最稳定的构象。","rationale":"出自概念手册「烷烃」核心概念；背完后可对照该单元的可背诵版核对。","id":"rgo03_q014","chapter":"第三章 烷烃","chapterIdx":2,"num":14},{"type":"D","stem":"名词解释：邻位交叉式","answer":"丁烷中两个甲基处于邻位、二面角为60°的交叉式构象；稳定性仅次于对位交叉式，能量比后者略高。","rationale":"出自概念手册「烷烃」核心概念；背完后可对照该单元的可背诵版核对。","id":"rgo03_q015","chapter":"第三章 烷烃","chapterIdx":2,"num":15},{"type":"D","stem":"名词解释：自由基取代反应","answer":"烷烃分子中的氢被卤素等原子或基团取代，且机理上经历自由基链式过程的反应，如光照条件下的氯代反应。","rationale":"出自概念手册「烷烃」核心概念；背完后可对照该单元的可背诵版核对。","id":"rgo03_q016","chapter":"第三章 烷烃","chapterIdx":2,"num":16},{"type":"D","stem":"名词解释：链反应","answer":"由链引发、链增长、链终止三个阶段组成的自由基反应；引发产生自由基，增长阶段消耗原料并再生自由基，终止阶段自由基相互结合而消失。","rationale":"出自概念手册「烷烃」核心概念；背完后可对照该单元的可背诵版核对。","id":"rgo03_q017","chapter":"第三章 烷烃","chapterIdx":2,"num":17},{"type":"D","stem":"名词解释：裂化","answer":"在高温或催化剂作用下使大分子烷烃断裂为较小分子烷烃和烯烃的过程，是石油加工中提高汽油产量的重要方法。","rationale":"出自概念手册「烷烃」核心概念；背完后可对照该单元的可背诵版核对。","id":"rgo03_q018","chapter":"第三章 烷烃","chapterIdx":2,"num":18},{"type":"D","stem":"名词解释：异构化","answer":"在催化剂作用下使烷烃碳链由直链变为支链或发生甲基迁移的反应，可提高汽油的辛烷值，改善燃烧性能。","rationale":"出自概念手册「烷烃」核心概念；背完后可对照该单元的可背诵版核对。","id":"rgo03_q019","chapter":"第三章 烷烃","chapterIdx":2,"num":19},{"type":"D","stem":"名词解释：石油醚","answer":"石油分馏得到的低沸点馏分，主要含戊烷和己烷，为无色易挥发液体，常用作有机溶剂；名称虽含醚字，实际并非醚类。","rationale":"出自概念手册「烷烃」核心概念；背完后可对照该单元的可背诵版核对。","id":"rgo03_q020","chapter":"第三章 烷烃","chapterIdx":2,"num":20},{"type":"D","stem":"名词解释：武兹反应","answer":"卤代烷与金属钠在无水乙醚中作用，两分子卤代烷偶联生成对称烷烃的反应，是实验室制备烷烃的常用方法。","rationale":"出自概念手册「烷烃」核心概念；背完后可对照该单元的可背诵版核对。","id":"rgo03_q021","chapter":"第三章 烷烃","chapterIdx":2,"num":21},{"type":"S","stem":"简答题：简述烷烃系统命名法（IUPAC 命名）的主要步骤。","answer":"①选主链：选取分子中最长的碳链作为主链，若有多条等长碳链，则选取代基数目最多的一条。②编号：从靠近取代基的一端开始给主链碳原子编号，使取代基的位次之和最小（或第一个取代基位次最小）。③合并相同基团：相同的取代基合并，用二、三、四等表示数目，位次之间用逗号隔开，位次与名称之间用半字线连接。④排列顺序：不同取代基按次序规则由小到大排列，主链名称写在最后。⑤复杂支链：支链上还有支链时，把该支链名称加括号作为取代基。","rationale":"采分点是“最长碳链、最小位次、相同基合并、按次序规则排列”四步。常见错误是编号方向判断错误，或把位次和名称之间的连接符号写错。","id":"rgo03_q022","chapter":"第三章 烷烃","chapterIdx":2,"num":22},{"type":"F","stem":"填空题：乙烷分子中最稳定的构象是______式，最不稳定的构象是______式。","answer":"①交叉 ②重叠（交叉式中前后氢原子相距最远，扭转张力与空间排斥最小）","rationale":"构象是单键旋转产生的空间排列，不需断键即可互变。重叠式存在扭转张力，能量最高；交叉式能量最低，故最稳定。","id":"rgo03_q023","chapter":"第三章 烷烃","chapterIdx":2,"num":23},{"type":"F","stem":"填空题：烷烃分子中的 C—C 键和 C—H 键都是______键，可绕键轴自由旋转，因此同一分子可存在多种______。","answer":"①σ ②构象（构象的改变不需断键，而构型的改变必须断键）","rationale":"σ 键电子云绕键轴呈圆柱形对称，故可自由旋转。要区分构象与构型：构象由单键旋转产生，构型需断键才能互变。","id":"rgo03_q024","chapter":"第三章 烷烃","chapterIdx":2,"num":24},{"type":"T","stem":"判断题：正丁烷的沸点高于异丁烷，是因为正丁烷的支链较多、分子间接触面积较大。","options":{"A":"正确","B":"错误"},"answer":["B"],"rationale":"理由说反了：正丁烷是直链烷烃，没有支链；异丁烷（2-甲基丙烷）才有支链。直链分子间接触面积大、色散力强，故正丁烷沸点较高。","id":"rgo03_q025","chapter":"第三章 烷烃","chapterIdx":2,"num":25},{"type":"T","stem":"判断题：烷烃与卤素在光照下发生自由基取代反应，卤素的反应活性顺序为 F2 > Cl2 > Br2 > I2。","options":{"A":"正确","B":"错误"},"answer":["A"],"rationale":"氟代反应过于剧烈甚至爆炸，碘代反应可逆、难以进行，故实用价值小。氯代活性高但选择性差，溴代活性适中、选择性好，合成上更有用。","id":"rgo03_q026","chapter":"第三章 烷烃","chapterIdx":2,"num":26}]},{"title":"第四章 烯烃","questions":[{"type":"D","stem":"名词解释：烯烃","answer":"含碳碳双键的开链不饱和烃，通式CnH2n，双键碳为sp2杂化，化学性质活泼，易发生亲电加成、氧化和聚合反应。","rationale":"出自概念手册「烯烃」核心概念；背完后可对照该单元的可背诵版核对。","id":"rgo04_q001","chapter":"第四章 烯烃","chapterIdx":3,"num":1},{"type":"D","stem":"名词解释：碳碳双键","answer":"由一个σ键和一个π键组成的双键，双键碳及与之相连的四个原子共平面，键长约0.134nm，不能自由旋转，是烯烃的反应中心。","rationale":"出自概念手册「烯烃」核心概念；背完后可对照该单元的可背诵版核对。","id":"rgo04_q002","chapter":"第四章 烯烃","chapterIdx":3,"num":2},{"type":"D","stem":"名词解释：顺反异构","answer":"双键或环限制了旋转，使两个相同基团位于双键同侧或异侧而产生的构型异构；同侧为顺式，异侧为反式，二者性质不同。","rationale":"出自概念手册「烯烃」核心概念；背完后可对照该单元的可背诵版核对。","id":"rgo04_q003","chapter":"第四章 烯烃","chapterIdx":3,"num":3},{"type":"D","stem":"名词解释：Z/E 标记法","answer":"按次序规则比较双键每个碳上所连两个基团的优先顺序，优先基团在同侧为Z、在异侧为E的构型标记法，适用于所有双键化合物。","rationale":"出自概念手册「烯烃」核心概念；背完后可对照该单元的可背诵版核对。","id":"rgo04_q004","chapter":"第四章 烯烃","chapterIdx":3,"num":4},{"type":"D","stem":"名词解释：亲电加成反应","answer":"烯烃的π电子进攻亲电试剂，生成碳正离子或环状卤鎓离子中间体，再由亲核试剂进攻成键的反应，是烯烃最典型的反应类型。","rationale":"出自概念手册「烯烃」核心概念；背完后可对照该单元的可背诵版核对。","id":"rgo04_q005","chapter":"第四章 烯烃","chapterIdx":3,"num":5},{"type":"D","stem":"名词解释：马氏规则","answer":"不对称烯烃与卤化氢等极性试剂加成时，氢原子加到含氢较多的双键碳上，即试剂的正电部分加到含氢多的一端，本质是生成更稳定的碳正离子。","rationale":"出自概念手册「烯烃」核心概念；背完后可对照该单元的可背诵版核对。","id":"rgo04_q006","chapter":"第四章 烯烃","chapterIdx":3,"num":6},{"type":"D","stem":"名词解释：过氧化物效应","answer":"在过氧化物存在下，溴化氢与不对称烯烃发生反马氏加成，溴加到含氢较多的碳上；该效应只适用于溴化氢，氯化氢和碘化氢不出现。","rationale":"出自概念手册「烯烃」核心概念；背完后可对照该单元的可背诵版核对。","id":"rgo04_q007","chapter":"第四章 烯烃","chapterIdx":3,"num":7},{"type":"D","stem":"名词解释：卤鎓离子","answer":"卤素与烯烃加成时先生成的三元环状正离子中间体，如溴鎓离子；它使两个卤原子从双键两侧分别进入，故加溴为反式加成。","rationale":"出自概念手册「烯烃」核心概念；背完后可对照该单元的可背诵版核对。","id":"rgo04_q008","chapter":"第四章 烯烃","chapterIdx":3,"num":8},{"type":"D","stem":"名词解释：水合反应","answer":"烯烃与水加成生成醇的反应，直接水合需酸催化并按马氏规则进行；也可通过硼氢化-氧化或间接水合实现，是工业制醇的重要方法。","rationale":"出自概念手册「烯烃」核心概念；背完后可对照该单元的可背诵版核对。","id":"rgo04_q009","chapter":"第四章 烯烃","chapterIdx":3,"num":9},{"type":"D","stem":"名词解释：硼氢化-氧化反应","answer":"烯烃先与乙硼烷发生顺式加成生成三烷基硼，再用过氧化氢碱性溶液氧化为醇的反应，总结果为反马氏加水，且不发生重排。","rationale":"出自概念手册「烯烃」核心概念；背完后可对照该单元的可背诵版核对。","id":"rgo04_q010","chapter":"第四章 烯烃","chapterIdx":3,"num":10},{"type":"D","stem":"名词解释：臭氧化反应","answer":"烯烃与臭氧加成生成臭氧化物，再经锌粉水解或催化氢化还原裂解为醛或酮的反应，可用于推断双键的位置和结构。","rationale":"出自概念手册「烯烃」核心概念；背完后可对照该单元的可背诵版核对。","id":"rgo04_q011","chapter":"第四章 烯烃","chapterIdx":3,"num":11},{"type":"D","stem":"名词解释：环氧化反应","answer":"烯烃与过氧酸作用生成环氧化合物的反应，氧原子从双键一侧加入，属顺式加成，产物可进一步开环生成反式邻二醇。","rationale":"出自概念手册「烯烃」核心概念；背完后可对照该单元的可背诵版核对。","id":"rgo04_q012","chapter":"第四章 烯烃","chapterIdx":3,"num":12},{"type":"D","stem":"名词解释：加聚反应","answer":"含双键的单体在引发剂作用下相互加成、生成高分子化合物的反应，如乙烯聚合为聚乙烯，产物链节与单体组成相同。","rationale":"出自概念手册「烯烃」核心概念；背完后可对照该单元的可背诵版核对。","id":"rgo04_q013","chapter":"第四章 烯烃","chapterIdx":3,"num":13},{"type":"D","stem":"名词解释：烯丙位取代","answer":"在双键相邻碳上发生的自由基取代反应，常用NBS在光照下进行，因烯丙型自由基有共轭稳定作用而易于生成。","rationale":"出自概念手册「烯烃」核心概念；背完后可对照该单元的可背诵版核对。","id":"rgo04_q014","chapter":"第四章 烯烃","chapterIdx":3,"num":14},{"type":"D","stem":"名词解释：氢化热","answer":"一摩尔不饱和化合物加氢生成饱和化合物所放出的热量，可用于比较烯烃的稳定性：氢化热越小，烯烃越稳定。","rationale":"出自概念手册「烯烃」核心概念；背完后可对照该单元的可背诵版核对。","id":"rgo04_q015","chapter":"第四章 烯烃","chapterIdx":3,"num":15},{"type":"F","stem":"填空题：一摩尔不饱和化合物加氢生成饱和化合物所放出的热量，可用于比较烯烃的稳定性：______越小，烯烃越稳定。","answer":"氢化热","rationale":"出自概念手册「烯烃」核心概念：氢化热。","id":"rgo04_q016","chapter":"第四章 烯烃","chapterIdx":3,"num":16},{"type":"D","stem":"名词解释：烯烃的氧化","answer":"烯烃与高锰酸钾、臭氧或过氧酸等氧化剂作用生成二醇、醛酮或羧酸的反应；冷稀高锰酸钾生成邻二醇，酸性加热则断键。","rationale":"出自概念手册「烯烃」核心概念；背完后可对照该单元的可背诵版核对。","id":"rgo04_q017","chapter":"第四章 烯烃","chapterIdx":3,"num":17},{"type":"S","stem":"简答题：什么是马尔科夫尼科夫规则？试用碳正离子稳定性加以解释。","answer":"①马氏规则：不对称烯烃与卤化氢等极性试剂发生亲电加成时，试剂中的氢加到含氢较多的双键碳上，卤素（或其余部分）加到含氢较少的双键碳上。②反应本质：亲电加成分步进行，质子先加到双键上生成碳正离子中间体，再由亲核试剂进攻。③碳正离子稳定性顺序为叔 > 仲 > 伯 > 甲基碳正离子，因为烷基的给电子诱导效应和 C—H 超共轭效应能分散正电荷。④质子加到含氢较多的碳上，正好生成取代基较多、更稳定的碳正离子，故得马氏产物。⑤例外：在过氧化物存在下与 HBr 加成按自由基机理进行，得反马氏产物，此过氧化物效应只对 HBr 有效，对 HCl、HI 无效。","rationale":"采分点是“规则表述 + 碳正离子稳定性 + 过氧化物效应及其适用范围”。易错点：把过氧化物效应推广到 HCl 和 HI，或把“含氢较多”写反。","id":"rgo04_q018","chapter":"第四章 烯烃","chapterIdx":3,"num":18},{"type":"F","stem":"填空题：丙烯与 HBr 在过氧化物存在下加成，主要产物是______，这一现象称为______效应。","answer":"①1-溴丙烷（反马氏产物） ②过氧化物（自由基机理，只对 HBr 有效）","rationale":"过氧化物均裂产生的自由基引发链反应，使溴自由基先加到末端碳上，生成更稳定的仲碳自由基，故得反马氏产物。对 HCl、HI 无此效应。","id":"rgo04_q019","chapter":"第四章 烯烃","chapterIdx":3,"num":19},{"type":"F","stem":"填空题：烯烃与稀冷高锰酸钾溶液作用生成______，可用于检验碳碳双键；与酸性热浓高锰酸钾作用时双键完全断裂，生成羧酸或______。","answer":"①邻二醇（顺式加成，同时紫色褪去并析出褐色二氧化锰沉淀） ②酮（双键碳上有烷基时被氧化成酮）","rationale":"稀冷高锰酸钾氧化是顺式加成，是检验双键的经典方法；强氧化条件下双键断裂，双键碳上带氢者氧化成羧酸，不带氢者氧化成酮。","id":"rgo04_q020","chapter":"第四章 烯烃","chapterIdx":3,"num":20},{"type":"T","stem":"判断题：烯烃与溴的加成是顺式加成，因为先生成环状溴鎓离子，溴离子再从背面进攻。","options":{"A":"正确","B":"错误"},"answer":["B"],"rationale":"结论与理由矛盾：先生成三元环溴鎓离子，溴离子只能从背面进攻，故为反式加成（anti 加成），不是顺式加成。","id":"rgo04_q021","chapter":"第四章 烯烃","chapterIdx":3,"num":21},{"type":"T","stem":"判断题：烯烃的稳定性随双键碳上所连烷基数目的增多而增大，故稳定性顺序为四取代 > 三取代 > 二取代 > 单取代。","options":{"A":"正确","B":"错误"},"answer":["A"],"rationale":"烷基是给电子基，可通过给电子诱导效应和超共轭效应分散双键电子云，使体系能量降低、稳定性增大，故取代基越多越稳定。","id":"rgo04_q022","chapter":"第四章 烯烃","chapterIdx":3,"num":22}]},{"title":"第五章 炔烃和二烯烃","questions":[{"type":"D","stem":"名词解释：炔烃","answer":"含碳碳三键的开链不饱和烃，通式CnH2n-2，三键碳为sp杂化，分子呈直线形，化学性质活泼，可发生加成、氧化和端基炔的取代反应。","rationale":"出自概念手册「炔烃和二烯烃」核心概念；背完后可对照该单元的可背诵版核对。","id":"rgo05_q001","chapter":"第五章 炔烃和二烯烃","chapterIdx":4,"num":1},{"type":"D","stem":"名词解释：碳碳三键","answer":"由一个σ键和两个相互垂直的π键组成的三键，两个碳及与之相连的原子共直线，键长约0.120nm，是炔烃的反应中心。","rationale":"出自概念手册「炔烃和二烯烃」核心概念；背完后可对照该单元的可背诵版核对。","id":"rgo05_q002","chapter":"第五章 炔烃和二烯烃","chapterIdx":4,"num":2},{"type":"D","stem":"名词解释：端基炔","answer":"三键位于碳链末端、三键碳上连有氢原子的炔烃，如乙炔、丙炔；其炔氢具弱酸性，可被金属取代生成炔化物。","rationale":"出自概念手册「炔烃和二烯烃」核心概念；背完后可对照该单元的可背诵版核对。","id":"rgo05_q003","chapter":"第五章 炔烃和二烯烃","chapterIdx":4,"num":3},{"type":"D","stem":"名词解释：金属炔化物","answer":"端基炔与硝酸银氨溶液或氯化亚铜氨溶液反应生成的沉淀，分别为白色的炔银和砖红色的炔亚铜，常用于鉴别端基炔。","rationale":"出自概念手册「炔烃和二烯烃」核心概念；背完后可对照该单元的可背诵版核对。","id":"rgo05_q004","chapter":"第五章 炔烃和二烯烃","chapterIdx":4,"num":4},{"type":"D","stem":"名词解释：林德拉催化剂","answer":"经醋酸铅等毒化的钯催化剂，能使炔烃加氢停留在烯烃阶段而不继续还原为烷烃，产物为顺式烯烃。","rationale":"出自概念手册「炔烃和二烯烃」核心概念；背完后可对照该单元的可背诵版核对。","id":"rgo05_q005","chapter":"第五章 炔烃和二烯烃","chapterIdx":4,"num":5},{"type":"D","stem":"名词解释：炔烃水合","answer":"炔烃在硫酸汞催化下与稀硫酸加成生成烯醇，烯醇不稳定迅速互变异构为酮的反应；乙炔水合生成乙醛，其余炔烃生成酮。","rationale":"出自概念手册「炔烃和二烯烃」核心概念；背完后可对照该单元的可背诵版核对。","id":"rgo05_q006","chapter":"第五章 炔烃和二烯烃","chapterIdx":4,"num":6},{"type":"D","stem":"名词解释：共轭二烯烃","answer":"两个碳碳双键被一个单键隔开的二烯烃，如1,3-丁二烯；双键的π电子与中间单键发生共轭，使体系稳定并具有特殊加成方式。","rationale":"出自概念手册「炔烃和二烯烃」核心概念；背完后可对照该单元的可背诵版核对。","id":"rgo05_q007","chapter":"第五章 炔烃和二烯烃","chapterIdx":4,"num":7},{"type":"D","stem":"名词解释：1,2-加成与1,4-加成","answer":"共轭二烯烃加成时试剂可加在相邻两个双键碳上，称1,2-加成；也可加在共轭体系两端碳上并在中间形成新双键，称1,4-加成。","rationale":"出自概念手册「炔烃和二烯烃」核心概念；背完后可对照该单元的可背诵版核对。","id":"rgo05_q008","chapter":"第五章 炔烃和二烯烃","chapterIdx":4,"num":8},{"type":"D","stem":"名词解释：离域π键","answer":"多个相互平行的p轨道在共轭体系中重叠形成、电子不局限于两个原子之间的π键，是共轭效应产生的结构基础。","rationale":"出自概念手册「炔烃和二烯烃」核心概念；背完后可对照该单元的可背诵版核对。","id":"rgo05_q009","chapter":"第五章 炔烃和二烯烃","chapterIdx":4,"num":9},{"type":"D","stem":"名词解释：双烯合成","answer":"又称Diels-Alder反应，共轭二烯与含吸电子基的烯烃加热发生环加成，生成六元环状化合物的反应，属协同反应。","rationale":"出自概念手册「炔烃和二烯烃」核心概念；背完后可对照该单元的可背诵版核对。","id":"rgo05_q010","chapter":"第五章 炔烃和二烯烃","chapterIdx":4,"num":10},{"type":"D","stem":"名词解释：亲双烯体","answer":"在双烯合成中与共轭二烯加成的烯烃组分，其上连有羰基、氰基、酯基等吸电子基时反应活性显著提高。","rationale":"出自概念手册「炔烃和二烯烃」核心概念；背完后可对照该单元的可背诵版核对。","id":"rgo05_q011","chapter":"第五章 炔烃和二烯烃","chapterIdx":4,"num":11},{"type":"D","stem":"名词解释：孤立二烯烃","answer":"两个双键被两个或更多单键隔开的二烯烃，双键间无共轭作用，性质与普通烯烃相似，可分别发生加成反应。","rationale":"出自概念手册「炔烃和二烯烃」核心概念；背完后可对照该单元的可背诵版核对。","id":"rgo05_q012","chapter":"第五章 炔烃和二烯烃","chapterIdx":4,"num":12},{"type":"D","stem":"名词解释：累积二烯烃","answer":"两个双键连在同一个碳原子上的二烯烃，如丙二烯；中间碳为sp杂化，两端双键互相垂直，性质活泼但不稳定。","rationale":"出自概念手册「炔烃和二烯烃」核心概念；背完后可对照该单元的可背诵版核对。","id":"rgo05_q013","chapter":"第五章 炔烃和二烯烃","chapterIdx":4,"num":13},{"type":"D","stem":"名词解释：炔烃的酸性","answer":"三键碳的sp杂化使碳电负性增大，C-H键极性增强，端基炔氢可解离，其pKa约25，酸性弱于醇而强于烯烃和烷烃。","rationale":"出自概念手册「炔烃和二烯烃」核心概念；背完后可对照该单元的可背诵版核对。","id":"rgo05_q014","chapter":"第五章 炔烃和二烯烃","chapterIdx":4,"num":14},{"type":"D","stem":"名词解释：乙炔的聚合","answer":"乙炔在催化剂作用下可聚合成苯、乙烯基乙炔或二乙烯基乙炔等，条件不同产物不同，是乙炔的重要工业性质。","rationale":"出自概念手册「炔烃和二烯烃」核心概念；背完后可对照该单元的可背诵版核对。","id":"rgo05_q015","chapter":"第五章 炔烃和二烯烃","chapterIdx":4,"num":15},{"type":"D","stem":"名词解释：烯炔","answer":"分子中同时含有双键和三键的开链不饱和烃，命名时称某烯炔，编号应使双键和三键的位次都尽可能小，书写时先烯后炔。","rationale":"出自概念手册「炔烃和二烯烃」核心概念；背完后可对照该单元的可背诵版核对。","id":"rgo05_q016","chapter":"第五章 炔烃和二烯烃","chapterIdx":4,"num":16},{"type":"F","stem":"填空题：分子中同时含有双键和三键的开链不饱和烃，命名时称某______，编号应使双键和三键的位次都尽可能小，书写时先烯后炔。","answer":"烯炔","rationale":"出自概念手册「炔烃和二烯烃」核心概念：烯炔。","id":"rgo05_q017","chapter":"第五章 炔烃和二烯烃","chapterIdx":4,"num":17},{"type":"S","stem":"简答题：比较炔烃与烯烃在亲电加成活性上的差异，并说明原因。","answer":"①总体而言炔烃的亲电加成活性低于烯烃，与溴、卤化氢加成的速率较慢。②原因之一是炔键碳为 sp 杂化，s 成分大、电负性高，π 电子被原子核束缚得紧，不易向亲电试剂给出。③原因之二是加成第一步生成的乙烯基碳正离子中带正电的碳为 sp2 杂化且直接连双键，能量高、不稳定，故反应活化能大。④但炔烃可连续加成两分子试剂，且能与 HCN、醇、羧酸等在催化下加成，这是烯烃较难进行的。⑤炔烃在汞盐催化下加水生成不稳定的烯醇，随即互变异构为酮；只有乙炔最终生成醛。","rationale":"采分点是“sp 杂化使 π 电子不易给出 + 乙烯基碳正离子不稳定”。最常见的错误是套用“三键更活泼”的直觉，把活性顺序写反。","id":"rgo05_q018","chapter":"第五章 炔烃和二烯烃","chapterIdx":4,"num":18},{"type":"F","stem":"填空题：乙炔在硫酸汞和稀硫酸催化下加水，首先生成不稳定的______，随即互变异构为______。","answer":"①烯醇（CH2=CHOH） ②乙醛（只有乙炔水解得醛，其他炔烃得酮）","rationale":"炔烃加水遵循马氏规则，羟基加在含氢较少的碳上，所得烯醇迅速互变异构为羰基化合物。乙炔得乙醛，丙炔得丙酮。","id":"rgo05_q019","chapter":"第五章 炔烃和二烯烃","chapterIdx":4,"num":19},{"type":"F","stem":"填空题：1,3-丁二烯与一分子溴在低温下主要发生______加成，得到 3,4-二溴-1-丁烯；在高温下主要生成 1,4-加成产物，原因是 1,4-产物______。","answer":"①1,2- ②更稳定（双键取代基较多、能量较低，高温下由热力学控制）","rationale":"低温为动力学控制，1,2-加成活化能低、生成快；高温为热力学控制，1,4-加成的内部双键更稳定，故成为主要产物。","id":"rgo05_q020","chapter":"第五章 炔烃和二烯烃","chapterIdx":4,"num":20},{"type":"T","stem":"判断题：末端炔烃（如丙炔）能与硝酸银的氨溶液反应生成白色沉淀，可用于鉴别末端炔烃。","options":{"A":"正确","B":"错误"},"answer":["A"],"rationale":"末端炔氢具有弱酸性，可被银离子或亚铜离子取代，分别生成白色的炔化银和红棕色的炔化亚铜沉淀，是末端炔烃的特征鉴别反应。","id":"rgo05_q021","chapter":"第五章 炔烃和二烯烃","chapterIdx":4,"num":21},{"type":"T","stem":"判断题：1,3-丁二烯分子中四个碳原子都是 sp2 杂化，π 电子形成离域的共轭体系。","options":{"A":"正确","B":"错误"},"answer":["A"],"rationale":"四个 sp2 碳共平面，每个碳提供一个 p 轨道侧面重叠形成贯穿四个碳的共轭大 π 键，故键长趋于平均化、体系能量降低，易发生 1,4-加成。","id":"rgo05_q022","chapter":"第五章 炔烃和二烯烃","chapterIdx":4,"num":22}]},{"title":"第六章 脂环烃","questions":[{"type":"D","stem":"名词解释：脂环烃","answer":"碳原子连成环状、性质与脂肪烃相似的烃，包括环烷烃、环烯烃和环炔烃，通式分别为CnH2n、CnH2n-2等。","rationale":"出自概念手册「脂环烃」核心概念；背完后可对照该单元的可背诵版核对。","id":"rgo06_q001","chapter":"第六章 脂环烃","chapterIdx":5,"num":1},{"type":"D","stem":"名词解释：单环烷烃","answer":"只含一个碳环的饱和脂环烃，通式CnH2n，与同碳数的烯烃互为同分异构体，性质与烷烃相似，但小环易开环。","rationale":"出自概念手册「脂环烃」核心概念；背完后可对照该单元的可背诵版核对。","id":"rgo06_q002","chapter":"第六章 脂环烃","chapterIdx":5,"num":2},{"type":"D","stem":"名词解释：桥环烃","answer":"两个或多个环共用两个以上碳原子的脂环烃，共用的碳称桥头碳；命名时按桥头碳编号，先写大环再写小环。","rationale":"出自概念手册「脂环烃」核心概念；背完后可对照该单元的可背诵版核对。","id":"rgo06_q003","chapter":"第六章 脂环烃","chapterIdx":5,"num":3},{"type":"D","stem":"名词解释：螺环烃","answer":"两个环只共用一个碳原子的脂环烃，共用碳称螺原子；命名时先小环后大环，两环编号均从螺原子相邻的碳开始。","rationale":"出自概念手册「脂环烃」核心概念；背完后可对照该单元的可背诵版核对。","id":"rgo06_q004","chapter":"第六章 脂环烃","chapterIdx":5,"num":4},{"type":"D","stem":"名词解释：环张力","answer":"环状分子因键角偏离正常值、相邻原子相互排斥以及构象扭曲而产生的内部张力，使环的能量升高、稳定性下降。","rationale":"出自概念手册「脂环烃」核心概念；背完后可对照该单元的可背诵版核对。","id":"rgo06_q005","chapter":"第六章 脂环烃","chapterIdx":5,"num":5},{"type":"D","stem":"名词解释：角张力","answer":"环中键角偏离sp3正常键角109.5°所产生的张力，偏离越大张力越大；环丙烷键角仅60°，角张力最大。","rationale":"出自概念手册「脂环烃」核心概念；背完后可对照该单元的可背诵版核对。","id":"rgo06_q006","chapter":"第六章 脂环烃","chapterIdx":5,"num":6},{"type":"F","stem":"填空题：环中键角偏离sp3正常键角109.5°所产生的张力，偏离越大张力越大；环丙烷键角仅60°，______最大。","answer":"角张力","rationale":"出自概念手册「脂环烃」核心概念：角张力。","id":"rgo06_q007","chapter":"第六章 脂环烃","chapterIdx":5,"num":7},{"type":"D","stem":"名词解释：扭转张力","answer":"环上相邻碳的键处于重叠式排列时，因氢原子相互排斥而产生的张力；环丙烷的氢全部重叠，扭转张力大。","rationale":"出自概念手册「脂环烃」核心概念；背完后可对照该单元的可背诵版核对。","id":"rgo06_q008","chapter":"第六章 脂环烃","chapterIdx":5,"num":8},{"type":"F","stem":"填空题：环上相邻碳的键处于重叠式排列时，因氢原子相互排斥而产生的张力；环丙烷的氢全部重叠，______大。","answer":"扭转张力","rationale":"出自概念手册「脂环烃」核心概念：扭转张力。","id":"rgo06_q009","chapter":"第六章 脂环烃","chapterIdx":5,"num":9},{"type":"D","stem":"名词解释：拜耳张力学说","answer":"用平面环的键角变形解释环烷烃稳定性的早期理论：环丙烷、环丁烷键角压缩严重而张力大，环戊烷以上张力减小；但它不能解释环己烷的异常稳定。","rationale":"出自概念手册「脂环烃」核心概念；背完后可对照该单元的可背诵版核对。","id":"rgo06_q010","chapter":"第六章 脂环烃","chapterIdx":5,"num":10},{"type":"D","stem":"名词解释：椅式构象","answer":"环己烷最稳定的构象，六个碳分处两个平行平面，键角接近109.5°，相邻碳上的氢全部处于交叉式，几乎无张力。","rationale":"出自概念手册「脂环烃」核心概念；背完后可对照该单元的可背诵版核对。","id":"rgo06_q011","chapter":"第六章 脂环烃","chapterIdx":5,"num":11},{"type":"D","stem":"名词解释：船式构象","answer":"环己烷中两个碳向上翘起、形似小船的构象，船头船尾的氢相距很近，且部分氢处于重叠式，能量高于椅式。","rationale":"出自概念手册「脂环烃」核心概念；背完后可对照该单元的可背诵版核对。","id":"rgo06_q012","chapter":"第六章 脂环烃","chapterIdx":5,"num":12},{"type":"D","stem":"名词解释：直立键","answer":"又称a键，环己烷椅式构象中平行于分子对称轴、近似垂直于环平均平面的碳氢键，同一碳上的a键与相邻碳的a键方向相反。","rationale":"出自概念手册「脂环烃」核心概念；背完后可对照该单元的可背诵版核对。","id":"rgo06_q013","chapter":"第六章 脂环烃","chapterIdx":5,"num":13},{"type":"D","stem":"名词解释：平伏键","answer":"又称e键，环己烷椅式构象中大致平行于环平面、向外伸展的碳氢键；取代基处于e键时空间位阻小，构象更稳定。","rationale":"出自概念手册「脂环烃」核心概念；背完后可对照该单元的可背诵版核对。","id":"rgo06_q014","chapter":"第六章 脂环烃","chapterIdx":5,"num":14},{"type":"D","stem":"名词解释：构象翻转","answer":"环己烷由一种椅式构象经环的扭动转变为另一种椅式构象的过程；翻转后a键变为e键、e键变为a键，取代基的上下方向不变。","rationale":"出自概念手册「脂环烃」核心概念；背完后可对照该单元的可背诵版核对。","id":"rgo06_q015","chapter":"第六章 脂环烃","chapterIdx":5,"num":15},{"type":"D","stem":"名词解释：开环加成反应","answer":"小环烷烃因张力大而使环破裂、与试剂加成生成开链产物的反应，如环丙烷与氢、溴、溴化氢的加成。","rationale":"出自概念手册「脂环烃」核心概念；背完后可对照该单元的可背诵版核对。","id":"rgo06_q016","chapter":"第六章 脂环烃","chapterIdx":5,"num":16},{"type":"D","stem":"名词解释：小环烷烃","answer":"通常指环丙烷和环丁烷，因角张力和扭转张力较大而不稳定，具有类似烯烃的开环加成性质。","rationale":"出自概念手册「脂环烃」核心概念；背完后可对照该单元的可背诵版核对。","id":"rgo06_q017","chapter":"第六章 脂环烃","chapterIdx":5,"num":17},{"type":"D","stem":"名词解释：燃烧热","answer":"一摩尔有机物完全燃烧生成二氧化碳和水所放出的热量；比较环烷烃每个CH2的燃烧热可判断稳定性，燃烧热越大越不稳定。","rationale":"出自概念手册「脂环烃」核心概念；背完后可对照该单元的可背诵版核对。","id":"rgo06_q018","chapter":"第六章 脂环烃","chapterIdx":5,"num":18},{"type":"F","stem":"填空题：一摩尔有机物完全燃烧生成二氧化碳和水所放出的热量；比较环烷烃每个CH2的______可判断稳定性，燃烧热越大越不稳定。","answer":"燃烧热","rationale":"出自概念手册「脂环烃」核心概念：燃烧热。","id":"rgo06_q019","chapter":"第六章 脂环烃","chapterIdx":5,"num":19},{"type":"D","stem":"名词解释：环上顺反异构","answer":"环的限制使环上两个取代基不能自由旋转，处于环同侧为顺式、异侧为反式；二者是构型不同的化合物，性质也不相同。","rationale":"出自概念手册「脂环烃」核心概念；背完后可对照该单元的可背诵版核对。","id":"rgo06_q020","chapter":"第六章 脂环烃","chapterIdx":5,"num":20},{"type":"S","stem":"简答题：为什么环丙烷容易发生开环加成反应，而环己烷性质稳定？","answer":"①环丙烷的三个碳原子共平面，环内角只有 60°，远小于 sp3 杂化碳的正常键角 109.5°，存在很大的角张力。②环丙烷中相邻碳上的氢处于重叠式，存在较大的扭转张力。③环丙烷的 C—C 键是弯曲键（香蕉键），轨道重叠程度小、键能低，故容易断裂开环。④环己烷可采取椅式构象，键角接近 109.5°，相邻键处于交叉式，角张力和扭转张力都很小。⑤因此环己烷性质与开链烷烃相似，光照下主要发生自由基取代，不易开环加成。","rationale":"采分点是“角张力、扭转张力、弯曲键”三点。要能据此解释小环（三元、四元）易开环而五元、六元环稳定，并会用溴的四氯化碳溶液鉴别。","id":"rgo06_q021","chapter":"第六章 脂环烃","chapterIdx":5,"num":21},{"type":"F","stem":"填空题：环丙烷在室温下与溴的四氯化碳溶液发生______反应而使溴褪色；环己烷与溴在光照下则发生______反应。","answer":"①开环加成（生成 1,3-二溴丙烷） ②自由基取代（环上氢被溴取代，溴不褪色为加成）","rationale":"三元小环张力大，易开环加成，故能使溴褪色；六元环稳定，只发生取代反应。这一差异可用于鉴别环丙烷与环己烷。","id":"rgo06_q022","chapter":"第六章 脂环烃","chapterIdx":5,"num":22},{"type":"F","stem":"填空题：环己烷最稳定的构象是______式，其中六个 C—H 键分为直立键（a 键）和平伏键（______键）两组。","answer":"①椅 ②e（平伏键，又称赤道键；a 键与 e 键可随环翻转而互变）","rationale":"椅式构象既无角张力也无扭转张力，能量最低；船式构象存在旗杆氢的空间排斥，能量较高。取代基处于 e 键时更稳定。","id":"rgo06_q023","chapter":"第六章 脂环烃","chapterIdx":5,"num":23},{"type":"T","stem":"判断题：在环烷烃中，环丙烷的稳定性最差，环己烷的稳定性最好。","options":{"A":"正确","B":"错误"},"answer":["A"],"rationale":"环丙烷角张力最大、燃烧热（每 CH2）最高，故最不稳定；环己烷可形成无张力的椅式构象，故最稳定。稳定性顺序为环己烷 > 环戊烷 > 环丁烷 > 环丙烷。","id":"rgo06_q024","chapter":"第六章 脂环烃","chapterIdx":5,"num":24},{"type":"T","stem":"判断题：环丙烷分子中三个碳原子共平面，其 C—C—C 键角为 109.5°。","options":{"A":"正确","B":"错误"},"answer":["B"],"rationale":"环丙烷虽为平面三角形，但键角只有 60°，远小于 sp3 的正常键角 109.5°，这正是其角张力极大、易于开环的原因。","id":"rgo06_q025","chapter":"第六章 脂环烃","chapterIdx":5,"num":25}]},{"title":"第七章 芳香烃","questions":[{"type":"D","stem":"名词解释：芳香烃","answer":"含苯环或具有芳香性结构的碳氢化合物，包括单环芳烃、多环芳烃和稠环芳烃，单环芳烃通式CnH2n-6，主要发生亲电取代反应。","rationale":"出自概念手册「芳香烃」核心概念；背完后可对照该单元的可背诵版核对。","id":"rgo07_q001","chapter":"第七章 芳香烃","chapterIdx":6,"num":1},{"type":"D","stem":"名词解释：芳香性","answer":"环状共轭体系因π电子完全离域而表现出的特殊稳定性，其判据为分子共平面、环状闭合共轭且π电子数符合休克尔规则。","rationale":"出自概念手册「芳香烃」核心概念；背完后可对照该单元的可背诵版核对。","id":"rgo07_q002","chapter":"第七章 芳香烃","chapterIdx":6,"num":2},{"type":"D","stem":"名词解释：休克尔规则","answer":"判断单环共轭体系芳香性的规则：分子共平面、形成闭合共轭环且π电子数为4n+2（n取0、1、2等整数）时具有芳香性。","rationale":"出自概念手册「芳香烃」核心概念；背完后可对照该单元的可背诵版核对。","id":"rgo07_q003","chapter":"第七章 芳香烃","chapterIdx":6,"num":3},{"type":"D","stem":"名词解释：反芳香性","answer":"平面环状闭合共轭体系的π电子数为4n时，体系能量高于相应的开链共轭物而表现不稳定，称为反芳香性，如环丁二烯。","rationale":"出自概念手册「芳香烃」核心概念；背完后可对照该单元的可背诵版核对。","id":"rgo07_q004","chapter":"第七章 芳香烃","chapterIdx":6,"num":4},{"type":"F","stem":"填空题：平面环状闭合共轭体系的π电子数为4n时，体系能量高于相应的开链共轭物而表现不稳定，称为______，如环丁二烯。","answer":"反芳香性","rationale":"出自概念手册「芳香烃」核心概念：反芳香性。","id":"rgo07_q005","chapter":"第七章 芳香烃","chapterIdx":6,"num":5},{"type":"D","stem":"名词解释：亲电取代反应","answer":"芳环上的氢被亲电试剂取代的反应，反应经σ-络合物中间体并失去质子恢复芳香性，是芳香烃最基本的反应类型。","rationale":"出自概念手册「芳香烃」核心概念；背完后可对照该单元的可背诵版核对。","id":"rgo07_q006","chapter":"第七章 芳香烃","chapterIdx":6,"num":6},{"type":"D","stem":"名词解释：σ-络合物","answer":"亲电试剂进攻苯环生成的带正电荷中间体，正电荷离域在环上五个碳上并破坏芳香性，能量较高，是决定反应速率的关键中间体。","rationale":"出自概念手册「芳香烃」核心概念；背完后可对照该单元的可背诵版核对。","id":"rgo07_q007","chapter":"第七章 芳香烃","chapterIdx":6,"num":7},{"type":"D","stem":"名词解释：定位效应","answer":"苯环上已有取代基通过诱导效应和共轭效应改变环上电子云分布，从而决定新引入基团进入位置的现象，分邻对位定位和间位定位。","rationale":"出自概念手册「芳香烃」核心概念；背完后可对照该单元的可背诵版核对。","id":"rgo07_q008","chapter":"第七章 芳香烃","chapterIdx":6,"num":8},{"type":"D","stem":"名词解释：致活基团","answer":"使苯环电子云密度升高、亲电取代反应速率加快的取代基，除卤素外多为邻对位定位基，如羟基、氨基、烷基。","rationale":"出自概念手册「芳香烃」核心概念；背完后可对照该单元的可背诵版核对。","id":"rgo07_q009","chapter":"第七章 芳香烃","chapterIdx":6,"num":9},{"type":"D","stem":"名词解释：致钝基团","answer":"使苯环电子云密度降低、亲电取代反应速率减慢的取代基，如硝基、磺酸基、羰基、氰基，一般为间位定位基。","rationale":"出自概念手册「芳香烃」核心概念；背完后可对照该单元的可背诵版核对。","id":"rgo07_q010","chapter":"第七章 芳香烃","chapterIdx":6,"num":10},{"type":"D","stem":"名词解释：傅-克烷基化","answer":"苯在无水三氯化铝催化下与卤代烷或烯烃反应生成烷基苯的反应，烷基可发生重排，易得多烷基化产物，且反应可逆。","rationale":"出自概念手册「芳香烃」核心概念；背完后可对照该单元的可背诵版核对。","id":"rgo07_q011","chapter":"第七章 芳香烃","chapterIdx":6,"num":11},{"type":"D","stem":"名词解释：傅-克酰基化","answer":"苯与酰卤或酸酐在无水三氯化铝催化下生成芳香酮的反应，酰基不发生重排，产物单一，是制备芳酮的重要方法。","rationale":"出自概念手册「芳香烃」核心概念；背完后可对照该单元的可背诵版核对。","id":"rgo07_q012","chapter":"第七章 芳香烃","chapterIdx":6,"num":12},{"type":"D","stem":"名词解释：磺化反应","answer":"苯与浓硫酸或发烟硫酸加热生成苯磺酸的反应，反应可逆，苯磺酸用水稀释加热可脱去磺酸基，常用于占位和分离。","rationale":"出自概念手册「芳香烃」核心概念；背完后可对照该单元的可背诵版核对。","id":"rgo07_q013","chapter":"第七章 芳香烃","chapterIdx":6,"num":13},{"type":"D","stem":"名词解释：侧链氧化","answer":"烷基苯的侧链在酸性高锰酸钾或重铬酸钾作用下被氧化为羧基的反应；有α-氢的侧链氧化为苯甲酸，无α-氢的叔丁基不被氧化。","rationale":"出自概念手册「芳香烃」核心概念；背完后可对照该单元的可背诵版核对。","id":"rgo07_q014","chapter":"第七章 芳香烃","chapterIdx":6,"num":14},{"type":"F","stem":"填空题：烷基苯的侧链在酸性高锰酸钾或重铬酸钾作用下被氧化为羧基的反应；有α-氢的______为苯甲酸，无α-氢的叔丁基不被氧化。","answer":"侧链氧化","rationale":"出自概念手册「芳香烃」核心概念：侧链氧化。","id":"rgo07_q015","chapter":"第七章 芳香烃","chapterIdx":6,"num":15},{"type":"D","stem":"名词解释：稠环芳烃","answer":"两个或多个苯环共用两个相邻碳原子稠合而成的芳烃，如萘、蒽、菲；性质与苯相似，但环上电子云密度不均匀，反应活性较高。","rationale":"出自概念手册「芳香烃」核心概念；背完后可对照该单元的可背诵版核对。","id":"rgo07_q016","chapter":"第七章 芳香烃","chapterIdx":6,"num":16},{"type":"D","stem":"名词解释：非苯芳烃","answer":"不含苯环但符合休克尔规则而具有芳香性的环状共轭体系，如环戊二烯基负离子、环庚三烯正离子和薁。","rationale":"出自概念手册「芳香烃」核心概念；背完后可对照该单元的可背诵版核对。","id":"rgo07_q017","chapter":"第七章 芳香烃","chapterIdx":6,"num":17},{"type":"D","stem":"名词解释：苯的结构","answer":"六个碳原子均为sp2杂化并共平面，形成闭合的离域π键，碳碳键长完全相等约0.139nm，键能介于单键与双键之间，故苯极稳定。","rationale":"出自概念手册「芳香烃」核心概念；背完后可对照该单元的可背诵版核对。","id":"rgo07_q018","chapter":"第七章 芳香烃","chapterIdx":6,"num":18},{"type":"S","stem":"简答题：苯为什么具有芳香性？请用休克尔规则说明。","answer":"①苯分子为平面正六边形，六个碳原子都是 sp2 杂化，键角 120°，所有原子共平面。②每个碳原子还有一个未参与杂化的 p 轨道，垂直于环平面且彼此平行，侧面重叠形成闭合的离域大 π 键。③苯的 π 电子数为 6，符合休克尔规则 4n+2（n=1）的要求，故具有芳香性。④π 电子完全离域使体系能量显著降低，C—C 键长完全平均化（均为 0.140 nm），分子特别稳定。⑤因此苯易发生亲电取代反应，难发生加成和氧化反应，这就是芳香性的表现。","rationale":"采分点是“平面闭合共轭体系 + 4n+2 规则 + 能量降低、键长平均化”。判断非苯芳烃时还必须强调“环状、平面、完全共轭”三个前提。","id":"rgo07_q019","chapter":"第七章 芳香烃","chapterIdx":6,"num":19},{"type":"F","stem":"填空题：苯的卤代反应需在______催化下进行；硝化反应使用浓硝酸与浓硫酸的混酸，其中浓硫酸起______作用。","answer":"①FeX3（FeCl3 或 FeBr3 等路易斯酸） ②催化（使硝酸质子化并脱水生成硝酰正离子 NO2+）","rationale":"亲电取代的实质是亲电试剂进攻苯环。路易斯酸活化卤素生成卤正离子，浓硫酸使硝酸生成 NO2+，二者都是催化剂。","id":"rgo07_q020","chapter":"第七章 芳香烃","chapterIdx":6,"num":20},{"type":"F","stem":"填空题：苯环上连有 —OH、—NH2、—CH3 等给电子基时，新引入的取代基主要进入______位，反应活性______。","answer":"①邻位和对位 ②升高（给电子基使苯环尤其是邻、对位电子云密度升高，属致活基团）","rationale":"给电子基为邻对位定位基并致活苯环；吸电子基（如 —NO2、—COOH、—CN）为间位定位基并致钝苯环。卤素是例外：邻对位定位但致钝。","id":"rgo07_q021","chapter":"第七章 芳香烃","chapterIdx":6,"num":21},{"type":"T","stem":"判断题：萘的亲电取代反应主要发生在 α 位，因为生成的 α-取代中间体有更多保留完整苯环的共振式，更稳定。","options":{"A":"正确","B":"错误"},"answer":["A"],"rationale":"α 位进攻所得中间体可写出两个保留一个完整苯环的共振式，β 位只有一个，故 α 位中间体能量更低，反应主要发生在 α 位。","id":"rgo07_q022","chapter":"第七章 芳香烃","chapterIdx":6,"num":22},{"type":"T","stem":"判断题：甲苯能被酸性高锰酸钾氧化成苯甲酸，说明苯环本身很容易被氧化。","options":{"A":"正确","B":"错误"},"answer":["B"],"rationale":"被氧化的是与苯环相连、且 α-碳上带氢的侧链烷基，苯环本身很稳定，不被高锰酸钾氧化。无 α-氢的叔丁基苯则不能被氧化。","id":"rgo07_q023","chapter":"第七章 芳香烃","chapterIdx":6,"num":23}]},{"title":"第八章 立体化学基础","questions":[{"type":"D","stem":"名词解释：立体化学","answer":"研究分子中原子在空间排列方式及其对性质影响的分支学科，内容包括构象异构、构型异构、手性及对映异构现象。","rationale":"出自概念手册「立体化学基础」核心概念；背完后可对照该单元的可背诵版核对。","id":"rgo08_q001","chapter":"第八章 立体化学基础","chapterIdx":7,"num":1},{"type":"D","stem":"名词解释：手性","answer":"物体与其镜像不能完全重合的性质，如同人的左右手；分子具有手性时称手性分子，其最显著的表现是能使平面偏振光旋转。","rationale":"出自概念手册「立体化学基础」核心概念；背完后可对照该单元的可背诵版核对。","id":"rgo08_q002","chapter":"第八章 立体化学基础","chapterIdx":7,"num":2},{"type":"F","stem":"填空题：物体与其镜像不能完全重合的性质，如同人的左右手；分子具有______时称手性分子，其最显著的表现是能使平面偏振光旋转。","answer":"手性","rationale":"出自概念手册「立体化学基础」核心概念：手性。","id":"rgo08_q003","chapter":"第八章 立体化学基础","chapterIdx":7,"num":3},{"type":"D","stem":"名词解释：手性碳原子","answer":"连有四个互不相同基团的sp3杂化碳原子，又称不对称碳原子或手性中心，常用星号标出；是判断多数手性分子的直观依据。","rationale":"出自概念手册「立体化学基础」核心概念；背完后可对照该单元的可背诵版核对。","id":"rgo08_q004","chapter":"第八章 立体化学基础","chapterIdx":7,"num":4},{"type":"D","stem":"名词解释：对映体","answer":"互为镜像且不能重合的一对立体异构体，二者的旋光方向相反、旋光度相等，除与手性试剂反应外化学性质相同。","rationale":"出自概念手册「立体化学基础」核心概念；背完后可对照该单元的可背诵版核对。","id":"rgo08_q005","chapter":"第八章 立体化学基础","chapterIdx":7,"num":5},{"type":"D","stem":"名词解释：非对映体","answer":"不互为镜像的立体异构体，如顺反异构体和含两个以上手性碳的差向异构体；其物理性质和旋光性均不相同。","rationale":"出自概念手册「立体化学基础」核心概念；背完后可对照该单元的可背诵版核对。","id":"rgo08_q006","chapter":"第八章 立体化学基础","chapterIdx":7,"num":6},{"type":"D","stem":"名词解释：外消旋体","answer":"等量左旋体和右旋体组成的混合物，旋光性相互抵消而显光学不活性，其熔点等物理性质与单一对映体不同。","rationale":"出自概念手册「立体化学基础」核心概念；背完后可对照该单元的可背诵版核对。","id":"rgo08_q007","chapter":"第八章 立体化学基础","chapterIdx":7,"num":7},{"type":"D","stem":"名词解释：内消旋体","answer":"分子内存在对称面或对称中心、使两部分旋光性相互抵消的化合物，如内消旋酒石酸；它是纯净物，不旋光，也不能拆分。","rationale":"出自概念手册「立体化学基础」核心概念；背完后可对照该单元的可背诵版核对。","id":"rgo08_q008","chapter":"第八章 立体化学基础","chapterIdx":7,"num":8},{"type":"D","stem":"名词解释：旋光度","answer":"偏振光通过含手性物质的溶液时振动平面发生的旋转角度，用旋光仪测定，受浓度、液层厚度、温度、波长和溶剂影响。","rationale":"出自概念手册「立体化学基础」核心概念；背完后可对照该单元的可背诵版核对。","id":"rgo08_q009","chapter":"第八章 立体化学基础","chapterIdx":7,"num":9},{"type":"D","stem":"名词解释：比旋光度","answer":"单位浓度和单位液层厚度下的旋光度，用[α]表示，是手性化合物的特征常数，可用于纯度测定与构型比较。","rationale":"出自概念手册「立体化学基础」核心概念；背完后可对照该单元的可背诵版核对。","id":"rgo08_q010","chapter":"第八章 立体化学基础","chapterIdx":7,"num":10},{"type":"D","stem":"名词解释：对称面","answer":"能将分子分成互为镜像的两部分的平面，用σ表示；分子中有对称面时必与其镜像重合，因而是非手性分子，内消旋体即含对称面。","rationale":"出自概念手册「立体化学基础」核心概念；背完后可对照该单元的可背诵版核对。","id":"rgo08_q011","chapter":"第八章 立体化学基础","chapterIdx":7,"num":11},{"type":"F","stem":"填空题：能将分子分成互为镜像的两部分的平面，用σ表示；分子中有______时必与其镜像重合，因而是非手性分子，内消旋体即含对称面。","answer":"对称面","rationale":"出自概念手册「立体化学基础」核心概念：对称面。","id":"rgo08_q012","chapter":"第八章 立体化学基础","chapterIdx":7,"num":12},{"type":"D","stem":"名词解释：R/S 构型标记","answer":"按次序规则确定手性碳上四个基团的优先顺序，最小基团背向观察者，其余三个由大到小排列，顺时针为R、逆时针为S的标记法。","rationale":"出自概念手册「立体化学基础」核心概念；背完后可对照该单元的可背诵版核对。","id":"rgo08_q013","chapter":"第八章 立体化学基础","chapterIdx":7,"num":13},{"type":"D","stem":"名词解释：次序规则","answer":"比较基团优先顺序的规则：单原子按原子序数由大到小排列，多原子基团逐个比较相连原子，双键或三键视作重复连接。","rationale":"出自概念手册「立体化学基础」核心概念；背完后可对照该单元的可背诵版核对。","id":"rgo08_q014","chapter":"第八章 立体化学基础","chapterIdx":7,"num":14},{"type":"D","stem":"名词解释：费歇尔投影式","answer":"用横竖交叉线表示手性碳构型的投影式，横线代表指向观察者的键、竖线代表背离观察者的键，常用于糖和氨基酸的构型表示。","rationale":"出自概念手册「立体化学基础」核心概念；背完后可对照该单元的可背诵版核对。","id":"rgo08_q015","chapter":"第八章 立体化学基础","chapterIdx":7,"num":15},{"type":"D","stem":"名词解释：构型","answer":"分子中各原子在空间的相对位置关系，改变构型必须断裂并重新形成共价键，如R/S构型和顺反构型，不同构型是不同的化合物。","rationale":"出自概念手册「立体化学基础」核心概念；背完后可对照该单元的可背诵版核对。","id":"rgo08_q016","chapter":"第八章 立体化学基础","chapterIdx":7,"num":16},{"type":"F","stem":"填空题：分子中各原子在空间的相对位置关系，改变______必须断裂并重新形成共价键，如R/S构型和顺反构型，不同构型是不同的化合物。","answer":"构型","rationale":"出自概念手册「立体化学基础」核心概念：构型。","id":"rgo08_q017","chapter":"第八章 立体化学基础","chapterIdx":7,"num":17},{"type":"D","stem":"名词解释：外消旋体拆分","answer":"将外消旋体分离为两个纯对映体的过程，常用生成非对映体盐后结晶分离、酶法或手性色谱法，因对映体物理性质相同不能直接分离。","rationale":"出自概念手册「立体化学基础」核心概念；背完后可对照该单元的可背诵版核对。","id":"rgo08_q018","chapter":"第八章 立体化学基础","chapterIdx":7,"num":18},{"type":"D","stem":"名词解释：差向异构体","answer":"含两个以上手性碳的立体异构体中，只有一个手性碳构型不同的异构体，如葡萄糖与甘露糖，属非对映体。","rationale":"出自概念手册「立体化学基础」核心概念；背完后可对照该单元的可背诵版核对。","id":"rgo08_q019","chapter":"第八章 立体化学基础","chapterIdx":7,"num":19},{"type":"D","stem":"名词解释：几何异构","answer":"因双键或环限制旋转而产生的顺反异构，属构型异构；两个相同基团在同侧为顺式，在异侧为反式。","rationale":"出自概念手册「立体化学基础」核心概念；背完后可对照该单元的可背诵版核对。","id":"rgo08_q020","chapter":"第八章 立体化学基础","chapterIdx":7,"num":20},{"type":"S","stem":"简答题：说明手性、旋光性与对映体三者的关系，并指出判断手性的依据。","answer":"①手性分子是不能与其镜像完全重合的分子，其根本原因是分子内缺乏对称面、对称中心和交替对称轴。②手性分子一定具有旋光性，能使平面偏振光的振动面发生旋转，比旋光度是物质的特征常数。③一对对映体是彼此不能重合的镜像，等量混合即组成外消旋体，外消旋体无旋光性。④分子中只含一个手性碳（连四个不同基团的 sp3 碳）时必为手性分子，有一对对映体；含 n 个不同手性碳时有 2^n 个旋光异构体。⑤对映体在非手性环境中物理性质相同、化学性质相同，但旋光方向相反，在手性环境（如生物体）中活性常有很大差别。","rationale":"采分点是“手性即不能与镜像重合 + 手性必有旋光性 + 外消旋体无旋光性”。易错点：把“含手性碳”当作“有旋光性”的充分条件，忽略内消旋体。","id":"rgo08_q021","chapter":"第八章 立体化学基础","chapterIdx":7,"num":21},{"type":"F","stem":"填空题：含一个手性碳原子的化合物有______个旋光异构体；等量的一对对映体混合组成______，其旋光性为______。","answer":"①2 ②外消旋体（可被拆分，拆分后两组分旋光方向相反） ③零（不显旋光性）","rationale":"旋光异构体数目为 2^n，n 为不同的手性碳原子数。外消旋体是混合物而非化合物，故无固定熔点，也无旋光性。","id":"rgo08_q022","chapter":"第八章 立体化学基础","chapterIdx":7,"num":22},{"type":"F","stem":"填空题：用 R/S 标记构型时，先把次序最小的基团置于远离观察者的位置，其余三个基团按次序规则由大到小排列，若为______时针方向则为 R 构型，若为______时针方向则为 S 构型。","answer":"①顺 ②逆（若最小基团朝向观察者，则所得结论必须反转）","rationale":"次序规则按原子序数由大到小比较，先比较直接相连的原子，序数相同再逐层比较。最小基团朝向观察者时手性判断结果要取反。","id":"rgo08_q023","chapter":"第八章 立体化学基础","chapterIdx":7,"num":23},{"type":"T","stem":"判断题：含有两个手性碳原子的化合物一定具有旋光性。","options":{"A":"正确","B":"错误"},"answer":["B"],"rationale":"当两个手性碳所连基团完全相同时（如酒石酸），存在分子内有对称面的内消旋体，整体无旋光性。故含手性碳不是有旋光性的充分条件。","id":"rgo08_q024","chapter":"第八章 立体化学基础","chapterIdx":7,"num":24},{"type":"T","stem":"判断题：一对对映体的熔点、沸点、溶解度等物理性质完全相同，比旋光度数值相等而方向相反。","options":{"A":"正确","B":"错误"},"answer":["A"],"rationale":"对映体在非手性环境中各物理性质相同，只是对偏振光的作用方向相反。外消旋体的熔点、溶解度等则与纯对映体不同。","id":"rgo08_q025","chapter":"第八章 立体化学基础","chapterIdx":7,"num":25}]},{"title":"第九章 卤代烃","questions":[{"type":"D","stem":"名词解释：卤代烃","answer":"烃分子中的一个或多个氢原子被卤素取代形成的化合物，通式R-X，卤素为官能团，主要发生亲核取代和消除反应。","rationale":"出自概念手册「卤代烃」核心概念；背完后可对照该单元的可背诵版核对。","id":"rgo09_q001","chapter":"第九章 卤代烃","chapterIdx":8,"num":1},{"type":"D","stem":"名词解释：亲核取代反应","answer":"亲核试剂进攻卤代烃中与卤素相连的碳原子，卤素以负离子形式离去并被亲核试剂取代的反应，分SN1和SN2两种机理。","rationale":"出自概念手册「卤代烃」核心概念；背完后可对照该单元的可背诵版核对。","id":"rgo09_q002","chapter":"第九章 卤代烃","chapterIdx":8,"num":2},{"type":"D","stem":"名词解释：SN2 反应","answer":"双分子亲核取代反应，亲核试剂从离去基团背面进攻、经五配位过渡态一步完成，速率与底物和亲核试剂浓度均有关，产物构型翻转。","rationale":"出自概念手册「卤代烃」核心概念；背完后可对照该单元的可背诵版核对。","id":"rgo09_q003","chapter":"第九章 卤代烃","chapterIdx":8,"num":3},{"type":"D","stem":"名词解释：SN1 反应","answer":"单分子亲核取代反应，卤代烃先离解生成碳正离子，再与亲核试剂结合，速率只与底物浓度有关，产物常为外消旋混合物。","rationale":"出自概念手册「卤代烃」核心概念；背完后可对照该单元的可背诵版核对。","id":"rgo09_q004","chapter":"第九章 卤代烃","chapterIdx":8,"num":4},{"type":"D","stem":"名词解释：瓦尔登翻转","answer":"SN2反应中亲核试剂从背面进攻，使手性碳的构型完全反转的现象，如左旋体变为右旋体，是SN2机理的有力证据。","rationale":"出自概念手册「卤代烃」核心概念；背完后可对照该单元的可背诵版核对。","id":"rgo09_q005","chapter":"第九章 卤代烃","chapterIdx":8,"num":5},{"type":"D","stem":"名词解释：消除反应","answer":"卤代烃在碱作用下脱去卤化氢生成烯烃的反应，按机理分为E1和E2，与亲核取代反应相互竞争。","rationale":"出自概念手册「卤代烃」核心概念；背完后可对照该单元的可背诵版核对。","id":"rgo09_q006","chapter":"第九章 卤代烃","chapterIdx":8,"num":6},{"type":"D","stem":"名词解释：E2 消除","answer":"双分子消除反应，碱夺取β-氢的同时卤素离去，要求氢与卤素处于反式共平面，速率与底物和碱浓度均有关，是常用的制烯方法。","rationale":"出自概念手册「卤代烃」核心概念；背完后可对照该单元的可背诵版核对。","id":"rgo09_q007","chapter":"第九章 卤代烃","chapterIdx":8,"num":7},{"type":"D","stem":"名词解释：E1 消除","answer":"单分子消除反应，先离解生成碳正离子，再失去β-质子形成双键，速率只与底物浓度有关，常与SN1反应伴生。","rationale":"出自概念手册「卤代烃」核心概念；背完后可对照该单元的可背诵版核对。","id":"rgo09_q008","chapter":"第九章 卤代烃","chapterIdx":8,"num":8},{"type":"D","stem":"名词解释：札依采夫规则","answer":"卤代烃消除时优先脱去含氢较少的β-碳上的氢，生成取代较多、较稳定的烯烃，是E1和多数E2反应的取向规律。","rationale":"出自概念手册「卤代烃」核心概念；背完后可对照该单元的可背诵版核对。","id":"rgo09_q009","chapter":"第九章 卤代烃","chapterIdx":8,"num":9},{"type":"D","stem":"名词解释：霍夫曼消除","answer":"季铵碱受热分解或使用体积庞大的强碱如叔丁醇钾时，碱优先夺取空间位阻小的β-氢，主要生成取代较少的烯烃，与札依采夫规则的取向相反，又称霍夫曼取向。","rationale":"出自概念手册「卤代烃」核心概念；背完后可对照该单元的可背诵版核对。","id":"rgo09_q010","chapter":"第九章 卤代烃","chapterIdx":8,"num":10},{"type":"D","stem":"名词解释：格氏试剂","answer":"卤代烃与镁在无水乙醚中反应生成的烷基卤化镁，通式RMgX，碳镁键极性很强，是重要的亲核试剂和有机合成中间体。","rationale":"出自概念手册「卤代烃」核心概念；背完后可对照该单元的可背诵版核对。","id":"rgo09_q011","chapter":"第九章 卤代烃","chapterIdx":8,"num":11},{"type":"D","stem":"名词解释：有机锂试剂","answer":"卤代烃与金属锂在无水乙醚中反应生成的烷基锂，通式RLi，比格氏试剂更活泼，可溶于烃类溶剂，常用于制备其他有机金属试剂。","rationale":"出自概念手册「卤代烃」核心概念；背完后可对照该单元的可背诵版核对。","id":"rgo09_q012","chapter":"第九章 卤代烃","chapterIdx":8,"num":12},{"type":"D","stem":"名词解释：乙烯基卤","answer":"卤素直接连在双键碳上的卤代烃，如氯乙烯；因p-π共轭使碳卤键增强，亲核取代反应极难进行。","rationale":"出自概念手册「卤代烃」核心概念；背完后可对照该单元的可背诵版核对。","id":"rgo09_q013","chapter":"第九章 卤代烃","chapterIdx":8,"num":13},{"type":"D","stem":"名词解释：芳基卤","answer":"卤素直接连在芳环上的卤代烃，如氯苯；卤素与苯环的p-π共轭使碳卤键稳定，普通条件不发生亲核取代，需高温高压或特殊催化剂。","rationale":"出自概念手册「卤代烃」核心概念；背完后可对照该单元的可背诵版核对。","id":"rgo09_q014","chapter":"第九章 卤代烃","chapterIdx":8,"num":14},{"type":"D","stem":"名词解释：烯丙型卤代烃","answer":"卤素连在与双键相邻碳上的卤代烃，如烯丙基溴；生成的碳正离子和过渡态有共轭稳定作用，SN1和SN2活性都较高。","rationale":"出自概念手册「卤代烃」核心概念；背完后可对照该单元的可背诵版核对。","id":"rgo09_q015","chapter":"第九章 卤代烃","chapterIdx":8,"num":15},{"type":"D","stem":"名词解释：卤代烃的鉴别","answer":"利用卤代烃与硝酸银醇溶液反应生成卤化银沉淀的快慢判断其结构类型，活性顺序为叔大于仲大于伯，乙烯基卤和芳基卤不反应。","rationale":"出自概念手册「卤代烃」核心概念；背完后可对照该单元的可背诵版核对。","id":"rgo09_q016","chapter":"第九章 卤代烃","chapterIdx":8,"num":16},{"type":"S","stem":"简答题：比较 SN1 与 SN2 反应机理的差异。","answer":"①动力学：SN1 为单分子反应，v=k[RX]；SN2 为双分子反应，v=k[RX][Nu⁻]。②历程：SN1 分两步，先慢步骤离解生成碳正离子，再被亲核试剂快速进攻；SN2 一步完成，亲核试剂从离去基团的背面进攻，经五配位过渡态。③立体化学：SN1 因碳正离子为平面结构，产物发生外消旋化（构型翻转与保持各约一半）；SN2 则使构型完全翻转，即瓦尔登转化。④影响因素：SN1 有利于叔卤代烷、弱亲核试剂、极性质子溶剂；SN2 有利于伯卤代烷、强亲核试剂、极性非质子溶剂。⑤副反应：SN1 常伴随碳正离子重排和 E1 消除；SN2 常伴随 E2 消除。","rationale":"采分点是“分子数、一步或两步、构型翻转或外消旋、影响因素”四项对比。易错点：把烯丙基、苄基卤简单归为只走一种机理。","id":"rgo09_q017","chapter":"第九章 卤代烃","chapterIdx":8,"num":17},{"type":"F","stem":"填空题：卤代烷与氢氧化钠的______溶液共热，主要发生取代反应生成醇；与氢氧化钠的______溶液共热，主要发生消除反应生成烯烃。","answer":"①水 ②醇（醇中碱性强、溶剂化程度低，有利于夺取 β-H 发生消除）","rationale":"水是极性质子溶剂，有利于生成碳正离子和亲核取代；醇溶液中碱性强、碱性离子不易被溶剂化，有利于消除。这是实验室控制产物的常用手段。","id":"rgo09_q018","chapter":"第九章 卤代烃","chapterIdx":8,"num":18},{"type":"F","stem":"填空题：卤代烷发生消除反应时，卤素与 β-碳上的氢同时脱去，主要生成双键碳上取代基较______的烯烃，这一取向规律称为______规则。","answer":"①多 ②扎伊采夫（Zaitsev，生成取代基多的烯烃更稳定，属热力学控制）","rationale":"消除反应的取向由产物烯烃的稳定性决定。使用体积大的强碱（如叔丁醇钾）时可得反扎伊采夫产物，这是重要的例外。","id":"rgo09_q019","chapter":"第九章 卤代烃","chapterIdx":8,"num":19},{"type":"T","stem":"判断题：叔溴丁烷在含水乙醇中水解，主要按 SN2 机理进行。","options":{"A":"正确","B":"错误"},"answer":["B"],"rationale":"叔卤代烷空间位阻大，亲核试剂难以从背面进攻，但所生成的叔碳正离子很稳定，故主要按 SN1 机理水解，并伴有重排和消除产物。","id":"rgo09_q020","chapter":"第九章 卤代烃","chapterIdx":8,"num":20},{"type":"T","stem":"判断题：卤代烷中碳卤键的键能随卤素原子序数增大而减小，故碘代烷最易发生亲核取代反应。","options":{"A":"正确","B":"错误"},"answer":["A"],"rationale":"碳卤键强度顺序为 C—F > C—Cl > C—Br > C—I，故反应活性为 RI > RBr > RCl > RF。但碘代烷也最易被氧化、见光分解，通常需避光保存。","id":"rgo09_q021","chapter":"第九章 卤代烃","chapterIdx":8,"num":21}]},{"title":"第十章 醇、酚、醚","questions":[{"type":"D","stem":"名词解释：醇","answer":"烃分子中饱和碳上的氢被羟基取代形成的化合物，通式R-OH，羟基为官能团，按羟基所连碳分为伯醇、仲醇和叔醇。","rationale":"出自概念手册「醇、酚、醚」核心概念；背完后可对照该单元的可背诵版核对。","id":"rgo10_q001","chapter":"第十章 醇、酚、醚","chapterIdx":9,"num":1},{"type":"D","stem":"名词解释：酚","answer":"羟基直接连在芳环上的化合物，如苯酚；羟基与苯环共轭使O-H键极性增大，酸性明显强于醇，并易发生芳环亲电取代。","rationale":"出自概念手册「醇、酚、醚」核心概念；背完后可对照该单元的可背诵版核对。","id":"rgo10_q002","chapter":"第十章 醇、酚、醚","chapterIdx":9,"num":2},{"type":"D","stem":"名词解释：醚","answer":"两个烃基通过氧原子相连的化合物，通式R-O-R′，醚键稳定，化学性质不活泼，常用作有机溶剂。","rationale":"出自概念手册「醇、酚、醚」核心概念；背完后可对照该单元的可背诵版核对。","id":"rgo10_q003","chapter":"第十章 醇、酚、醚","chapterIdx":9,"num":3},{"type":"D","stem":"名词解释：醇的酸性","answer":"醇羟基的氢可部分解离，pKa约为16至18，酸性弱于水而强于炔烃；与金属钠反应生成醇盐和氢气，酸性随烷基给电子能力增强而减弱。","rationale":"出自概念手册「醇、酚、醚」核心概念；背完后可对照该单元的可背诵版核对。","id":"rgo10_q005","chapter":"第十章 醇、酚、醚","chapterIdx":9,"num":5},{"type":"D","stem":"名词解释：醇盐","answer":"醇羟基氢被金属取代形成的化合物，如乙醇钠；是强碱和强亲核试剂，遇水即水解，常用于消除反应和威廉姆逊合成。","rationale":"出自概念手册「醇、酚、醚」核心概念；背完后可对照该单元的可背诵版核对。","id":"rgo10_q006","chapter":"第十章 醇、酚、醚","chapterIdx":9,"num":6},{"type":"D","stem":"名词解释：卢卡斯试剂","answer":"无水氯化锌与浓盐酸配成的试剂，用于鉴别伯、仲、叔醇：叔醇立即浑浊，仲醇数分钟浑浊，伯醇需加热才反应。","rationale":"出自概念手册「醇、酚、醚」核心概念；背完后可对照该单元的可背诵版核对。","id":"rgo10_q007","chapter":"第十章 醇、酚、醚","chapterIdx":9,"num":7},{"type":"D","stem":"名词解释：醇的脱水","answer":"醇在酸催化下脱去水生成烯烃或醚的反应；分子内脱水生成烯烃并遵循札依采夫规则，分子间脱水生成醚，温度决定产物。","rationale":"出自概念手册「醇、酚、醚」核心概念；背完后可对照该单元的可背诵版核对。","id":"rgo10_q008","chapter":"第十章 醇、酚、醚","chapterIdx":9,"num":8},{"type":"D","stem":"名词解释：酚的酸性","answer":"苯酚的pKa约为10，酸性强于醇而弱于碳酸，能溶于氢氧化钠溶液但不溶于碳酸氢钠溶液；苯氧负离子因共轭而稳定，故酸性远强于醇。","rationale":"出自概念手册「醇、酚、醚」核心概念；背完后可对照该单元的可背诵版核对。","id":"rgo10_q009","chapter":"第十章 醇、酚、醚","chapterIdx":9,"num":9},{"type":"D","stem":"名词解释：酚的铁离子显色","answer":"酚与三氯化铁溶液作用生成有色配合物的反应，苯酚显紫色，不同取代酚颜色不同，常用于酚类药物的鉴别。","rationale":"出自概念手册「醇、酚、醚」核心概念；背完后可对照该单元的可背诵版核对。","id":"rgo10_q010","chapter":"第十章 醇、酚、醚","chapterIdx":9,"num":10},{"type":"D","stem":"名词解释：威廉姆逊合成","answer":"醇钠与卤代烃发生SN2反应生成醚的方法，卤代烃以伯卤代烷效果最好，叔卤代烷则主要发生消除而生成烯烃。","rationale":"出自概念手册「醇、酚、醚」核心概念；背完后可对照该单元的可背诵版核对。","id":"rgo10_q011","chapter":"第十章 醇、酚、醚","chapterIdx":9,"num":11},{"type":"D","stem":"名词解释：环氧乙烷","answer":"最简单的环氧化合物，三元环张力大，易被亲核试剂开环；酸性条件亲核试剂进攻取代较多的碳，碱性条件进攻位阻较小的碳。","rationale":"出自概念手册「醇、酚、醚」核心概念；背完后可对照该单元的可背诵版核对。","id":"rgo10_q012","chapter":"第十章 醇、酚、醚","chapterIdx":9,"num":12},{"type":"D","stem":"名词解释：醚的过氧化物","answer":"醚在空气中久置被氧化生成的过氧化物，受热易爆炸，蒸馏乙醚前须用碘化钾淀粉试纸检验并除去过氧化物。","rationale":"出自概念手册「醇、酚、醚」核心概念；背完后可对照该单元的可背诵版核对。","id":"rgo10_q013","chapter":"第十章 醇、酚、醚","chapterIdx":9,"num":13},{"type":"D","stem":"名词解释：醇的氧化","answer":"醇在氧化剂作用下失去氢的反应：伯醇氧化为醛并可继续氧化为羧酸，仲醇氧化为酮，叔醇无α-氢一般不被氧化。","rationale":"出自概念手册「醇、酚、醚」核心概念；背完后可对照该单元的可背诵版核对。","id":"rgo10_q014","chapter":"第十章 醇、酚、醚","chapterIdx":9,"num":14},{"type":"D","stem":"名词解释：酚的亲电取代","answer":"酚羟基使苯环电子云密度显著升高，酚的亲电取代比苯容易，与溴水即生成2,4,6-三溴苯酚白色沉淀，可用于鉴别。","rationale":"出自概念手册「醇、酚、醚」核心概念；背完后可对照该单元的可背诵版核对。","id":"rgo10_q015","chapter":"第十章 醇、酚、醚","chapterIdx":9,"num":15},{"type":"F","stem":"填空题：酚羟基使苯环电子云密度显著升高，______比苯容易，与溴水即生成2,4,6-三溴苯酚白色沉淀，可用于鉴别。","answer":"酚的亲电取代","rationale":"出自概念手册「醇、酚、醚」核心概念：酚的亲电取代。","id":"rgo10_q016","chapter":"第十章 醇、酚、醚","chapterIdx":9,"num":16},{"type":"D","stem":"名词解释：醇的卤代","answer":"醇与卤化氢、五氯化磷或氯化亚砜反应生成卤代烃的反应，活性为叔醇大于仲醇大于伯醇，氢卤酸中碘化氢活性最高。","rationale":"出自概念手册「醇、酚、醚」核心概念；背完后可对照该单元的可背诵版核对。","id":"rgo10_q017","chapter":"第十章 醇、酚、醚","chapterIdx":9,"num":17},{"type":"D","stem":"名词解释：醇的鉴别","answer":"利用卢卡斯试剂、碘仿反应或铬酸氧化等现象区分醇的类别：含CH3CH(OH)-结构的醇能发生碘仿反应，伯醇和仲醇可被铬酸氧化变色。","rationale":"出自概念手册「醇、酚、醚」核心概念；背完后可对照该单元的可背诵版核对。","id":"rgo10_q018","chapter":"第十章 醇、酚、醚","chapterIdx":9,"num":18},{"type":"S","stem":"简答题：比较醇、酚、醚的结构特点与主要化学性质。","answer":"①醇：羟基连在 sp3 饱和碳上，O—H 与 C—O 键均有极性；可与金属钠反应放出氢气，与卤化氢反应生成卤代烃，可脱水成醚或烯，可被氧化（伯醇成醛、仲醇成酮、叔醇一般不被氧化）。②酚：羟基直接连在苯环上，氧的孤对电子与苯环发生 p-π 共轭，使 O—H 键易电离，故酸性强于醇而弱于碳酸。③酚可与氢氧化钠成盐，但不能与碳酸氢钠反应，故可用碳酸氢钠区分酚与羧酸。④酚易被氧化，与三氯化铁溶液显紫色，与浓溴水生成 2,4,6-三溴苯酚白色沉淀。⑤醚：氧上无氢，分子间不能形成氢键，沸点比同碳数醇低得多，性质稳定，可与浓强酸成盐，可被氢碘酸断裂。","rationale":"采分点是“醇的酸性弱于酚、酚的显色与溴水沉淀、醚的惰性与低沸点”。易错点：把酚的酸性说成强于碳酸，或漏掉醚能与强酸成盐。","id":"rgo10_q019","chapter":"第十章 醇、酚、醚","chapterIdx":9,"num":19},{"type":"F","stem":"填空题：乙醇在浓硫酸存在下加热到 140 ℃ 主要发生分子间脱水生成______；加热到 170 ℃ 主要发生分子内脱水生成______。","answer":"①乙醚（分子间脱水成醚） ②乙烯（分子内脱水成烯，170 ℃ 时为主产物）","rationale":"温度决定脱水方式：较低温度下生成醚，较高温度下生成烯。分子内脱水遵循扎伊采夫规则，主要生成较稳定的烯烃。","id":"rgo10_q020","chapter":"第十章 醇、酚、醚","chapterIdx":9,"num":20},{"type":"F","stem":"填空题：苯酚与三氯化铁溶液作用显______色，与浓溴水作用生成______色沉淀。","answer":"①紫（酚类与 FeCl3 的显色反应） ②白（2,4,6-三溴苯酚为难溶于水的白色固体）","rationale":"这两个反应都是酚的特征鉴别反应。苯酚与溴水反应不需催化剂，说明羟基是强致活基团，这与苯需路易斯酸催化形成对比。","id":"rgo10_q021","chapter":"第十章 醇、酚、醚","chapterIdx":9,"num":21},{"type":"T","stem":"判断题：苯酚的酸性比碳酸强，因此苯酚能与碳酸氢钠溶液反应放出二氧化碳。","options":{"A":"正确","B":"错误"},"answer":["B"],"rationale":"苯酚酸性弱于碳酸，只能与氢氧化钠成盐，不能与碳酸氢钠反应放出二氧化碳。正因如此，碳酸氢钠可用来区分酚与羧酸。","id":"rgo10_q022","chapter":"第十章 醇、酚、醚","chapterIdx":9,"num":22},{"type":"T","stem":"判断题：卢卡斯试剂可用于区分伯、仲、叔醇，现象是叔醇立即出现浑浊，伯醇在室温下长时间无变化。","options":{"A":"正确","B":"错误"},"answer":["A"],"rationale":"卢卡斯试剂是无水氯化锌的浓盐酸溶液，反应按 SN1 机理进行，碳正离子越稳定反应越快，故叔醇立即浑浊、仲醇数分钟浑浊、伯醇需加热。该法只适用于六个碳以下的水溶性醇。","id":"rgo10_q023","chapter":"第十章 醇、酚、醚","chapterIdx":9,"num":23}]},{"title":"第十一章 醛、酮、醌","questions":[{"type":"D","stem":"名词解释：羰基化合物","answer":"分子中含有碳氧双键（C=O）的化合物，包括醛、酮、醌及羧酸衍生物等，羰基碳为sp2杂化，是亲核加成的活性中心。","rationale":"出自概念手册「醛、酮、醌」核心概念；背完后可对照该单元的可背诵版核对。","id":"rgo11_q001","chapter":"第十一章 醛、酮、醌","chapterIdx":10,"num":1},{"type":"D","stem":"名词解释：醛","answer":"羰基碳原子至少与一个氢原子相连的化合物，通式RCHO（甲醛为HCHO），可被弱氧化剂氧化成羧酸，这是其还原性与鉴别反应的结构基础。","rationale":"出自概念手册「醛、酮、醌」核心概念；背完后可对照该单元的可背诵版核对。","id":"rgo11_q002","chapter":"第十一章 醛、酮、醌","chapterIdx":10,"num":2},{"type":"D","stem":"名词解释：酮","answer":"羰基碳原子与两个烃基相连的化合物，通式RCOR'，不能被托伦试剂或斐林试剂氧化，但可被强氧化剂氧化断链生成羧酸混合物。","rationale":"出自概念手册「醛、酮、醌」核心概念；背完后可对照该单元的可背诵版核对。","id":"rgo11_q003","chapter":"第十一章 醛、酮、醌","chapterIdx":10,"num":3},{"type":"D","stem":"名词解释：亲核加成反应","answer":"亲核试剂进攻带部分正电荷的羰基碳，羰基π键断裂、氧带负电荷，再经质子化生成加成产物的反应，是醛酮的典型反应。","rationale":"出自概念手册「醛、酮、醌」核心概念；背完后可对照该单元的可背诵版核对。","id":"rgo11_q004","chapter":"第十一章 醛、酮、醌","chapterIdx":10,"num":4},{"type":"D","stem":"名词解释：α-氢的酸性","answer":"与羰基直接相连的碳原子上的氢，受羰基强吸电子诱导效应与共轭稳定作用而显酸性，pKa约17~20，可被强碱夺去。","rationale":"出自概念手册「醛、酮、醌」核心概念；背完后可对照该单元的可背诵版核对。","id":"rgo11_q005","chapter":"第十一章 醛、酮、醌","chapterIdx":10,"num":5},{"type":"D","stem":"名词解释：烯醇负离子","answer":"α-氢被碱夺去后形成的碳负离子与烯醇氧负离子的共振杂化体，既是亲核试剂又是强碱，是羟醛缩合与α-卤代反应的活性中间体。","rationale":"出自概念手册「醛、酮、醌」核心概念；背完后可对照该单元的可背诵版核对。","id":"rgo11_q006","chapter":"第十一章 醛、酮、醌","chapterIdx":10,"num":6},{"type":"D","stem":"名词解释：羟醛缩合","answer":"含α-氢的醛在稀碱催化下，一分子醛的α-碳进攻另一分子醛的羰基生成β-羟基醛，加热脱水得α,β-不饱和醛的反应。","rationale":"出自概念手册「醛、酮、醌」核心概念；背完后可对照该单元的可背诵版核对。","id":"rgo11_q007","chapter":"第十一章 醛、酮、醌","chapterIdx":10,"num":7},{"type":"D","stem":"名词解释：碘仿反应","answer":"含CH3CO—结构（乙醛、甲基酮）或可被氧化成该结构的CH3CH(OH)—化合物，与碘的氢氧化钠溶液作用生成黄色碘仿沉淀的反应，用于鉴别。","rationale":"出自概念手册「醛、酮、醌」核心概念；背完后可对照该单元的可背诵版核对。","id":"rgo11_q008","chapter":"第十一章 醛、酮、醌","chapterIdx":10,"num":8},{"type":"D","stem":"名词解释：坎尼扎罗反应","answer":"无α-氢的醛在浓碱作用下发生歧化，两分子醛中一分子被氧化成羧酸盐、另一分子被还原成醇的反应。","rationale":"出自概念手册「醛、酮、醌」核心概念；背完后可对照该单元的可背诵版核对。","id":"rgo11_q009","chapter":"第十一章 醛、酮、醌","chapterIdx":10,"num":9},{"type":"D","stem":"名词解释：托伦试剂","answer":"硝酸银的氨溶液即银氨溶液，属弱氧化剂，与醛共热生成银镜，与酮不反应，是区分醛与酮的经典试剂。","rationale":"出自概念手册「醛、酮、醌」核心概念；背完后可对照该单元的可背诵版核对。","id":"rgo11_q010","chapter":"第十一章 醛、酮、醌","chapterIdx":10,"num":10},{"type":"D","stem":"名词解释：斐林试剂","answer":"硫酸铜与酒石酸钾钠的碱性溶液，属弱氧化剂，与脂肪醛共热生成砖红色氧化亚铜沉淀，芳香醛一般不反应。","rationale":"出自概念手册「醛、酮、醌」核心概念；背完后可对照该单元的可背诵版核对。","id":"rgo11_q011","chapter":"第十一章 醛、酮、醌","chapterIdx":10,"num":11},{"type":"D","stem":"名词解释：希夫试剂","answer":"品红的亚硫酸无色溶液，与醛作用显紫红色，加浓硫酸后颜色不褪者为甲醛，可用于醛的检验及甲醛与其他醛的区分。","rationale":"出自概念手册「醛、酮、醌」核心概念；背完后可对照该单元的可背诵版核对。","id":"rgo11_q012","chapter":"第十一章 醛、酮、醌","chapterIdx":10,"num":12},{"type":"D","stem":"名词解释：亚硫酸氢钠加成","answer":"饱和亚硫酸氢钠溶液与醛、脂肪族甲基酮及八元以下环酮加成生成羟基磺酸钠，产物不溶于饱和亚硫酸氢钠，用于分离提纯。","rationale":"出自概念手册「醛、酮、醌」核心概念；背完后可对照该单元的可背诵版核对。","id":"rgo11_q013","chapter":"第十一章 醛、酮、醌","chapterIdx":10,"num":13},{"type":"D","stem":"名词解释：缩醛与缩酮","answer":"醛或酮与两分子醇在干燥氯化氢催化下生成的产物，对碱和氧化剂稳定，在稀酸中水解恢复羰基，常用作羰基保护。","rationale":"出自概念手册「醛、酮、醌」核心概念；背完后可对照该单元的可背诵版核对。","id":"rgo11_q014","chapter":"第十一章 醛、酮、醌","chapterIdx":10,"num":14},{"type":"D","stem":"名词解释：克莱门森还原","answer":"醛或酮与锌汞齐在浓盐酸中加热，羰基被还原为亚甲基的反应，适用于对碱敏感而对酸稳定的底物。","rationale":"出自概念手册「醛、酮、醌」核心概念；背完后可对照该单元的可背诵版核对。","id":"rgo11_q015","chapter":"第十一章 醛、酮、醌","chapterIdx":10,"num":15},{"type":"D","stem":"名词解释：沃尔夫-凯惜纳-黄鸣龙还原","answer":"醛或酮与肼在高沸点溶剂中经强碱催化生成腙，再分解放出氮生成亚甲基的反应，黄鸣龙改良法适用于对酸敏感的底物。","rationale":"出自概念手册「醛、酮、醌」核心概念；背完后可对照该单元的可背诵版核对。","id":"rgo11_q016","chapter":"第十一章 醛、酮、醌","chapterIdx":10,"num":16},{"type":"D","stem":"名词解释：安息香缩合","answer":"两分子苯甲醛在氰离子催化下缩合生成安息香（苯偶姻）的反应，氰离子使羰基碳由亲电变为亲核，属极性反转。","rationale":"出自概念手册「醛、酮、醌」核心概念；背完后可对照该单元的可背诵版核对。","id":"rgo11_q017","chapter":"第十一章 醛、酮、醌","chapterIdx":10,"num":17},{"type":"D","stem":"名词解释：醌","answer":"含共轭环己二烯二酮结构的化合物，如对苯醌，为有色结晶，具α,β-不饱和酮性质，可发生1,4-加成，还原生成对苯二酚。","rationale":"出自概念手册「醛、酮、醌」核心概念；背完后可对照该单元的可背诵版核对。","id":"rgo11_q018","chapter":"第十一章 醛、酮、醌","chapterIdx":10,"num":18},{"type":"S","stem":"简答题：如何用化学方法区分醛和酮？写出所用试剂与现象。","answer":"①托伦试剂（硝酸银的氨溶液）：醛在水浴加热下生成银镜，酮不反应，可用于区分。②斐林试剂（新制氢氧化铜悬浊液）：脂肪醛加热生成砖红色氧化亚铜沉淀，酮不反应；芳香醛也不与斐林试剂反应，故斐林试剂还能区分脂肪醛与芳香醛。③溴水：醛可被溴水氧化而使溴褪色，酮不能。④希夫试剂：醛显紫红色，酮不显色。⑤与饱和亚硫酸氢钠、氢氰酸、格氏试剂的加成反应醛和酮都能发生，不能用于区分。","rationale":"采分点是“银镜、砖红色沉淀、溴水褪色”三种现象对应试剂。易错点：误认为芳香醛能还原斐林试剂，或误用亚硫酸氢钠加成来区分醛酮。","id":"rgo11_q019","chapter":"第十一章 醛、酮、醌","chapterIdx":10,"num":19},{"type":"F","stem":"填空题：醛与托伦试剂共热，在容器内壁生成______，该反应说明醛具有______性。","answer":"①银镜（析出银白色的金属银） ②还原（醛被氧化成羧酸，银离子被还原成银）","rationale":"托伦试剂是弱氧化剂，只能氧化醛而不能氧化酮，故是区分醛酮的经典试剂。反应须在碱性条件下水浴加热，酸性条件会使试剂失效。","id":"rgo11_q020","chapter":"第十一章 醛、酮、醌","chapterIdx":10,"num":20},{"type":"F","stem":"填空题：含______结构的醛或酮（如乙醛、丙酮）能发生碘仿反应，现象是生成______色沉淀。","answer":"①CH3CO—（甲基酮基，或 CH3CH(OH)— 结构） ②黄（碘仿 CHI3 为黄色结晶）","rationale":"凡含 CH3CO— 或可被次卤酸氧化成 CH3CO— 的结构（如乙醇、异丙醇）均显阳性。碘仿反应既是鉴别反应，也可用于制备碘仿。","id":"rgo11_q021","chapter":"第十一章 醛、酮、醌","chapterIdx":10,"num":21},{"type":"T","stem":"判断题：苯甲醛能被斐林试剂氧化，生成砖红色沉淀。","options":{"A":"正确","B":"错误"},"answer":["B"],"rationale":"芳香醛只能被托伦试剂氧化，不与斐林试剂反应。斐林试剂恰好可用来区分脂肪醛与芳香醛，现象为脂肪醛生成砖红色氧化亚铜沉淀。","id":"rgo11_q022","chapter":"第十一章 醛、酮、醌","chapterIdx":10,"num":22},{"type":"T","stem":"判断题：醛酮的羰基碳为 sp2 杂化，氧的电负性大于碳，故羰基是极性不饱和键，易发生亲核加成。","options":{"A":"正确","B":"错误"},"answer":["A"],"rationale":"C=O 极化后碳带部分正电荷、氧带部分负电荷，亲核试剂先进攻羰基碳，故醛酮的典型反应是亲核加成。亲核加成活性醛大于酮，因酮有两个烷基的位阻与给电子作用。","id":"rgo11_q023","chapter":"第十一章 醛、酮、醌","chapterIdx":10,"num":23}]},{"title":"第十二章 羧酸及羧酸衍生物","questions":[{"type":"D","stem":"名词解释：羧酸","answer":"烃基与羧基相连的化合物，通式RCOOH，羧基中羟基氧的孤对电子与羰基共轭，使两个碳氧键趋于等同，酸性明显强于醇和酚。","rationale":"出自概念手册「羧酸及羧酸衍生物」核心概念；背完后可对照该单元的可背诵版核对。","id":"rgo12_q001","chapter":"第十二章 羧酸及羧酸衍生物","chapterIdx":11,"num":1},{"type":"D","stem":"名词解释：羧酸衍生物","answer":"羧基中的羟基被卤素、酰氧基、烷氧基或氨基取代所得的化合物，包括酰卤、酸酐、酯和酰胺，均可发生酰基亲核取代。","rationale":"出自概念手册「羧酸及羧酸衍生物」核心概念；背完后可对照该单元的可背诵版核对。","id":"rgo12_q002","chapter":"第十二章 羧酸及羧酸衍生物","chapterIdx":11,"num":2},{"type":"D","stem":"名词解释：酰卤","answer":"羧酸中的羟基被卤素取代的衍生物，通式RCOX，以酰氯最常用，活性最高，遇水剧烈水解，是酰化反应的常用试剂。","rationale":"出自概念手册「羧酸及羧酸衍生物」核心概念；背完后可对照该单元的可背诵版核对。","id":"rgo12_q003","chapter":"第十二章 羧酸及羧酸衍生物","chapterIdx":11,"num":3},{"type":"D","stem":"名词解释：酸酐","answer":"两分子羧酸脱去一分子水所得的衍生物，通式(RCO)2O，分子内脱水者称环状酸酐，活性仅次于酰氯，常用作酰化剂。","rationale":"出自概念手册「羧酸及羧酸衍生物」核心概念；背完后可对照该单元的可背诵版核对。","id":"rgo12_q004","chapter":"第十二章 羧酸及羧酸衍生物","chapterIdx":11,"num":4},{"type":"F","stem":"填空题：两分子羧酸脱去一分子水所得的衍生物，通式(RCO)2O，分子内脱水者称环状______，活性仅次于酰氯，常用作酰化剂。","answer":"酸酐","rationale":"出自概念手册「羧酸及羧酸衍生物」核心概念：酸酐。","id":"rgo12_q005","chapter":"第十二章 羧酸及羧酸衍生物","chapterIdx":11,"num":5},{"type":"D","stem":"名词解释：酯","answer":"羧酸与醇脱水生成的衍生物，通式RCOOR'，活性较低，在酸或碱催化下可水解，碱性水解不可逆，称为皂化。","rationale":"出自概念手册「羧酸及羧酸衍生物」核心概念；背完后可对照该单元的可背诵版核对。","id":"rgo12_q006","chapter":"第十二章 羧酸及羧酸衍生物","chapterIdx":11,"num":6},{"type":"D","stem":"名词解释：酰胺","answer":"羧酸中的羟基被氨基或取代氨基置换的衍生物，通式RCONH2，活性最低，需强酸或强碱加热才能水解，可脱水生成腈。","rationale":"出自概念手册「羧酸及羧酸衍生物」核心概念；背完后可对照该单元的可背诵版核对。","id":"rgo12_q007","chapter":"第十二章 羧酸及羧酸衍生物","chapterIdx":11,"num":7},{"type":"D","stem":"名词解释：酰基亲核取代反应","answer":"亲核试剂进攻酰基碳生成四面体中间体，随后消除一个负离子离去基团并重新形成碳氧双键的反应，总结果是被取代。","rationale":"出自概念手册「羧酸及羧酸衍生物」核心概念；背完后可对照该单元的可背诵版核对。","id":"rgo12_q008","chapter":"第十二章 羧酸及羧酸衍生物","chapterIdx":11,"num":8},{"type":"D","stem":"名词解释：酯化反应","answer":"羧酸与醇在酸催化下生成酯和水的可逆反应，常用浓硫酸或干燥氯化氢催化，通过移除产物或使用过量醇提高产率。","rationale":"出自概念手册「羧酸及羧酸衍生物」核心概念；背完后可对照该单元的可背诵版核对。","id":"rgo12_q009","chapter":"第十二章 羧酸及羧酸衍生物","chapterIdx":11,"num":9},{"type":"D","stem":"名词解释：皂化反应","answer":"酯在碱性溶液中水解生成羧酸盐和醇的反应，因生成的羧酸被碱中和而不可逆，油脂的碱性水解制皂即属此类。","rationale":"出自概念手册「羧酸及羧酸衍生物」核心概念；背完后可对照该单元的可背诵版核对。","id":"rgo12_q010","chapter":"第十二章 羧酸及羧酸衍生物","chapterIdx":11,"num":10},{"type":"D","stem":"名词解释：赫尔-乌尔哈-泽林斯基反应","answer":"羧酸在少量红磷存在下与溴或氯作用，α-碳上的氢被卤素取代生成α-卤代羧酸的反应，是制备α-氨基酸的重要步骤。","rationale":"出自概念手册「羧酸及羧酸衍生物」核心概念；背完后可对照该单元的可背诵版核对。","id":"rgo12_q011","chapter":"第十二章 羧酸及羧酸衍生物","chapterIdx":11,"num":11},{"type":"D","stem":"名词解释：罗森蒙德还原","answer":"酰氯在部分失活的钯催化剂存在下经催化氢化还原为醛的反应，催化剂经毒化可避免醛进一步还原为醇。","rationale":"出自概念手册「羧酸及羧酸衍生物」核心概念；背完后可对照该单元的可背诵版核对。","id":"rgo12_q012","chapter":"第十二章 羧酸及羧酸衍生物","chapterIdx":11,"num":12},{"type":"D","stem":"名词解释：霍夫曼降解反应","answer":"酰胺与溴和氢氧化钠溶液作用，脱去羰基生成比原酰胺少一个碳原子的伯胺的反应，过程中不发生烷基重排。","rationale":"出自概念手册「羧酸及羧酸衍生物」核心概念；背完后可对照该单元的可背诵版核对。","id":"rgo12_q013","chapter":"第十二章 羧酸及羧酸衍生物","chapterIdx":11,"num":13},{"type":"D","stem":"名词解释：脱羧反应","answer":"羧酸失去羧基放出二氧化碳生成烃的反应，普通一元羧酸需高温与碱石灰，β-酮酸和丙二酸型化合物加热即可脱羧。","rationale":"出自概念手册「羧酸及羧酸衍生物」核心概念；背完后可对照该单元的可背诵版核对。","id":"rgo12_q014","chapter":"第十二章 羧酸及羧酸衍生物","chapterIdx":11,"num":14},{"type":"D","stem":"名词解释：二元羧酸受热规律","answer":"草酸与丙二酸受热脱羧生成一元羧酸，丁二酸与戊二酸脱水生成五元、六元环状酸酐，己二酸与庚二酸脱羧脱水生成环酮。","rationale":"出自概念手册「羧酸及羧酸衍生物」核心概念；背完后可对照该单元的可背诵版核对。","id":"rgo12_q015","chapter":"第十二章 羧酸及羧酸衍生物","chapterIdx":11,"num":15},{"type":"D","stem":"名词解释：羧酸的酸性","answer":"羧基电离出质子后形成的羧酸根负离子因两个碳氧键等同而高度稳定，故羧酸pKa约4~5，能与碳酸氢钠反应放出二氧化碳。","rationale":"出自概念手册「羧酸及羧酸衍生物」核心概念；背完后可对照该单元的可背诵版核对。","id":"rgo12_q016","chapter":"第十二章 羧酸及羧酸衍生物","chapterIdx":11,"num":16},{"type":"D","stem":"名词解释：酰化反应","answer":"酰卤、酸酐或羧酸在脱水剂存在下与醇、胺等作用，把酰基引入到醇羟基或氨基上生成酯或酰胺的反应。","rationale":"出自概念手册「羧酸及羧酸衍生物」核心概念；背完后可对照该单元的可背诵版核对。","id":"rgo12_q017","chapter":"第十二章 羧酸及羧酸衍生物","chapterIdx":11,"num":17},{"type":"S","stem":"简答题：比较酰卤、酸酐、酯、酰胺的水解（亲核酰基取代）活性顺序，并说明原因。","answer":"①活性顺序为酰卤 > 酸酐 > 酯 > 酰胺。②决定因素是离去基团的性质，离去能力为 Cl⁻ > RCOO⁻ > RO⁻ > NH2⁻，离去基团越弱碱性、越易离去，活性越高。③氮的电负性小于氧、给电子能力强，其孤对电子与羰基共轭最强，使 C—N 键带有部分双键性质、羰基碳正电性降低，故酰胺最稳定。④其次是羰基碳的正电性：与羰基相连的基团吸电子时羰基碳更正，活性更高。⑤因此酰卤极易水解甚至遇空气中的水汽就发烟，而酰胺需在强酸或强碱中长时间加热才能水解。","rationale":"采分点是“活性顺序 + 离去基团离去能力 + 氮的共轭削弱羰基正电性”。易错点：只背顺序而不解释，或把酸酐与酯的顺序颠倒。","id":"rgo12_q018","chapter":"第十二章 羧酸及羧酸衍生物","chapterIdx":11,"num":18},{"type":"F","stem":"填空题：羧酸的酸性比碳酸______，故羧酸能与碳酸氢钠反应放出______，可用此反应与酚相区别。","answer":"①强 ②二氧化碳（CO2，同时生成羧酸钠）","rationale":"羧酸的 pKa 约 4～5，碳酸的 pKa1 约 6.4，酚的 pKa 约 10，故酸性为羧酸 > 碳酸 > 酚。碳酸氢钠只与羧酸反应，是区分二者的常用试剂。","id":"rgo12_q019","chapter":"第十二章 羧酸及羧酸衍生物","chapterIdx":11,"num":19},{"type":"F","stem":"填空题：酰卤、酸酐和酯与氨作用均生成______；乙酰胺在强碱溶液中加热水解，生成乙酸钠并放出______。","answer":"①酰胺（氨解反应，是制备酰胺的常用方法） ②氨气（NH3，可使湿润的红色石蕊试纸变蓝）","rationale":"羧酸衍生物的氨解、醇解和水解都属于亲核酰基取代，机理相同而亲核试剂不同。酰胺碱性水解放氨，可用于含氮量的测定。","id":"rgo12_q020","chapter":"第十二章 羧酸及羧酸衍生物","chapterIdx":11,"num":20},{"type":"T","stem":"判断题：羧酸的 α-碳上连有吸电子基团时酸性增强，且吸电子基越多、离 α-碳越近，酸性越强。","options":{"A":"正确","B":"错误"},"answer":["A"],"rationale":"吸电子诱导效应使 O—H 键电子云偏向氧，并使解离后羧酸根负离子的负电荷得到分散，故酸性增强。三氯乙酸的酸性远强于乙酸，二氯乙酸又强于一氯乙酸。","id":"rgo12_q021","chapter":"第十二章 羧酸及羧酸衍生物","chapterIdx":11,"num":21},{"type":"T","stem":"判断题：酯的碱性水解（皂化）是不可逆的，因为生成的羧酸立即成盐而失去反应活性。","options":{"A":"正确","B":"错误"},"answer":["A"],"rationale":"碱把生成的羧酸中和成羧酸盐，使平衡不断右移，故皂化反应能进行完全。酸催化水解则可逆，需用过量水或不断移去产物。","id":"rgo12_q022","chapter":"第十二章 羧酸及羧酸衍生物","chapterIdx":11,"num":22}]},{"title":"第十三章 取代羧酸","questions":[{"type":"D","stem":"名词解释：取代羧酸","answer":"羧酸烃基上的氢被其他原子或基团取代的化合物，常见为羟基酸、羰基酸和卤代酸，兼具羧基与取代基的双重性质。","rationale":"出自概念手册「取代羧酸」核心概念；背完后可对照该单元的可背诵版核对。","id":"rgo13_q001","chapter":"第十三章 取代羧酸","chapterIdx":12,"num":1},{"type":"D","stem":"名词解释：羟基酸","answer":"羧酸烃基上的氢被羟基取代的化合物，按羟基位置分为α、β、γ、δ等类型，受热脱水方式随羟基位置不同而异。","rationale":"出自概念手册「取代羧酸」核心概念；背完后可对照该单元的可背诵版核对。","id":"rgo13_q002","chapter":"第十三章 取代羧酸","chapterIdx":12,"num":2},{"type":"D","stem":"名词解释：羰基酸","answer":"羧酸烃基上的氢被羰基取代的化合物，包括醛酸与酮酸，α-酮酸与β-酮酸均易脱羧，是糖代谢与三羧酸循环的中间产物。","rationale":"出自概念手册「取代羧酸」核心概念；背完后可对照该单元的可背诵版核对。","id":"rgo13_q003","chapter":"第十三章 取代羧酸","chapterIdx":12,"num":3},{"type":"D","stem":"名词解释：乙酰乙酸乙酯","answer":"β-酮酸酯，简称EAA，由两分子乙酸乙酯在乙醇钠作用下经克莱森缩合制得，其亚甲基氢酸性较强，pKa约11。","rationale":"出自概念手册「取代羧酸」核心概念；背完后可对照该单元的可背诵版核对。","id":"rgo13_q004","chapter":"第十三章 取代羧酸","chapterIdx":12,"num":4},{"type":"D","stem":"名词解释：酮式-烯醇式互变异构","answer":"乙酰乙酸乙酯的酮式与烯醇式在常温下相互转变并达动态平衡的现象，通常酮式约占92%，烯醇式约占8%。","rationale":"出自概念手册「取代羧酸」核心概念；背完后可对照该单元的可背诵版核对。","id":"rgo13_q005","chapter":"第十三章 取代羧酸","chapterIdx":12,"num":5},{"type":"D","stem":"名词解释：丙二酸二乙酯","answer":"丙二酸的二乙酯，简称DEM，其亚甲基受两个酯羰基活化而显酸性，是丙二酸酯合成法的原料。","rationale":"出自概念手册「取代羧酸」核心概念；背完后可对照该单元的可背诵版核对。","id":"rgo13_q006","chapter":"第十三章 取代羧酸","chapterIdx":12,"num":6},{"type":"D","stem":"名词解释：β-二羰基化合物","answer":"两个羰基或酯基被一个碳原子隔开的化合物，其中的亚甲基受两个吸电子基活化而显明显酸性。","rationale":"出自概念手册「取代羧酸」核心概念；背完后可对照该单元的可背诵版核对。","id":"rgo13_q007","chapter":"第十三章 取代羧酸","chapterIdx":12,"num":7},{"type":"D","stem":"名词解释：活性亚甲基化合物","answer":"亚甲基两端连接羰基、酯基、氰基或硝基等吸电子基的化合物，其亚甲基氢可被碱夺去生成稳定的碳负离子。","rationale":"出自概念手册「取代羧酸」核心概念；背完后可对照该单元的可背诵版核对。","id":"rgo13_q008","chapter":"第十三章 取代羧酸","chapterIdx":12,"num":8},{"type":"D","stem":"名词解释：克莱森缩合反应","answer":"含α-氢的酯在强碱常用乙醇钠作用下与另一分子酯缩合，生成β-酮酸酯的反应，是形成碳碳键的重要方法。","rationale":"出自概念手册「取代羧酸」核心概念；背完后可对照该单元的可背诵版核对。","id":"rgo13_q009","chapter":"第十三章 取代羧酸","chapterIdx":12,"num":9},{"type":"D","stem":"名词解释：狄克曼缩合","answer":"二元酸二酯在同一分子内发生的克莱森缩合，生成五元或六元环状β-酮酸酯的反应，属分子内缩合。","rationale":"出自概念手册「取代羧酸」核心概念；背完后可对照该单元的可背诵版核对。","id":"rgo13_q010","chapter":"第十三章 取代羧酸","chapterIdx":12,"num":10},{"type":"D","stem":"名词解释：乙酰乙酸乙酯合成法","answer":"以乙酰乙酸乙酯为原料，经碱夺去亚甲基氢、烷基化，再经酮式或酸式分解制备取代丙酮或羧酸的方法。","rationale":"出自概念手册「取代羧酸」核心概念；背完后可对照该单元的可背诵版核对。","id":"rgo13_q011","chapter":"第十三章 取代羧酸","chapterIdx":12,"num":11},{"type":"D","stem":"名词解释：丙二酸酯合成法","answer":"以丙二酸二乙酯为原料，经烷基化后碱性水解并酸化脱羧，制备取代乙酸即一元羧酸的方法。","rationale":"出自概念手册「取代羧酸」核心概念；背完后可对照该单元的可背诵版核对。","id":"rgo13_q012","chapter":"第十三章 取代羧酸","chapterIdx":12,"num":12},{"type":"D","stem":"名词解释：酮式分解","answer":"乙酰乙酸乙酯烷基化产物在稀碱或稀酸中加热水解并脱羧，生成取代丙酮的反应，因保留酮式结构而得名。","rationale":"出自概念手册「取代羧酸」核心概念；背完后可对照该单元的可背诵版核对。","id":"rgo13_q013","chapter":"第十三章 取代羧酸","chapterIdx":12,"num":13},{"type":"D","stem":"名词解释：酸式分解","answer":"乙酰乙酸乙酯烷基化产物在浓碱中加热，酰基与亚甲基之间断裂生成两分子羧酸盐的反应，酸化后得羧酸。","rationale":"出自概念手册「取代羧酸」核心概念；背完后可对照该单元的可背诵版核对。","id":"rgo13_q014","chapter":"第十三章 取代羧酸","chapterIdx":12,"num":14},{"type":"D","stem":"名词解释：乳酸","answer":"即2-羟基丙酸，存在于酸牛奶中，含一个手性碳故有旋光性，药用其钙盐与钠盐，也可由糖类发酵制得。","rationale":"出自概念手册「取代羧酸」核心概念；背完后可对照该单元的可背诵版核对。","id":"rgo13_q015","chapter":"第十三章 取代羧酸","chapterIdx":12,"num":15},{"type":"D","stem":"名词解释：水杨酸","answer":"即邻羟基苯甲酸，存在于柳树皮中，羟基与羧基处于邻位，与三氯化铁显紫红色，是制备阿司匹林的原料。","rationale":"出自概念手册「取代羧酸」核心概念；背完后可对照该单元的可背诵版核对。","id":"rgo13_q016","chapter":"第十三章 取代羧酸","chapterIdx":12,"num":16},{"type":"D","stem":"名词解释：乙酰水杨酸","answer":"即阿司匹林，由水杨酸经乙酰化制得，遇湿气易水解生成水杨酸与乙酸，药典规定需控制游离水杨酸的限量。","rationale":"出自概念手册「取代羧酸」核心概念；背完后可对照该单元的可背诵版核对。","id":"rgo13_q017","chapter":"第十三章 取代羧酸","chapterIdx":12,"num":17},{"type":"S","stem":"简答题：羟基酸受热脱水产物随羟基位置不同而不同，请分别说明。","answer":"①α-羟基酸：两分子间交错脱水，生成交酯（六元环状二酯）。②β-羟基酸：发生分子内脱水，生成 α,β-不饱和羧酸。③γ-羟基酸和 δ-羟基酸：发生分子内脱水，分别生成五元环和六元环的内酯，因成环稳定故容易进行。④羟基酸中羟基的吸电子诱导效应使酸性强于相应的羧酸，且羟基离羧基越近（α 位）影响越大。⑤羟基酸可被氧化成酮酸或醛酸，酮酸中 β-酮酸受热极易脱羧生成酮，α-酮酸脱羧较难。","rationale":"采分点是“α 成交酯、β 成不饱和酸、γ 与 δ 成内酯”。易错点是把 β-羟基酸也说成生成内酯，忽略三元、四元环不稳定的因素。","id":"rgo13_q018","chapter":"第十三章 取代羧酸","chapterIdx":12,"num":18},{"type":"F","stem":"填空题：α-羟基酸受热时两分子间脱水生成______；γ-羟基酸受热发生分子内脱水，生成五元环的______。","answer":"①交酯（六元环状二酯） ②内酯（分子内酯，成五元环较稳定）","rationale":"脱水方式取决于成环的稳定性：α-羟基酸分子内成三元环不稳定故走分子间；β-羟基酸分子内脱水成烯酸；γ、δ-羟基酸成五、六元环内酯，稳定易成。","id":"rgo13_q019","chapter":"第十三章 取代羧酸","chapterIdx":12,"num":19},{"type":"F","stem":"填空题：乙酰乙酸乙酯存在酮式与烯醇式的互变异构，室温平衡时烯醇式约占______%，加入三氯化铁溶液显______色。","answer":"①7（烯醇式含量较少） ②紫（烯醇式含酚式羟基，与 FeCl3 显紫红色）","rationale":"烯醇式靠分子内氢键和 C=C 与 C=O 的共轭而稳定，故虽为少数仍可检出。乙酰乙酸乙酯与 FeCl3 显色是检验其烯醇式的经典方法。","id":"rgo13_q020","chapter":"第十三章 取代羧酸","chapterIdx":12,"num":20},{"type":"T","stem":"判断题：β-酮酸受热比 α-酮酸更容易脱羧。","options":{"A":"正确","B":"错误"},"answer":["A"],"rationale":"β-酮酸可经六元环过渡态协同脱羧，活化能低，室温或微热即可脱羧生成酮；α-酮酸脱羧需较高温度。这是生物体内酮体代谢的化学基础。","id":"rgo13_q021","chapter":"第十三章 取代羧酸","chapterIdx":12,"num":21},{"type":"T","stem":"判断题：乳酸分子中含一个手性碳原子，因此有一对对映体，其等量混合物不显旋光性。","options":{"A":"正确","B":"错误"},"answer":["A"],"rationale":"乳酸的 C2 连有 —H、—OH、—CH3、—COOH 四个不同基团，是手性碳。故有一对旋光方向相反的对映体，等量混合即外消旋乳酸，无旋光性。","id":"rgo13_q022","chapter":"第十三章 取代羧酸","chapterIdx":12,"num":22}]},{"title":"第十四章 含氮有机化合物","questions":[{"type":"D","stem":"名词解释：胺","answer":"氨分子中的氢被烃基取代形成的化合物，氮原子为sp3杂化并带一对孤对电子，故显碱性并具亲核性。","rationale":"出自概念手册「含氮有机化合物」核心概念；背完后可对照该单元的可背诵版核对。","id":"rgo14_q001","chapter":"第十四章 含氮有机化合物","chapterIdx":13,"num":1},{"type":"D","stem":"名词解释：伯胺、仲胺、叔胺","answer":"按氮原子上所连烃基数目划分，连一个烃基为伯胺，两个为仲胺，三个为叔胺，与卤代烃伯仲叔的划分依据不同。","rationale":"出自概念手册「含氮有机化合物」核心概念；背完后可对照该单元的可背诵版核对。","id":"rgo14_q002","chapter":"第十四章 含氮有机化合物","chapterIdx":13,"num":2},{"type":"D","stem":"名词解释：季铵盐与季铵碱","answer":"叔胺与卤代烃反应生成的四烃基铵盐，属离子型化合物；其氢氧化物为季铵碱，碱性与氢氧化钠、氢氧化钾相当。","rationale":"出自概念手册「含氮有机化合物」核心概念；背完后可对照该单元的可背诵版核对。","id":"rgo14_q003","chapter":"第十四章 含氮有机化合物","chapterIdx":13,"num":3},{"type":"D","stem":"名词解释：胺的碱性","answer":"胺的氮原子以孤对电子接受质子而显碱性，碱性强弱取决于氮上电子云密度与共轭效应，可用共轭酸的pKa表示。","rationale":"出自概念手册「含氮有机化合物」核心概念；背完后可对照该单元的可背诵版核对。","id":"rgo14_q004","chapter":"第十四章 含氮有机化合物","chapterIdx":13,"num":4},{"type":"D","stem":"名词解释：季铵碱的热消除（霍夫曼消除）","answer":"季铵碱受热分解生成烯烃、叔胺和水的反应，消除取向遵循霍夫曼规则，即以生成取代基较少的烯烃为主。","rationale":"出自概念手册「含氮有机化合物」核心概念；背完后可对照该单元的可背诵版核对。","id":"rgo14_q005","chapter":"第十四章 含氮有机化合物","chapterIdx":13,"num":5},{"type":"D","stem":"名词解释：重氮盐","answer":"芳香伯胺在低温强酸中与亚硝酸作用生成的盐，通式ArN2+X-，稳定性差，只在0~5℃的酸性溶液中稳定存在。","rationale":"出自概念手册「含氮有机化合物」核心概念；背完后可对照该单元的可背诵版核对。","id":"rgo14_q006","chapter":"第十四章 含氮有机化合物","chapterIdx":13,"num":6},{"type":"D","stem":"名词解释：重氮化反应","answer":"芳香伯胺与亚硝酸在低温下作用生成重氮盐的反应，亚硝酸由亚硝酸钠与盐酸或硫酸原位生成，须强酸过量并控制温度。","rationale":"出自概念手册「含氮有机化合物」核心概念；背完后可对照该单元的可背诵版核对。","id":"rgo14_q007","chapter":"第十四章 含氮有机化合物","chapterIdx":13,"num":7},{"type":"D","stem":"名词解释：偶合反应","answer":"重氮盐作为弱亲电试剂与酚或芳香胺发生亲电取代生成偶氮化合物的反应，介质酸碱性与取代基决定偶合位置。","rationale":"出自概念手册「含氮有机化合物」核心概念；背完后可对照该单元的可背诵版核对。","id":"rgo14_q008","chapter":"第十四章 含氮有机化合物","chapterIdx":13,"num":8},{"type":"D","stem":"名词解释：桑德迈尔反应","answer":"重氮盐在氯化亚铜或溴化亚铜催化下，重氮基被氯或溴取代生成卤代芳烃的反应，是制备取代卤苯的常用方法。","rationale":"出自概念手册「含氮有机化合物」核心概念；背完后可对照该单元的可背诵版核对。","id":"rgo14_q009","chapter":"第十四章 含氮有机化合物","chapterIdx":13,"num":9},{"type":"D","stem":"名词解释：盖特曼反应","answer":"重氮盐在铜粉存在下与盐酸或氢溴酸作用，重氮基被氯或溴取代的反应，与桑德迈尔反应类似而催化剂不同。","rationale":"出自概念手册「含氮有机化合物」核心概念；背完后可对照该单元的可背诵版核对。","id":"rgo14_q010","chapter":"第十四章 含氮有机化合物","chapterIdx":13,"num":10},{"type":"D","stem":"名词解释：兴斯堡反应","answer":"胺与苯磺酰氯在氢氧化钠溶液中作用，伯胺生成可溶性磺酰胺盐、仲胺生成不溶性磺酰胺、叔胺不反应，用于鉴别与分离。","rationale":"出自概念手册「含氮有机化合物」核心概念；背完后可对照该单元的可背诵版核对。","id":"rgo14_q011","chapter":"第十四章 含氮有机化合物","chapterIdx":13,"num":11},{"type":"D","stem":"名词解释：亚硝酸试验","answer":"胺与亚硝酸的作用因类型而异：脂肪伯胺放出氮气，芳香伯胺生成重氮盐，仲胺生成黄色N-亚硝基胺，叔胺生成盐。","rationale":"出自概念手册「含氮有机化合物」核心概念；背完后可对照该单元的可背诵版核对。","id":"rgo14_q012","chapter":"第十四章 含氮有机化合物","chapterIdx":13,"num":12},{"type":"D","stem":"名词解释：硝基化合物","answer":"烃基与硝基直接相连的化合物，可被还原为胺，硝基苯经不同条件还原可依次得到亚硝基苯、苯基羟胺和苯胺。","rationale":"出自概念手册「含氮有机化合物」核心概念；背完后可对照该单元的可背诵版核对。","id":"rgo14_q013","chapter":"第十四章 含氮有机化合物","chapterIdx":13,"num":13},{"type":"D","stem":"名词解释：苯胺","answer":"最简单的芳香伯胺，碱性弱，易被氧化而显黄色，与溴水生成2,4,6-三溴苯胺白色沉淀，是检验苯胺的灵敏反应。","rationale":"出自概念手册「含氮有机化合物」核心概念；背完后可对照该单元的可背诵版核对。","id":"rgo14_q014","chapter":"第十四章 含氮有机化合物","chapterIdx":13,"num":14},{"type":"F","stem":"填空题：最简单的芳香伯胺，碱性弱，易被氧化而显黄色，与溴水生成2,4,6-三溴______白色沉淀，是检验苯胺的灵敏反应。","answer":"苯胺","rationale":"出自概念手册「含氮有机化合物」核心概念：苯胺。","id":"rgo14_q015","chapter":"第十四章 含氮有机化合物","chapterIdx":13,"num":15},{"type":"D","stem":"名词解释：去氨基化","answer":"重氮盐与次磷酸作用，重氮基被氢原子取代生成芳烃的反应，可用于从芳环上脱除氨基，常用于先定位再移除的合成设计。","rationale":"出自概念手册「含氮有机化合物」核心概念；背完后可对照该单元的可背诵版核对。","id":"rgo14_q016","chapter":"第十四章 含氮有机化合物","chapterIdx":13,"num":16},{"type":"D","stem":"名词解释：重氮盐的水解","answer":"重氮盐在酸性水溶液中加热分解，重氮基被羟基取代生成酚的反应，可制备不能由直接硝化或磺化得到的酚。","rationale":"出自概念手册「含氮有机化合物」核心概念；背完后可对照该单元的可背诵版核对。","id":"rgo14_q017","chapter":"第十四章 含氮有机化合物","chapterIdx":13,"num":17},{"type":"S","stem":"简答题：比较脂肪胺、氨、芳香胺和酰胺的碱性强弱，并说明原因。","answer":"①碱性强弱顺序为脂肪胺 > 氨 > 芳香胺 > 酰胺。②脂肪胺中氮上连有烷基，烷基的给电子诱导效应使氮上电子云密度升高，故碱性强于氨。③芳香胺中氮的孤对电子与苯环形成 p-π 共轭而离域到环上，氮上电子云密度降低，故苯胺碱性明显弱于氨。④酰胺中氮的孤对电子与羰基强烈共轭，几乎不显碱性，其共轭酸的 pKa 约为 −1。⑤因此胺能与酸成盐而酰胺不能；在水中脂肪胺的碱性受溶剂化影响，实际顺序为仲胺 > 伯胺 > 叔胺 > 氨。","rationale":"采分点是“给电子使碱性增强、共轭使碱性减弱”这一条主线。易错点：把脂肪胺在水中的碱性顺序直接写成气相顺序（气相为叔 > 仲 > 伯 > 氨）。","id":"rgo14_q018","chapter":"第十四章 含氮有机化合物","chapterIdx":13,"num":18},{"type":"F","stem":"填空题：苯胺与溴水作用生成______色沉淀，说明氨基是______基团。","answer":"①白（生成 2,4,6-三溴苯胺沉淀） ②致活（强致活基团，故不需催化剂即可反应）","rationale":"氨基强致活并属邻对位定位基，故苯胺与溴水直接生成三溴代物。这是苯胺与苯在反应条件上的显著差别。","id":"rgo14_q019","chapter":"第十四章 含氮有机化合物","chapterIdx":13,"num":19},{"type":"F","stem":"填空题：胺与亚硝酸在低温下反应时，脂肪族伯胺放出______；芳香族伯胺生成______盐，后者在碱性条件下与 β-萘酚偶合生成橙红色染料。","answer":"①氮气（N2，可观察到气泡） ②重氮（重氮盐，可发生偶合反应）","rationale":"这一差异是区分脂肪族伯胺与芳香族伯胺的依据。重氮盐的偶合反应还可用于制备偶氮染料，并可用于检验酚类和芳香胺。","id":"rgo14_q020","chapter":"第十四章 含氮有机化合物","chapterIdx":13,"num":20},{"type":"T","stem":"判断题：苯胺的碱性比氨弱，是因为氨基的孤对电子与苯环发生 p-π 共轭而离域。","options":{"A":"正确","B":"错误"},"answer":["A"],"rationale":"共轭使氮上电子云密度降低、供电子能力减弱，故苯胺共轭酸的 pKa 约为 4.6，而氨约为 9.3。这一解释也可说明苯胺的邻对位致活作用。","id":"rgo14_q021","chapter":"第十四章 含氮有机化合物","chapterIdx":13,"num":21},{"type":"T","stem":"判断题：脂肪族伯胺与亚硝酸在低温下反应放出氮气，可用来鉴别脂肪族伯胺。","options":{"A":"正确","B":"错误"},"answer":["A"],"rationale":"芳香族伯胺在同一条件下生成重氮盐而不放出氮气，故有无气泡产生可作为鉴别依据。仲胺则生成黄色油状 N-亚硝基胺。","id":"rgo14_q022","chapter":"第十四章 含氮有机化合物","chapterIdx":13,"num":22}]},{"title":"第十五章 氨基酸、多肽、蛋白质","questions":[{"type":"D","stem":"名词解释：氨基酸","answer":"分子中同时含氨基与羧基的化合物，通式可写作RCH(NH2)COOH，按氨基与羧基的相对位置分为α、β、γ等类型，其中α-氨基酸是构成蛋白质的基本单位。","rationale":"出自概念手册「氨基酸、多肽、蛋白质」核心概念；背完后可对照该单元的可背诵版核对。","id":"rgo15_q001","chapter":"第十五章 氨基酸、多肽、蛋白质","chapterIdx":14,"num":1},{"type":"F","stem":"填空题：分子中同时含氨基与羧基的化合物，通式可写作RCH(NH2)COOH，按氨基与羧基的相对位置分为α、β、γ等类型，其中α-______是构成蛋白质的基本单位。","answer":"氨基酸","rationale":"出自概念手册「氨基酸、多肽、蛋白质」核心概念：氨基酸。","id":"rgo15_q002","chapter":"第十五章 氨基酸、多肽、蛋白质","chapterIdx":14,"num":2},{"type":"D","stem":"名词解释：α-氨基酸","answer":"氨基与羧基连接在同一个碳原子上的氨基酸，除甘氨酸外α-碳均为手性碳，天然蛋白质中的α-氨基酸几乎都是L型。","rationale":"出自概念手册「氨基酸、多肽、蛋白质」核心概念；背完后可对照该单元的可背诵版核对。","id":"rgo15_q003","chapter":"第十五章 氨基酸、多肽、蛋白质","chapterIdx":14,"num":3},{"type":"F","stem":"填空题：氨基与羧基连接在同一个碳原子上的氨基酸，除甘氨酸外α-碳均为手性碳，天然蛋白质中的______几乎都是L型。","answer":"α-氨基酸","rationale":"出自概念手册「氨基酸、多肽、蛋白质」核心概念：α-氨基酸。","id":"rgo15_q004","chapter":"第十五章 氨基酸、多肽、蛋白质","chapterIdx":14,"num":4},{"type":"D","stem":"名词解释：中性氨基酸","answer":"分子中氨基与羧基数目相等的氨基酸，如甘氨酸、丙氨酸、缬氨酸，其等电点多在5.0~6.5之间，略偏酸性。","rationale":"出自概念手册「氨基酸、多肽、蛋白质」核心概念；背完后可对照该单元的可背诵版核对。","id":"rgo15_q005","chapter":"第十五章 氨基酸、多肽、蛋白质","chapterIdx":14,"num":5},{"type":"D","stem":"名词解释：酸性氨基酸","answer":"侧链含额外羧基的氨基酸，包括天冬氨酸与谷氨酸，等电点约在3左右，在生理pH的溶液中带负电荷。","rationale":"出自概念手册「氨基酸、多肽、蛋白质」核心概念；背完后可对照该单元的可背诵版核对。","id":"rgo15_q006","chapter":"第十五章 氨基酸、多肽、蛋白质","chapterIdx":14,"num":6},{"type":"D","stem":"名词解释：碱性氨基酸","answer":"侧链含氨基、胍基或咪唑基的氨基酸，包括赖氨酸、精氨酸与组氨酸，等电点明显偏高，在生理pH的溶液中带正电荷。","rationale":"出自概念手册「氨基酸、多肽、蛋白质」核心概念；背完后可对照该单元的可背诵版核对。","id":"rgo15_q007","chapter":"第十五章 氨基酸、多肽、蛋白质","chapterIdx":14,"num":7},{"type":"D","stem":"名词解释：必需氨基酸","answer":"人体不能合成或合成量不足、必须由食物供给的氨基酸，成人有赖氨酸、甲硫氨酸、色氨酸、缬氨酸、苏氨酸、亮氨酸、异亮氨酸与苯丙氨酸八种。","rationale":"出自概念手册「氨基酸、多肽、蛋白质」核心概念；背完后可对照该单元的可背诵版核对。","id":"rgo15_q008","chapter":"第十五章 氨基酸、多肽、蛋白质","chapterIdx":14,"num":8},{"type":"D","stem":"名词解释：两性离子","answer":"又称内盐，指氨基酸在同一分子内同时含碱性氨基与酸性羧基，在等电点时以带等量正负电荷的形式存在，故熔点较高、易溶于水而难溶于有机溶剂。","rationale":"出自概念手册「氨基酸、多肽、蛋白质」核心概念；背完后可对照该单元的可背诵版核对。","id":"rgo15_q009","chapter":"第十五章 氨基酸、多肽、蛋白质","chapterIdx":14,"num":9},{"type":"D","stem":"名词解释：等电点","answer":"氨基酸所带正负电荷相等、净电荷为零时的溶液pH值，用pI表示；此时溶解度最小、电泳时不移动，中性氨基酸的pI近似为两个pKa的平均值。","rationale":"出自概念手册「氨基酸、多肽、蛋白质」核心概念；背完后可对照该单元的可背诵版核对。","id":"rgo15_q010","chapter":"第十五章 氨基酸、多肽、蛋白质","chapterIdx":14,"num":10},{"type":"D","stem":"名词解释：茚三酮反应","answer":"α-氨基酸与水合茚三酮在弱酸性溶液中加热，经氧化脱氨与脱羧生成蓝紫色化合物，灵敏度高，用于氨基酸的定性、定量与纸层析显色。","rationale":"出自概念手册「氨基酸、多肽、蛋白质」核心概念；背完后可对照该单元的可背诵版核对。","id":"rgo15_q011","chapter":"第十五章 氨基酸、多肽、蛋白质","chapterIdx":14,"num":11},{"type":"D","stem":"名词解释：甲醛滴定法","answer":"氨基酸与甲醛作用生成羟甲基衍生物，使氨基的碱性被掩蔽，再用氢氧化钠标准溶液滴定羧基，据此测定氨基酸的含量。","rationale":"出自概念手册「氨基酸、多肽、蛋白质」核心概念；背完后可对照该单元的可背诵版核对。","id":"rgo15_q012","chapter":"第十五章 氨基酸、多肽、蛋白质","chapterIdx":14,"num":12},{"type":"D","stem":"名词解释：范斯莱克反应","answer":"氨基酸的伯氨基与亚硝酸作用定量放出氮气并生成羟基酸，通过测量氮的体积求得氨基氮含量，故该法又称氨基氮测定法。","rationale":"出自概念手册「氨基酸、多肽、蛋白质」核心概念；背完后可对照该单元的可背诵版核对。","id":"rgo15_q013","chapter":"第十五章 氨基酸、多肽、蛋白质","chapterIdx":14,"num":13},{"type":"D","stem":"名词解释：氨基酸脱羧反应","answer":"氨基酸在脱羧酶或与碱石灰共热的作用下失去二氧化碳生成少一个碳的伯胺，如组氨酸生成组胺、谷氨酸生成γ-氨基丁酸。","rationale":"出自概念手册「氨基酸、多肽、蛋白质」核心概念；背完后可对照该单元的可背诵版核对。","id":"rgo15_q014","chapter":"第十五章 氨基酸、多肽、蛋白质","chapterIdx":14,"num":14},{"type":"D","stem":"名词解释：肽键","answer":"一个氨基酸的羧基与另一个氨基酸的氨基脱水缩合形成的酰胺键—CONH—，具有部分双键性质，六个原子共处一个平面而不能自由旋转。","rationale":"出自概念手册「氨基酸、多肽、蛋白质」核心概念；背完后可对照该单元的可背诵版核对。","id":"rgo15_q015","chapter":"第十五章 氨基酸、多肽、蛋白质","chapterIdx":14,"num":15},{"type":"D","stem":"名词解释：端基分析","answer":"测定肽链两端氨基酸种类与数目的方法，N端常用二硝基氟苯法、丹磺酰氯法与异硫氰酸苯酯降解法，C端常用羧肽酶法与肼解法。","rationale":"出自概念手册「氨基酸、多肽、蛋白质」核心概念；背完后可对照该单元的可背诵版核对。","id":"rgo15_q016","chapter":"第十五章 氨基酸、多肽、蛋白质","chapterIdx":14,"num":16},{"type":"D","stem":"名词解释：埃德曼降解","answer":"肽链N端氨基酸与异硫氰酸苯酯反应生成苯硫代乙内酰脲衍生物并从链上切除，可逐级重复测定肽链的氨基酸排列顺序。","rationale":"出自概念手册「氨基酸、多肽、蛋白质」核心概念；背完后可对照该单元的可背诵版核对。","id":"rgo15_q017","chapter":"第十五章 氨基酸、多肽、蛋白质","chapterIdx":14,"num":17},{"type":"D","stem":"名词解释：二硫键","answer":"两个半胱氨酸残基的巯基氧化形成的—S—S—键，可存在于同一肽链内或两条肽链之间，是稳定蛋白质空间结构的重要共价键。","rationale":"出自概念手册「氨基酸、多肽、蛋白质」核心概念；背完后可对照该单元的可背诵版核对。","id":"rgo15_q018","chapter":"第十五章 氨基酸、多肽、蛋白质","chapterIdx":14,"num":18},{"type":"D","stem":"名词解释：蛋白质一级结构","answer":"蛋白质中氨基酸的排列顺序，包括肽链数目、末端氨基酸种类与二硫键位置，由肽键与二硫键维持，是空间结构的基础。","rationale":"出自概念手册「氨基酸、多肽、蛋白质」核心概念；背完后可对照该单元的可背诵版核对。","id":"rgo15_q019","chapter":"第十五章 氨基酸、多肽、蛋白质","chapterIdx":14,"num":19},{"type":"D","stem":"名词解释：蛋白质二级结构","answer":"肽链主链局部有规律的空间盘曲，主要有α-螺旋与β-折叠，靠主链上羰基与亚氨基之间形成的氢键维持，不涉及侧链的排列。","rationale":"出自概念手册「氨基酸、多肽、蛋白质」核心概念；背完后可对照该单元的可背诵版核对。","id":"rgo15_q020","chapter":"第十五章 氨基酸、多肽、蛋白质","chapterIdx":14,"num":20},{"type":"D","stem":"名词解释：蛋白质变性","answer":"蛋白质受热、强酸碱、重金属或有机溶剂作用，二、三、四级结构被破坏而一级结构不变，表现为溶解度下降与生物活性丧失。","rationale":"出自概念手册「氨基酸、多肽、蛋白质」核心概念；背完后可对照该单元的可背诵版核对。","id":"rgo15_q021","chapter":"第十五章 氨基酸、多肽、蛋白质","chapterIdx":14,"num":21},{"type":"D","stem":"名词解释：盐析","answer":"向蛋白质溶液中加入高浓度中性盐使蛋白质析出的现象，源于盐离子破坏水化层并中和电荷，属可逆沉淀而蛋白质并未变性。","rationale":"出自概念手册「氨基酸、多肽、蛋白质」核心概念；背完后可对照该单元的可背诵版核对。","id":"rgo15_q022","chapter":"第十五章 氨基酸、多肽、蛋白质","chapterIdx":14,"num":22},{"type":"D","stem":"名词解释：电泳","answer":"带电的氨基酸或蛋白质在电场中向相反电极移动的现象，移动方向与速度取决于净电荷性质与分子大小，用于分离、纯度鉴定与分子量测定。","rationale":"出自概念手册「氨基酸、多肽、蛋白质」核心概念；背完后可对照该单元的可背诵版核对。","id":"rgo15_q023","chapter":"第十五章 氨基酸、多肽、蛋白质","chapterIdx":14,"num":23},{"type":"D","stem":"名词解释：双缩脲反应","answer":"含两个或两个以上肽键的化合物在碱性溶液中与硫酸铜生成紫红色配合物的反应，用于肽与蛋白质的定性定量，二肽不显色。","rationale":"出自概念手册「氨基酸、多肽、蛋白质」核心概念；背完后可对照该单元的可背诵版核对。","id":"rgo15_q024","chapter":"第十五章 氨基酸、多肽、蛋白质","chapterIdx":14,"num":24},{"type":"S","stem":"简答题：氨基酸为什么具有两性？说明等电点的含义及处于等电点时的性质。","answer":"①氨基酸分子中同时含有碱性的氨基和酸性的羧基，故为两性化合物。②在水溶液中氨基酸以偶极离子（内盐）形式存在，既能与酸成盐，又能与碱成盐。③等电点 pI 是使氨基酸所带正、负电荷相等、净电荷为零时的 pH，此时它在电场中既不向阴极也不向阳极迁移。④在等电点时氨基酸的溶解度最小，最易结晶析出，故可用调节 pH 至等电点的办法分离提纯氨基酸。⑤等电点由分子中两性基团的 pKa 决定：中性氨基酸的 pI 约为 5～6.5，酸性氨基酸偏低，碱性氨基酸偏高。","rationale":"采分点是“两性、内盐、净电荷为零、溶解度最小”。易错点：把 pI 说成“溶解度最大”，或忘记在电场中不迁移这一现象。","id":"rgo15_q025","chapter":"第十五章 氨基酸、多肽、蛋白质","chapterIdx":14,"num":25},{"type":"F","stem":"填空题：当溶液 pH 大于某氨基酸的等电点时，该氨基酸主要以______离子形式存在，在电场中向______极移动。","answer":"①负（阴离子，羧基去质子带负电） ②阳（正极；pH 小于 pI 时带正电，移向阴极）","rationale":"判断依据是 pH 与 pI 的比较：pH > pI 时分子给出质子带负电，pH < pI 时结合质子带正电。这一原理是电泳分离氨基酸和多肽的基础。","id":"rgo15_q026","chapter":"第十五章 氨基酸、多肽、蛋白质","chapterIdx":14,"num":26},{"type":"F","stem":"填空题：氨基酸分子间脱水形成的______键（—CO—NH—）把氨基酸连接成多肽链；测定多肽 N 端氨基酸常用______试剂。","answer":"①肽（肽键，由羧基与氨基脱水缩合形成） ②2,4-二硝基氟苯（Sanger 试剂，只与 N 端游离氨基结合）","rationale":"肽键是蛋白质的一级结构连接方式。N 端测定还可用丹磺酰氯法或 Edman 降解法，三者原理都是选择性标记游离的 α-氨基。","id":"rgo15_q027","chapter":"第十五章 氨基酸、多肽、蛋白质","chapterIdx":14,"num":27},{"type":"T","stem":"判断题：蛋白质在等电点时溶解度最大，故常用调节 pH 至等电点的方法使蛋白质析出。","options":{"A":"正确","B":"错误"},"answer":["B"],"rationale":"等电点时蛋白质分子净电荷为零，分子间静电排斥最小，故溶解度最小、最易沉淀析出。结论与理由恰好说反。","id":"rgo15_q028","chapter":"第十五章 氨基酸、多肽、蛋白质","chapterIdx":14,"num":28},{"type":"T","stem":"判断题：蛋白质的变性是指一级结构（肽键顺序）被破坏，因而不能再恢复原有活性。","options":{"A":"正确","B":"错误"},"answer":["B"],"rationale":"变性只破坏二、三、四级结构的空间构象（氢键、疏水作用、二硫键等），一级结构并不改变。去除变性因素后有的蛋白质可以复性。","id":"rgo15_q029","chapter":"第十五章 氨基酸、多肽、蛋白质","chapterIdx":14,"num":29}]},{"title":"第十六章 杂环化合物","questions":[{"type":"D","stem":"名词解释：杂环化合物","answer":"构成环的原子除碳外还含有氧、硫、氮等杂原子的环状化合物，分芳香性与非芳香性两类，广泛存在于天然产物与药物中。","rationale":"出自概念手册「杂环化合物」核心概念；背完后可对照该单元的可背诵版核对。","id":"rgo16_q001","chapter":"第十六章 杂环化合物","chapterIdx":15,"num":1},{"type":"D","stem":"名词解释：芳香性杂环","answer":"具有平面闭环共轭体系且π电子数符合休克尔4n+2规则的杂环，如吡啶、呋喃、噻吩、吡咯等，均具芳香性。","rationale":"出自概念手册「杂环化合物」核心概念；背完后可对照该单元的可背诵版核对。","id":"rgo16_q002","chapter":"第十六章 杂环化合物","chapterIdx":15,"num":2},{"type":"D","stem":"名词解释：呋喃","answer":"含一个氧原子的五元芳杂环，氧的孤对电子参与共轭故为富电子环，亲电取代在α位，遇强酸易聚合，需温和条件反应。","rationale":"出自概念手册「杂环化合物」核心概念；背完后可对照该单元的可背诵版核对。","id":"rgo16_q003","chapter":"第十六章 杂环化合物","chapterIdx":15,"num":3},{"type":"D","stem":"名词解释：噻吩","answer":"含一个硫原子的五元芳杂环，芳香性在五元杂环中最强，亲电取代在α位，可从煤焦油苯中检出，常用靛红硫酸反应检验。","rationale":"出自概念手册「杂环化合物」核心概念；背完后可对照该单元的可背诵版核对。","id":"rgo16_q004","chapter":"第十六章 杂环化合物","chapterIdx":15,"num":4},{"type":"D","stem":"名词解释：吡咯","answer":"含一个氮原子的五元芳杂环，氮的孤对电子参与芳香π体系，故几乎无碱性，亲电取代活性最高，遇酸易聚合。","rationale":"出自概念手册「杂环化合物」核心概念；背完后可对照该单元的可背诵版核对。","id":"rgo16_q005","chapter":"第十六章 杂环化合物","chapterIdx":15,"num":5},{"type":"D","stem":"名词解释：吡啶","answer":"含一个氮原子的六元芳杂环，氮的孤对电子处于sp2轨道不参与共轭故有碱性，亲电取代难而在3位，亲核取代在2、4位。","rationale":"出自概念手册「杂环化合物」核心概念；背完后可对照该单元的可背诵版核对。","id":"rgo16_q006","chapter":"第十六章 杂环化合物","chapterIdx":15,"num":6},{"type":"D","stem":"名词解释：咪唑","answer":"含两个氮原子的五元芳杂环，一个氮为吡咯型、一个为吡啶型，具碱性，是组氨酸与组胺的结构母核。","rationale":"出自概念手册「杂环化合物」核心概念；背完后可对照该单元的可背诵版核对。","id":"rgo16_q007","chapter":"第十六章 杂环化合物","chapterIdx":15,"num":7},{"type":"D","stem":"名词解释：嘧啶","answer":"含两个间位氮原子的六元芳杂环，碱性弱于吡啶，是核酸中胞嘧啶、尿嘧啶、胸腺嘧啶的母核。","rationale":"出自概念手册「杂环化合物」核心概念；背完后可对照该单元的可背诵版核对。","id":"rgo16_q008","chapter":"第十六章 杂环化合物","chapterIdx":15,"num":8},{"type":"F","stem":"填空题：含两个间位氮原子的六元芳杂环，碱性弱于吡啶，是核酸中胞______、尿嘧啶、胸腺嘧啶的母核。","answer":"嘧啶","rationale":"出自概念手册「杂环化合物」核心概念：嘧啶。","id":"rgo16_q009","chapter":"第十六章 杂环化合物","chapterIdx":15,"num":9},{"type":"D","stem":"名词解释：嘌呤","answer":"由嘧啶环与咪唑环稠合而成的杂环，是腺嘌呤与鸟嘌呤的母核，也是嘌呤类抗代谢药物的结构基础。","rationale":"出自概念手册「杂环化合物」核心概念；背完后可对照该单元的可背诵版核对。","id":"rgo16_q010","chapter":"第十六章 杂环化合物","chapterIdx":15,"num":10},{"type":"F","stem":"填空题：由嘧啶环与咪唑环稠合而成的杂环，是腺______与鸟嘌呤的母核，也是嘌呤类抗代谢药物的结构基础。","answer":"嘌呤","rationale":"出自概念手册「杂环化合物」核心概念：嘌呤。","id":"rgo16_q011","chapter":"第十六章 杂环化合物","chapterIdx":15,"num":11},{"type":"D","stem":"名词解释：吲哚","answer":"苯环与吡咯环稠合而成的杂环，亲电取代主要发生在吡咯环的3位，是色氨酸与吲哚类生物碱的母核。","rationale":"出自概念手册「杂环化合物」核心概念；背完后可对照该单元的可背诵版核对。","id":"rgo16_q012","chapter":"第十六章 杂环化合物","chapterIdx":15,"num":12},{"type":"F","stem":"填空题：苯环与吡咯环稠合而成的杂环，亲电取代主要发生在吡咯环的3位，是色氨酸与______类生物碱的母核。","answer":"吲哚","rationale":"出自概念手册「杂环化合物」核心概念：吲哚。","id":"rgo16_q013","chapter":"第十六章 杂环化合物","chapterIdx":15,"num":13},{"type":"D","stem":"名词解释：喹啉","answer":"苯环与吡啶环稠合而成的杂环，亲电取代发生在苯环的5、8位，亲核取代发生在吡啶环的2、4位，碱性弱于吡啶。","rationale":"出自概念手册「杂环化合物」核心概念；背完后可对照该单元的可背诵版核对。","id":"rgo16_q014","chapter":"第十六章 杂环化合物","chapterIdx":15,"num":14},{"type":"D","stem":"名词解释：杂环芳香性的判断","answer":"判断杂环有无芳香性需同时满足三点：环为平面闭环共轭体系、每个成环原子都有p轨道、参与共轭的π电子数符合4n+2，其中杂原子可提供一对孤对电子。","rationale":"出自概念手册「杂环化合物」核心概念；背完后可对照该单元的可背诵版核对。","id":"rgo16_q015","chapter":"第十六章 杂环化合物","chapterIdx":15,"num":15},{"type":"D","stem":"名词解释：富电子杂环","answer":"杂原子的孤对电子参与共轭，使环上电子云密度高于苯的杂环，如呋喃、吡咯、噻吩，亲电取代活性大于苯。","rationale":"出自概念手册「杂环化合物」核心概念；背完后可对照该单元的可背诵版核对。","id":"rgo16_q016","chapter":"第十六章 杂环化合物","chapterIdx":15,"num":16},{"type":"D","stem":"名词解释：缺电子杂环","answer":"杂原子的孤对电子不参与共轭且氮的电负性使环上电子云密度低于苯的杂环，如吡啶，亲电取代难而亲核取代易。","rationale":"出自概念手册「杂环化合物」核心概念；背完后可对照该单元的可背诵版核对。","id":"rgo16_q017","chapter":"第十六章 杂环化合物","chapterIdx":15,"num":17},{"type":"D","stem":"名词解释：吡啶的亲核取代","answer":"吡啶环上2位和4位的电子云密度最低，易受亲核试剂进攻，如与氨基钠作用生成2-氨基吡啶。","rationale":"出自概念手册「杂环化合物」核心概念；背完后可对照该单元的可背诵版核对。","id":"rgo16_q018","chapter":"第十六章 杂环化合物","chapterIdx":15,"num":18},{"type":"D","stem":"名词解释：烟酸","answer":"即吡啶-3-甲酸，又称尼克酸，属B族维生素，其酰胺为烟酰胺，是辅酶Ⅰ与辅酶Ⅱ的组成部分，临床用于防治糙皮病。","rationale":"出自概念手册「杂环化合物」核心概念；背完后可对照该单元的可背诵版核对。","id":"rgo16_q019","chapter":"第十六章 杂环化合物","chapterIdx":15,"num":19},{"type":"S","stem":"简答题：比较吡啶与吡咯的碱性和芳香性差异，并说明原因。","answer":"①吡啶中氮为 sp2 杂化，其孤对电子处于环平面内的 sp2 轨道上，不参与 π 体系，故能接受质子而显碱性，共轭酸 pKa 约 5.2。②吡咯中氮的孤对电子必须参与构成 6π 电子的芳香体系，若接受质子则芳香性被破坏，故碱性极弱，共轭酸 pKa 约为 −3.8，遇强酸反而聚合成树脂。③吡咯的芳香性比吡啶强：吡咯的 6 个 π 电子由 4 个碳各提供 1 个、氮提供 2 个，属富电子芳环。④吡啶的 6 个 π 电子由 5 个碳和 1 个氮各提供 1 个，氮的电负性使环上电子云密度降低，属缺电子芳环。⑤因此吡啶较难发生亲电取代而较易发生亲核取代，吡咯则易发生亲电取代。","rationale":"采分点是“孤对电子是否参与 π 体系”决定碱性，“环上电子云密度高低”决定反应类型。易错点：认为含氮杂环一定显碱性。","id":"rgo16_q020","chapter":"第十六章 杂环化合物","chapterIdx":15,"num":20},{"type":"F","stem":"填空题：呋喃、吡咯、噻吩都是五元杂环，环上的杂原子分别是______、______、______；它们各有 6 个 π 电子，符合______规则而具有芳香性。","answer":"①氧 ②氮 ③硫 ④休克尔（Hückel 的 4n+2 规则，此处 n=1）","rationale":"三个杂环中杂原子均以 sp2 杂化，孤对电子参与 π 体系。杂原子电负性越小、给出孤对电子越容易，芳香性越强，故芳香性为苯 > 噻吩 > 吡咯 > 呋喃。","id":"rgo16_q021","chapter":"第十六章 杂环化合物","chapterIdx":15,"num":21},{"type":"F","stem":"填空题：吡啶属于______元含氮单杂环；吲哚可看作苯与______稠合而成的稠杂环。","answer":"①六（六元杂环，环上 5 个碳 1 个氮） ②吡咯（吲哚即苯并吡咯；喹啉则为苯并吡啶）","rationale":"杂环按环的元数分五元环和六元环，按是否与苯环并合分单杂环与稠杂环。吲哚、喹啉、嘌呤都是重要的稠杂环。","id":"rgo16_q022","chapter":"第十六章 杂环化合物","chapterIdx":15,"num":22},{"type":"T","stem":"判断题：吡咯的碱性比吡啶强，因为吡咯分子中氮原子上有一对孤对电子。","options":{"A":"正确","B":"错误"},"answer":["B"],"rationale":"吡咯的孤对电子已参与芳香 π 体系，接受质子即破坏芳香性，故碱性远弱于吡啶。有孤对电子并不等于能作碱，关键看它是否参与共轭。","id":"rgo16_q023","chapter":"第十六章 杂环化合物","chapterIdx":15,"num":23},{"type":"T","stem":"判断题：吡啶发生亲电取代反应比苯容易，新取代基主要进入 3 位。","options":{"A":"正确","B":"错误"},"answer":["B"],"rationale":"氮的吸电子作用使环上电子云密度降低，故吡啶的亲电取代比苯难，且主要进入 3 位；它更易发生的是亲核取代（主要在 2、4 位）。","id":"rgo16_q024","chapter":"第十六章 杂环化合物","chapterIdx":15,"num":24}]},{"title":"第十七章 糖类化合物","questions":[{"type":"D","stem":"名词解释：糖类","answer":"多羟基醛、多羟基酮及其缩合产物与衍生物的总称，曾称碳水化合物，按能否水解及水解产物多少分为单糖、低聚糖与多糖。","rationale":"出自概念手册「糖类化合物」核心概念；背完后可对照该单元的可背诵版核对。","id":"rgo17_q001","chapter":"第十七章 糖类化合物","chapterIdx":16,"num":1},{"type":"D","stem":"名词解释：单糖","answer":"不能水解成更小分子的糖，如葡萄糖、果糖、核糖，含多个手性碳，具旋光性与变旋现象，在水溶液中主要以环状半缩醛或半缩酮形式存在。","rationale":"出自概念手册「糖类化合物」核心概念；背完后可对照该单元的可背诵版核对。","id":"rgo17_q002","chapter":"第十七章 糖类化合物","chapterIdx":16,"num":2},{"type":"D","stem":"名词解释：低聚糖","answer":"水解后生成二至十个单糖分子的糖，以二糖最常见，如蔗糖、麦芽糖、乳糖，其还原性取决于分子中是否存在游离的半缩醛羟基。","rationale":"出自概念手册「糖类化合物」核心概念；背完后可对照该单元的可背诵版核对。","id":"rgo17_q003","chapter":"第十七章 糖类化合物","chapterIdx":16,"num":3},{"type":"D","stem":"名词解释：多糖","answer":"水解后生成多个单糖分子的高分子糖，如淀粉、糖原、纤维素，无还原性与变旋现象，不溶于水或形成胶体溶液。","rationale":"出自概念手册「糖类化合物」核心概念；背完后可对照该单元的可背诵版核对。","id":"rgo17_q004","chapter":"第十七章 糖类化合物","chapterIdx":16,"num":4},{"type":"D","stem":"名词解释：醛糖与酮糖","answer":"按羰基类型对单糖的分类，含醛基者为醛糖，含酮基者为酮糖；己醛糖有四个手性碳、十六个旋光异构体，己酮糖有三个手性碳、八个旋光异构体。","rationale":"出自概念手册「糖类化合物」核心概念；背完后可对照该单元的可背诵版核对。","id":"rgo17_q005","chapter":"第十七章 糖类化合物","chapterIdx":16,"num":5},{"type":"D","stem":"名词解释：D、L构型","answer":"单糖的开链式以编号最大的手性碳上羟基的朝向确定构型，向右为D型、向左为L型；天然单糖多为D型，与D-甘油醛相关联。","rationale":"出自概念手册「糖类化合物」核心概念；背完后可对照该单元的可背诵版核对。","id":"rgo17_q006","chapter":"第十七章 糖类化合物","chapterIdx":16,"num":6},{"type":"D","stem":"名词解释：环状半缩醛结构","answer":"单糖分子内羟基与羰基发生加成形成的环状结构，六元环称吡喃型、五元环称呋喃型，D-葡萄糖在水溶液中主要以吡喃型存在。","rationale":"出自概念手册「糖类化合物」核心概念；背完后可对照该单元的可背诵版核对。","id":"rgo17_q007","chapter":"第十七章 糖类化合物","chapterIdx":16,"num":7},{"type":"D","stem":"名词解释：端基碳","answer":"单糖成环后由羰基碳转变而来的手性碳，又称异头碳，其上的羟基称半缩醛羟基，与C5上羟甲基同侧者为β型、异侧者为α型。","rationale":"出自概念手册「糖类化合物」核心概念；背完后可对照该单元的可背诵版核对。","id":"rgo17_q008","chapter":"第十七章 糖类化合物","chapterIdx":16,"num":8},{"type":"D","stem":"名词解释：哈沃斯透视式","answer":"把环状单糖画成近似平面的多边形以表示各碳上取代基上下位置的结构式，六元环中氧原子位于右上角、C1在右侧，据此可判断α与β构型。","rationale":"出自概念手册「糖类化合物」核心概念；背完后可对照该单元的可背诵版核对。","id":"rgo17_q009","chapter":"第十七章 糖类化合物","chapterIdx":16,"num":9},{"type":"D","stem":"名词解释：构象式","answer":"表示环状单糖真实空间形状的式子，吡喃型葡萄糖以椅式构象最稳定，D-葡萄糖的优势构象为较大基团处于平伏键的4C1构象。","rationale":"出自概念手册「糖类化合物」核心概念；背完后可对照该单元的可背诵版核对。","id":"rgo17_q010","chapter":"第十七章 糖类化合物","chapterIdx":16,"num":10},{"type":"D","stem":"名词解释：变旋现象","answer":"单糖溶于水后比旋光度随时间改变并趋于恒定值的现象，源于α、β端基异构体通过开链式互相转化并达到动态平衡。","rationale":"出自概念手册「糖类化合物」核心概念；背完后可对照该单元的可背诵版核对。","id":"rgo17_q011","chapter":"第十七章 糖类化合物","chapterIdx":16,"num":11},{"type":"D","stem":"名词解释：还原糖","answer":"含游离半缩醛或半缩酮羟基、能还原托伦试剂与斐林试剂的糖，如葡萄糖、麦芽糖、乳糖；蔗糖因两个端基都成苷而无还原性。","rationale":"出自概念手册「糖类化合物」核心概念；背完后可对照该单元的可背诵版核对。","id":"rgo17_q012","chapter":"第十七章 糖类化合物","chapterIdx":16,"num":12},{"type":"D","stem":"名词解释：糖脎","answer":"单糖与过量苯肼加热生成的黄色结晶状衍生物，反应发生在C1与C2上，葡萄糖、果糖与甘露糖生成同一种糖脎，可据此鉴别与分离。","rationale":"出自概念手册「糖类化合物」核心概念；背完后可对照该单元的可背诵版核对。","id":"rgo17_q013","chapter":"第十七章 糖类化合物","chapterIdx":16,"num":13},{"type":"F","stem":"填空题：单糖与过量苯肼加热生成的黄色结晶状衍生物，反应发生在C1与C2上，葡萄糖、果糖与甘露糖生成同一种______，可据此鉴别与分离。","answer":"糖脎","rationale":"出自概念手册「糖类化合物」核心概念：糖脎。","id":"rgo17_q014","chapter":"第十七章 糖类化合物","chapterIdx":16,"num":14},{"type":"D","stem":"名词解释：糖苷","answer":"单糖的半缩醛羟基与醇、酚等含羟基化合物缩合生成的产物，苷键属缩醛结构，故糖苷无变旋现象、无还原性，在碱性中稳定而可被酸或酶水解。","rationale":"出自概念手册「糖类化合物」核心概念；背完后可对照该单元的可背诵版核对。","id":"rgo17_q015","chapter":"第十七章 糖类化合物","chapterIdx":16,"num":15},{"type":"F","stem":"填空题：单糖的半缩醛羟基与醇、酚等含羟基化合物缩合生成的产物，苷键属缩醛结构，故______无变旋现象、无还原性，在碱性中稳定而可被酸或酶水解。","answer":"糖苷","rationale":"出自概念手册「糖类化合物」核心概念：糖苷。","id":"rgo17_q016","chapter":"第十七章 糖类化合物","chapterIdx":16,"num":16},{"type":"D","stem":"名词解释：苷键","answer":"连接糖基与另一分子的缩醛键，由半缩醛羟基与羟基脱水形成，按立体化学分为α-苷键与β-苷键，按两端碳位分为1,2、1,4、1,6等类型。","rationale":"出自概念手册「糖类化合物」核心概念；背完后可对照该单元的可背诵版核对。","id":"rgo17_q017","chapter":"第十七章 糖类化合物","chapterIdx":16,"num":17},{"type":"F","stem":"填空题：连接糖基与另一分子的缩醛键，由半缩醛羟基与羟基脱水形成，按立体化学分为α-______与β-苷键，按两端碳位分为1,2、1,4、1,6等类型。","answer":"苷键","rationale":"出自概念手册「糖类化合物」核心概念：苷键。","id":"rgo17_q018","chapter":"第十七章 糖类化合物","chapterIdx":16,"num":18},{"type":"D","stem":"名词解释：糖酸与糖二酸","answer":"醛糖被溴水等弱氧化剂氧化生成糖酸，被稀硝酸等较强氧化剂氧化则首尾两端都被氧化生成糖二酸，如葡萄糖生成葡萄糖二酸。","rationale":"出自概念手册「糖类化合物」核心概念；背完后可对照该单元的可背诵版核对。","id":"rgo17_q019","chapter":"第十七章 糖类化合物","chapterIdx":16,"num":19},{"type":"D","stem":"名词解释：糖醛酸","answer":"单糖的伯醇基被氧化为羧基所生成的糖酸，如葡萄糖醛酸，在肝内可与毒物或药物结合而解毒并促进其排出，是重要的解毒与排毒形式。","rationale":"出自概念手册「糖类化合物」核心概念；背完后可对照该单元的可背诵版核对。","id":"rgo17_q020","chapter":"第十七章 糖类化合物","chapterIdx":16,"num":20},{"type":"F","stem":"填空题：单糖的伯醇基被氧化为羧基所生成的糖酸，如葡萄______，在肝内可与毒物或药物结合而解毒并促进其排出，是重要的解毒与排毒形式。","answer":"糖醛酸","rationale":"出自概念手册「糖类化合物」核心概念：糖醛酸。","id":"rgo17_q021","chapter":"第十七章 糖类化合物","chapterIdx":16,"num":21},{"type":"D","stem":"名词解释：糖醇","answer":"单糖的羰基被还原为羟基所生成的多元醇，如葡萄糖还原得山梨醇、甘露糖还原得甘露醇、木糖还原得木糖醇，多用作甜味剂与渗透性利尿药。","rationale":"出自概念手册「糖类化合物」核心概念；背完后可对照该单元的可背诵版核对。","id":"rgo17_q022","chapter":"第十七章 糖类化合物","chapterIdx":16,"num":22},{"type":"F","stem":"填空题：单糖的羰基被还原为羟基所生成的多元醇，如葡萄糖还原得山梨醇、甘露糖还原得甘露醇、木糖还原得木______，多用作甜味剂与渗透性利尿药。","answer":"糖醇","rationale":"出自概念手册「糖类化合物」核心概念：糖醇。","id":"rgo17_q023","chapter":"第十七章 糖类化合物","chapterIdx":16,"num":23},{"type":"D","stem":"名词解释：淀粉","answer":"多个葡萄糖以α-苷键连接成的多糖，分直链淀粉与支链淀粉，前者以α-1,4-苷键连接遇碘显蓝色，后者另有α-1,6-分支遇碘显紫红色。","rationale":"出自概念手册「糖类化合物」核心概念；背完后可对照该单元的可背诵版核对。","id":"rgo17_q024","chapter":"第十七章 糖类化合物","chapterIdx":16,"num":24},{"type":"F","stem":"填空题：多个葡萄糖以α-苷键连接成的多糖，分直链______与支链淀粉，前者以α-1,4-苷键连接遇碘显蓝色，后者另有α-1,6-分支遇碘显紫红色。","answer":"淀粉","rationale":"出自概念手册「糖类化合物」核心概念：淀粉。","id":"rgo17_q025","chapter":"第十七章 糖类化合物","chapterIdx":16,"num":25},{"type":"D","stem":"名词解释：糖原","answer":"动物体内贮存的多糖，由葡萄糖以α-1,4-苷键连接并含比支链淀粉更多的α-1,6-分支，遇碘显红褐色，彻底水解最终生成葡萄糖。","rationale":"出自概念手册「糖类化合物」核心概念；背完后可对照该单元的可背诵版核对。","id":"rgo17_q026","chapter":"第十七章 糖类化合物","chapterIdx":16,"num":26},{"type":"D","stem":"名词解释：纤维素","answer":"由葡萄糖以β-1,4-苷键连接成的直链多糖，链间氢键使其成为纤维状，人体缺少β-葡萄糖苷酶故不能消化利用，但可促进肠蠕动。","rationale":"出自概念手册「糖类化合物」核心概念；背完后可对照该单元的可背诵版核对。","id":"rgo17_q027","chapter":"第十七章 糖类化合物","chapterIdx":16,"num":27},{"type":"D","stem":"名词解释：环糊精","answer":"淀粉经环糊精葡萄糖基转移酶作用生成的环状低聚糖，由六至八个葡萄糖以α-1,4-苷键构成，外壁亲水、内腔疏水，可包合药物而增溶、稳定与掩味。","rationale":"出自概念手册「糖类化合物」核心概念；背完后可对照该单元的可背诵版核对。","id":"rgo17_q028","chapter":"第十七章 糖类化合物","chapterIdx":16,"num":28},{"type":"F","stem":"填空题：淀粉经______葡萄糖基转移酶作用生成的环状低聚糖，由六至八个葡萄糖以α-1,4-苷键构成，外壁亲水、内腔疏水，可包合药物而增溶、稳定与掩味。","answer":"环糊精","rationale":"出自概念手册「糖类化合物」核心概念：环糊精。","id":"rgo17_q029","chapter":"第十七章 糖类化合物","chapterIdx":16,"num":29},{"type":"S","stem":"简答题：什么是还原糖？以葡萄糖为例说明单糖的结构特点与主要化学性质。","answer":"①还原糖是能还原托伦试剂和斐林试剂的糖，其结构特征是含有游离的苷羟基（半缩醛羟基），如葡萄糖、果糖、麦芽糖；蔗糖无苷羟基故不具还原性。②葡萄糖是多羟基醛（醛糖），含 1 个醛基和 5 个羟基，有 4 个手性碳，故有 16 个旋光异构体（2^4）。③在水溶液中葡萄糖以环状半缩醛形式存在，形成 α 和 β 两种端基异构体，二者通过开链式相互转化，故有变旋现象。④可被托伦试剂、斐林试剂氧化，分别生成银镜和砖红色氧化亚铜沉淀。⑤与苯肼反应生成黄色的糖脎，可用于鉴定；被溴水氧化成葡萄糖酸，被硝酸氧化成葡萄糖二酸。","rationale":"采分点是“含苷羟基故有还原性”，再补“变旋现象、成脎反应、成脎只涉及 C1 与 C2”。易错点：把果糖当成非还原糖。","id":"rgo17_q030","chapter":"第十七章 糖类化合物","chapterIdx":16,"num":30},{"type":"F","stem":"填空题：蔗糖水解生成一分子______和一分子______，水解后的产物具有还原性。","answer":"①葡萄糖 ②果糖（水解后所得等量混合物称转化糖，具还原性）","rationale":"蔗糖是非还原性二糖，因两个端基碳都参与成苷。麦芽糖、乳糖有一个游离苷羟基，故属还原性二糖。","id":"rgo17_q031","chapter":"第十七章 糖类化合物","chapterIdx":16,"num":31},{"type":"F","stem":"填空题：淀粉遇碘显______色；淀粉在酸或酶作用下逐步水解，最终产物是______。","answer":"①蓝（直链淀粉的螺旋空腔包合碘分子而显蓝色） ②葡萄糖（中间产物为糊精和麦芽糖）","rationale":"淀粉是葡萄糖的缩聚物，水解是逐步进行的，故可用碘液检验水解程度。纤维素虽也由葡萄糖组成，但以 β-1,4-苷键连接，人体不能消化。","id":"rgo17_q032","chapter":"第十七章 糖类化合物","chapterIdx":16,"num":32},{"type":"T","stem":"判断题：果糖是酮糖，分子中没有醛基，因此不能还原托伦试剂。","options":{"A":"正确","B":"错误"},"answer":["B"],"rationale":"果糖在碱性条件下可经烯醇化异构化为葡萄糖和甘露糖，故仍能还原托伦试剂和斐林试剂，属于还原糖。判断还原性看有无苷羟基而非看醛基。","id":"rgo17_q033","chapter":"第十七章 糖类化合物","chapterIdx":16,"num":33},{"type":"T","stem":"判断题：葡萄糖与果糖互为同分异构体，二者与苯肼反应生成同一种糖脎。","options":{"A":"正确","B":"错误"},"answer":["A"],"rationale":"二者分子式同为 C6H12O6，故互为同分异构体。成脎反应只涉及 C1 和 C2，C3 以下构型相同的糖生成同一种糖脎，故葡萄糖、果糖、甘露糖生成同一糖脎。","id":"rgo17_q034","chapter":"第十七章 糖类化合物","chapterIdx":16,"num":34}]},{"title":"第十八章 萜类和甾体化合物","questions":[{"type":"D","stem":"名词解释：萜类化合物","answer":"由异戊二烯单位构成的天然烃类及其含氧衍生物，广泛存在于植物的挥发油中，如薄荷醇、樟脑、柠檬烯与紫杉醇。","rationale":"出自概念手册「萜类和甾体化合物」核心概念；背完后可对照该单元的可背诵版核对。","id":"rgo18_q001","chapter":"第十八章 萜类和甾体化合物","chapterIdx":17,"num":1},{"type":"D","stem":"名词解释：异戊二烯单位","answer":"萜类分子中反复出现的五碳结构单元，其碳骨架相当于2-甲基-1,3-丁二烯，各单位之间多以头尾方式相连。","rationale":"出自概念手册「萜类和甾体化合物」核心概念；背完后可对照该单元的可背诵版核对。","id":"rgo18_q002","chapter":"第十八章 萜类和甾体化合物","chapterIdx":17,"num":2},{"type":"D","stem":"名词解释：异戊二烯规则","answer":"萜类分子的碳骨架可划分为整数个异戊二烯单位并以头尾方式连接，据此可由碳原子数推断其所属的类别。","rationale":"出自概念手册「萜类和甾体化合物」核心概念；背完后可对照该单元的可背诵版核对。","id":"rgo18_q003","chapter":"第十八章 萜类和甾体化合物","chapterIdx":17,"num":3},{"type":"D","stem":"名词解释：单萜","answer":"含两个异戊二烯单位、共十个碳原子的萜类，分无环、单环与双环三类，是挥发油的主要成分，如薄荷醇、樟脑、桉油精与柠檬烯。","rationale":"出自概念手册「萜类和甾体化合物」核心概念；背完后可对照该单元的可背诵版核对。","id":"rgo18_q004","chapter":"第十八章 萜类和甾体化合物","chapterIdx":17,"num":4},{"type":"D","stem":"名词解释：倍半萜","answer":"含三个异戊二烯单位、共十五个碳原子的萜类，如金合欢醇、山道年与青蒿素，其中青蒿素为含过氧桥的倍半萜内酯。","rationale":"出自概念手册「萜类和甾体化合物」核心概念；背完后可对照该单元的可背诵版核对。","id":"rgo18_q005","chapter":"第十八章 萜类和甾体化合物","chapterIdx":17,"num":5},{"type":"F","stem":"填空题：含三个异戊二烯单位、共十五个碳原子的萜类，如金合欢醇、山道年与青蒿素，其中青蒿素为含过氧桥的______内酯。","answer":"倍半萜","rationale":"出自概念手册「萜类和甾体化合物」核心概念：倍半萜。","id":"rgo18_q006","chapter":"第十八章 萜类和甾体化合物","chapterIdx":17,"num":6},{"type":"D","stem":"名词解释：二萜","answer":"含四个异戊二烯单位、共二十个碳原子的萜类，如维生素A、紫杉醇与丹参酮，多具有重要的生理活性与药用价值。","rationale":"出自概念手册「萜类和甾体化合物」核心概念；背完后可对照该单元的可背诵版核对。","id":"rgo18_q007","chapter":"第十八章 萜类和甾体化合物","chapterIdx":17,"num":7},{"type":"D","stem":"名词解释：三萜","answer":"含六个异戊二烯单位、共三十个碳原子的萜类，角鲨烯是其生物合成前体，甘草次酸与齐墩果酸属此类，多形成皂苷。","rationale":"出自概念手册「萜类和甾体化合物」核心概念；背完后可对照该单元的可背诵版核对。","id":"rgo18_q008","chapter":"第十八章 萜类和甾体化合物","chapterIdx":17,"num":8},{"type":"D","stem":"名词解释：四萜","answer":"含八个异戊二烯单位、共四十个碳原子的萜类，多具长共轭多烯结构而显色，如β-胡萝卜素与番茄红素。","rationale":"出自概念手册「萜类和甾体化合物」核心概念；背完后可对照该单元的可背诵版核对。","id":"rgo18_q009","chapter":"第十八章 萜类和甾体化合物","chapterIdx":17,"num":9},{"type":"D","stem":"名词解释：挥发油","answer":"又称精油，为植物中具有挥发性与芳香气味的油状物，主要成分为单萜与倍半萜及其含氧衍生物，可用水蒸气蒸馏法提取。","rationale":"出自概念手册「萜类和甾体化合物」核心概念；背完后可对照该单元的可背诵版核对。","id":"rgo18_q010","chapter":"第十八章 萜类和甾体化合物","chapterIdx":17,"num":10},{"type":"D","stem":"名词解释：薄荷醇","answer":"单环单萜醇，学名2-异丙基-5-甲基环己醇，含三个手性碳而有八个立体异构体，天然品为左旋体，具清凉香气与止痒作用。","rationale":"出自概念手册「萜类和甾体化合物」核心概念；背完后可对照该单元的可背诵版核对。","id":"rgo18_q011","chapter":"第十八章 萜类和甾体化合物","chapterIdx":17,"num":11},{"type":"D","stem":"名词解释：樟脑","answer":"双环单萜酮，学名1,7,7-三甲基双环[2.2.1]庚-2-酮，含两个手性碳，易升华，天然品为右旋体，有局部刺激与兴奋强心作用。","rationale":"出自概念手册「萜类和甾体化合物」核心概念；背完后可对照该单元的可背诵版核对。","id":"rgo18_q012","chapter":"第十八章 萜类和甾体化合物","chapterIdx":17,"num":12},{"type":"D","stem":"名词解释：桉油精","answer":"单环单萜的环醚，学名1,8-环氧对孟烷，为桉叶油的主要成分，具祛痰、防腐与清凉作用。","rationale":"出自概念手册「萜类和甾体化合物」核心概念；背完后可对照该单元的可背诵版核对。","id":"rgo18_q013","chapter":"第十八章 萜类和甾体化合物","chapterIdx":17,"num":13},{"type":"D","stem":"名词解释：紫杉醇","answer":"红豆杉中的紫杉烷型二萜，能促进微管蛋白聚合并抑制其解聚，使细胞停止于有丝分裂期，是治疗卵巢癌与乳腺癌的重要药物。","rationale":"出自概念手册「萜类和甾体化合物」核心概念；背完后可对照该单元的可背诵版核对。","id":"rgo18_q014","chapter":"第十八章 萜类和甾体化合物","chapterIdx":17,"num":14},{"type":"D","stem":"名词解释：维生素A","answer":"二萜类化合物，由β-紫罗兰酮环、共轭多烯侧链与伯醇基构成，视黄醇为主要形式，缺乏时引起夜盲症与干眼病。","rationale":"出自概念手册「萜类和甾体化合物」核心概念；背完后可对照该单元的可背诵版核对。","id":"rgo18_q015","chapter":"第十八章 萜类和甾体化合物","chapterIdx":17,"num":15},{"type":"D","stem":"名词解释：甾体化合物","answer":"含环戊烷多氢菲骨架的天然产物及其衍生物，包括胆固醇、胆汁酸、性激素、肾上腺皮质激素与强心苷等。","rationale":"出自概念手册「萜类和甾体化合物」核心概念；背完后可对照该单元的可背诵版核对。","id":"rgo18_q016","chapter":"第十八章 萜类和甾体化合物","chapterIdx":17,"num":16},{"type":"D","stem":"名词解释：环戊烷多氢菲","answer":"由三个六元环与一个五元环稠合而成的四环骨架，是甾体化合物的共同母核，四个环依次标记为A、B、C、D。","rationale":"出自概念手册「萜类和甾体化合物」核心概念；背完后可对照该单元的可背诵版核对。","id":"rgo18_q017","chapter":"第十八章 萜类和甾体化合物","chapterIdx":17,"num":17},{"type":"D","stem":"名词解释：甾体的α、β构型","answer":"甾体环上取代基的立体取向用α与β表示，β表示基团位于环平面之上、α表示位于环平面之下，天然甾体多为β构型。","rationale":"出自概念手册「萜类和甾体化合物」核心概念；背完后可对照该单元的可背诵版核对。","id":"rgo18_q018","chapter":"第十八章 萜类和甾体化合物","chapterIdx":17,"num":18},{"type":"D","stem":"名词解释：胆固醇","answer":"含二十七个碳的甾体，C3有β-羟基、C5与C6间有双键、C17连异辛基侧链，是动物细胞膜的成分及胆汁酸、维生素D与甾体激素的前体。","rationale":"出自概念手册「萜类和甾体化合物」核心概念；背完后可对照该单元的可背诵版核对。","id":"rgo18_q019","chapter":"第十八章 萜类和甾体化合物","chapterIdx":17,"num":19},{"type":"D","stem":"名词解释：胆酸","answer":"含二十四个碳的胆甾烷酸，C3、C7、C12上有α-羟基、侧链末端为羧基，与甘氨酸或牛磺酸结合成胆汁酸，起乳化脂肪促进吸收的作用。","rationale":"出自概念手册「萜类和甾体化合物」核心概念；背完后可对照该单元的可背诵版核对。","id":"rgo18_q020","chapter":"第十八章 萜类和甾体化合物","chapterIdx":17,"num":20},{"type":"D","stem":"名词解释：肾上腺皮质激素","answer":"肾上腺皮质分泌的甾体激素，含二十一个碳，C17有—COCH2OH侧链，可的松与氢化可的松影响糖代谢，醛固酮调节水盐代谢。","rationale":"出自概念手册「萜类和甾体化合物」核心概念；背完后可对照该单元的可背诵版核对。","id":"rgo18_q021","chapter":"第十八章 萜类和甾体化合物","chapterIdx":17,"num":21},{"type":"D","stem":"名词解释：强心苷","answer":"甾体苷元与糖结合而成的苷类，苷元C17连五元不饱和内酯环、C14有β-羟基，能增强心肌收缩力，如洋地黄毒苷与地高辛。","rationale":"出自概念手册「萜类和甾体化合物」核心概念；背完后可对照该单元的可背诵版核对。","id":"rgo18_q022","chapter":"第十八章 萜类和甾体化合物","chapterIdx":17,"num":22},{"type":"D","stem":"名词解释：甾体皂苷","answer":"苷元为甾体骨架的皂苷，多含螺缩酮结构，如薯蓣皂苷元，是合成甾体激素的重要原料，其水溶液振摇产生持久泡沫并有溶血作用。","rationale":"出自概念手册「萜类和甾体化合物」核心概念；背完后可对照该单元的可背诵版核对。","id":"rgo18_q023","chapter":"第十八章 萜类和甾体化合物","chapterIdx":17,"num":23},{"type":"D","stem":"名词解释：性激素","answer":"由性腺分泌的甾体激素，包括雄激素如睾酮、雌激素如雌二醇与孕激素如黄体酮，分别含十九、十八与二十一个碳。","rationale":"出自概念手册「萜类和甾体化合物」核心概念；背完后可对照该单元的可背诵版核对。","id":"rgo18_q024","chapter":"第十八章 萜类和甾体化合物","chapterIdx":17,"num":24},{"type":"S","stem":"简答题：什么是萜类化合物？说明其结构单位与分类。","answer":"①萜类是天然存在的、由异戊二烯（2-甲基-1,3-丁二烯）单位首尾相连而成的烃类及其含氧衍生物，广泛存在于挥发油中。②其结构单位是异戊二烯，分子中碳原子数一般为 5 的整数倍，且可划分成若干个异戊二烯单位，这一规律称为异戊二烯规则。③按异戊二烯单位数分为半萜（1 个单元，5 碳）、单萜（2 个，10 碳）、倍半萜（3 个，15 碳）、二萜（4 个，20 碳）、二倍半萜、三萜（6 个，30 碳）和四萜（8 个，40 碳）。④按碳骨架是否成环分为开链萜和环萜，环萜又分为单环、双环等。⑤单萜是挥发油的主要成分，如薄荷醇、樟脑；二萜如维生素 A；四萜如胡萝卜素。","rationale":"采分点是“异戊二烯单位 + 碳数为 5 的整数倍 + 单萜、倍半萜、二萜的碳数”。易错点：把三萜（30 碳）与三倍半萜混淆。","id":"rgo18_q025","chapter":"第十八章 萜类和甾体化合物","chapterIdx":17,"num":25},{"type":"F","stem":"填空题：甾体化合物的基本骨架是______，它由三个六元环（A、B、C）和一个五元环（D）稠合而成；甾体分子在 C10 和 C13 上常连有______。","answer":"①环戊烷多氢菲 ②甲基（即角甲基，是甾体骨架的特征标志）","rationale":"甾体的“甾”字形象地表示四个环和两个角甲基。天然甾体多在 C3 上有羟基，并具特定的立体构型（β 型）。","id":"rgo18_q026","chapter":"第十八章 萜类和甾体化合物","chapterIdx":17,"num":26},{"type":"F","stem":"填空题：胆汁酸中含量最高的胆酸属于______类化合物；胆固醇分子在 C3 上连有一个______基。","answer":"①甾体（胆酸为甾体胆汁酸，以与甘氨酸或牛磺酸结合的形式存在） ②羟基（β-羟基，C5—C6 间还有双键）","rationale":"胆固醇为 C27 的甾醇，结构特征为 C3 有 β-羟基、C5—C6 有双键、C17 有异辛基侧链。胆汁酸由胆固醇在肝内转化生成。","id":"rgo18_q027","chapter":"第十八章 萜类和甾体化合物","chapterIdx":17,"num":27},{"type":"T","stem":"判断题：单萜由两个异戊二烯单位构成，共含 10 个碳原子。","options":{"A":"正确","B":"错误"},"answer":["A"],"rationale":"异戊二烯单位含 5 个碳，故单萜为 10 碳、倍半萜 15 碳、二萜 20 碳、三萜 30 碳、四萜 40 碳，均为 5 的整数倍。","id":"rgo18_q028","chapter":"第十八章 萜类和甾体化合物","chapterIdx":17,"num":28},{"type":"T","stem":"判断题：萜类化合物的碳原子数都是 5 的整数倍，这一规律称为异戊二烯规则。","options":{"A":"正确","B":"错误"},"answer":["A"],"rationale":"异戊二烯规则表明萜类由异戊二烯单位首尾连接而成，故碳数为 5 的整数倍。少数萜类因降解或重排而不严格符合，属例外情况。","id":"rgo18_q029","chapter":"第十八章 萜类和甾体化合物","chapterIdx":17,"num":29}]}]};
